INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8c5ff60d0229', 'en', 'US', '15 Minute Sausage Meatballs', 'Recipe video above. Save this one for those really busy nights: just chop up sausages, pan fry and voila - juicy meatballs without the fuss! A bottle of passata rather than canned tomato makes for a quick sauce which needs nothing more than a pinch of Italian Herbs and salt thanks to all the free flavour we get from the pre-seasoned meat inside the sausages. Serve over pasta, or polenta (try instant polenta!), mash or make saucy subs. YES!', 'https://www.recipetineats.com/tachyon/2025/10/Sausage-meatballs-15-minutes_0.jpg', 5, 10, 15, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_sausages", "quantity": {"value": 1.4, "unit": "pack of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_stock", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}]', '[{"ingredients":["1 tbsp olive oil","700 g / 1.4 lb good sausages","2 garlic cloves (, finely chopped)","3/4 cup chicken stock/broth (, low sodium - sub water (Note 2))","700g / 24 oz tomato passata (US: tomato sauce like Hunt''s) (Note 3)","1/2 tsp dried Italian herb mix (sub dried oregano, or 50/50 oregano/thyme)","1/2 tsp cooking salt / kosher salt (+50% for flakes, halve for table salt)","1/4 tsp red pepper flakes (, optional (hint of warmth - sub pinch of pepper))","1 sprig basil ( - stalk for sauce, leaves for garnish (optional))"]},{"ingredients":["Parmesan (, finely grated)","350g / 12oz pasta of choice (, or polenta, mash or make subs!)"],"purpose":"Serving:"}]', '[{"description":"Brown meatballs (3-4 min), add garlic for last 15 seconds. Reduce stock by half (1 min), add everything else, simmer 4 minutes. Serve!","images":[],"step":1},{"title":"Brown meatballs","description":"Heat the oil in a large non-stick pan over high heat. Add the meatballs and stir for 4 - 5 minutes until lightly browned but still raw inside. (Note 4)","duration":4.5,"images":[],"step":2},{"description":"Add garlic and stir for just 15 seconds until light golden (careful, don''t let it burn!)","images":[],"step":3},{"title":"Simmer","description":"Add the stock and simmer rapidly for 1 minute to reduce by half. Add everything else, stir, bring to a simmer, then lower heat to medium high and let it simmer energetically (but not crazy rapidly) for 4 minutes.","duration":1,"images":[],"step":4},{"description":"Serve with lots of parmesan and hand-torn basil leaves over pasta, polenta, mash or other starchy vehicle of choice, or stuff into subs!","images":[],"step":5},{"description":"Add cooked pasta with 1/2 cup of the pasta cooking water into the pan with meatballs. Toss over medium heat for 1 - 2 minutes until the sauce is stuck to the pasta and it''s stained red, rather than pooled in the base of the pan. Divide between bowls and enjoy!","duration":1.5,"images":[],"step":6}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["dinner-tonight","meatball-recipes","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","sausage-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ccc413d76a32', 'en', 'US', 'Jamaican Jerk Fish', 'Recipe video above. Jerk seasoning adds a stack of flavour and makes the surface crispy too. Quick way to make a dish that punches way above its weight for effort vs results. I''ve used it for white fish fillets here but it will be excellent with salmon, prawns/shrimp, chicken or turkey.Spiciness - Packs a decent punch! See note for how to control.Jamaican menu week! This Jerk Fish with Jamaican Slaw and Jamaican Coconut Rice and Peas (beans) plus rum and raisin ice cream without an ice cream maker for dessert!', 'https://www.recipetineats.com/tachyon/2023/01/Jerk-fish_0.jpg', 5, 6, 11, 4, '[{"id": "ing_garlic_powder", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.007, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}]', '[{"ingredients":["3 tsp garlic powder","3 tsp onion powder","2 tsp cooking salt / kosher salt (reduce to 1 1/2 tsp for table salt)","3 tsp dried thyme","2 1/2 tsp brown sugar (, lightly packed (Note 2))","2 1/4 tsp cayenne pepper (it''s spicy! See SPICE NOTE)","1 1/2 tsp smoked paprika (sub ordinary paprika)","1 1/4 tsp allspice powder","1/2 tsp cinnamon powder","1/2 tsp nutmeg powder"],"purpose":"Jerk seasoning (Note 1):"},{"ingredients":["4 x 160g/6 oz thin snapper or other white fish fillets (, skinless, boneless (up to 1.5cm / 0.6\" thick, Note 3))","3 tbsp extra virgin olive oil"],"purpose":"Fish:"}]', '[{"title":"Jerk Spice Blend","description":"Mix the Jerk Seasoning spices together in a bowl then spread in a small tray that is just large enough to fit one fish fillet.","images":[],"step":1},{"title":"Coat fish","description":"Pat fish dry with a paper towel. Then coat both sides of each fillet with the jerk seasoning, pressing to adhere. Shake off excess, place on a clean plate and coat remaining fish.","images":[],"step":2},{"title":"Cook fish","description":"Heat half the oil in a large non-stick pan over high heat. When you see small wisps of smoke, place 2 fillets presentation side down and cook for 2 minutes.","duration":2,"images":[],"step":3},{"title":"Flip","description":"the spice crust should be a deep bronze colour with a reddish tinge. Cook the other side for 1 minute until the target internal temperature is 55°C/130°F, or the fish flakes easily at the thickest point.","duration":1,"images":[],"step":4},{"description":"Rest on a rack for 2 minutes (to preserve crispy spice crust). Then serve! Recipes for pictured Jamaican sides coming on Tuesday - stay tuned!","duration":2,"images":[],"step":5}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Caribbean","Jamaican"],"categories":["dietary","dinner-tonight","fish-recipes","low-calorie-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a6b37999ff63', 'en', 'US', 'Crispy Skin Fish', 'Recipe video above. Fish with crispy skin is one of the most delicious quick ways to cook a piece of protein! To nail it every time, you need dry skin, hot oil and to press down lightly to let the skin seal against the hot pan.I''m using Barramundi here but this recipe can be used for any fish with skin that goes crispy - see Note 1.Stove to oven method recommended for thick fillets so for most even cooking of flesh with super crispy skin - see Note 3. Thin fillets can be cooked entirely on the stove. Scoring the skin is recommended for thick fillets for even cooking of the flesh and skin, plus an insurance policy to prevent the skin from curling up.Sauces and sides - See Note 7!', 'https://www.recipetineats.com/tachyon/2021/10/Crispy-Skin-Barramundi_97.jpg', 3, 0, 3, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.18, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sauces_and_sides", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["180g/6oz x 2 barramundi or other fish fillets (, skin on, pin boned (Note 1))","2 tbsp olive oil (or vegetable, canola or grapeseed oil)","3/4 tsp cooking/kosher salt (or 1/2 tsp table salt, Note 2)","1/4 tsp black pepper","Sauces and sides (- see Note 7 below)"]}]', '[{"title":"Thick Fillets definition","description":"Fish > 2.5cm / 1\" thick at the thickest point. Best finished in the oven. (Note 3)","images":[],"step":1},{"title":"Pan type","description":"Non-stick pan, an oven proof one if you have Thick Fillets. (Note 4)","images":[],"step":2},{"title":"Preheat oven (for Thick Fillets)","description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":3},{"description":"Cooking:","images":[],"step":4},{"title":"Dry skin","description":"Pat skin dry with paper towels. For extra precaution, leave the fish fillets in the fridge skin side up, uncovered, for an hour. (I rarely do this)","images":[],"step":5},{"title":"Scoring skin (Note 5)","description":"For Thick Fillets, score the skin by cutting slashes into the skin as pictured in post. 4cm slashes 1cm apart, 2 - 3mm deep, through the skin and ever so slightly into the flesh (1.6\" long, 0.4\" apart, 0.1\" deep)","images":[],"step":6},{"title":"Season fish","description":"Sprinkle the flesh and skin with the salt and pepper just before cooking.","images":[],"step":7},{"title":"Heat oil well","description":"Heat oil in a non stick pan over medium high heat until you see the first small wisps of smoke.","images":[],"step":8},{"title":"Press fish down","description":"Place one fillet into the pan skin side down, then use your fingers or spatula to press down lightly for 10 seconds to allow the skin to seal flat against the hot surface. Repeat with the other fillet (PROS: Do both at the same time!).","duration":0.16666666666666666,"images":[],"step":9},{"title":"Cook skin 2","description":"3 minutes: Cook the skin side for 2 to 3 minutes until it''s crispy in the centre and golden. Lift up to check.","duration":2.5,"images":[],"step":10},{"title":"Transfer Thick Fillets to oven","description":"Transfer to oven for 10 minutes (do not flip, keep skin side still down - goes crispier!) or until the internal temperature is 55°C/131°F. (Note 6)","duration":10,"images":[],"step":11},{"title":"Thin fillets","description":"Turn and cook the flesh side in the pan.","images":[],"step":12},{"title":"Rest 3 minutes","description":"Transfer fish to a rack with the skin side UP. Rest for 3 minutes.","duration":3,"images":[],"step":13},{"title":"Serving","description":"To serve, place on a plate skin side UP. Do not pour sauce on the skin until just before serving else it will soften the fish skin. See ingredients above for suggested sauces and sides!","images":[],"step":14}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","mains","other","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_44db9eac2bd1', 'en', 'US', 'Asian Chilli Chicken', 'Recipe video above. A quick chicken dinner that''s an explosion of (spicy!) Asian flavours! Make this with chicken breast, boneless thighs or tenderloins.Spiciness level: Spicy but not blow-your-head-off spicy! Remember, I like to think I''m a Spice Monster, but in reality I can''t handle the heat (literally!). To dial it back, reduce chilli flakes and see Note 2 about reducing Sriracha.', 'https://www.recipetineats.com/tachyon/2021/02/Asian-Chilli-Chicken_7a.jpg', 5, 8, 13, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_sriracha", "quantity": {"value": 0.113, "unit": "bottle of 400ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.002, "unit": "jar of 500g"}}, {"id": "ing_lime", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["500g / 1lb breast fillets, skinless and boneless (2 large) (Note 1 other cuts)","1/2 tsp each salt and pepper","1 1/2 tbsp rice flour, or all-purpose/plain flour (Note 2)","1 1/2 tbsp oil (, vegetable or canola)"],"purpose":"Chicken:"},{"ingredients":["2 tsp sesame oil","2 garlic cloves (, finely minced)","2 tsp ginger (, finely minced)","1 tsp chilli flakes / red pepper flakes (reduce for less spicy)","1/2 cup water","3 tbsp sriracha (sub ketchup for not spicy, Note 3)","1 tbsp soy sauce (, light or all purpose (Note 4))","1/4 cup honey (sub brown sugar)","3 tbsp lime juice (sub 2 tbsp rice vinegar)"],"purpose":"Sauce:"},{"ingredients":["Green onion (finely sliced), sesame seeds, fresh chilli, lime wedges"],"purpose":"Garnishes (choose):"}]', '[{"title":"Season","description":"Cut each chicken breast in half horizontally to form 4 steaks total. Sprinkle each side with salt, pepper and rice flour, shaking off excess.","images":[],"step":1},{"title":"Pan-fry","description":"Heat oil in a large skillet over high heat. Add chicken and cook for 2 minutes. Turn and cook the other side for 2 minutes, then remove to a plate.","duration":2,"images":[],"step":2},{"description":"Sticky Chilli Sauce:","images":[],"step":3},{"title":"Sesame oil","description":"Allow the skillet to cool a bit then return to the stove on medium. Add sesame oil and heat.","images":[],"step":4},{"title":"Garlic and ginger","description":"Add garlic and ginger, cook for 15 seconds.","duration":0.25,"images":[],"step":5},{"title":"Chilli flakes","description":"Add chilli flakes and cook for 30 seconds until garlic is golden.","duration":0.5,"images":[],"step":6},{"title":"Sriracha, soy and honey","description":"Turn heat up to medium-high. Add water, sriracha, soy sauce and honey, stir well, scraping the base of the pan to dissolve all the golden bits into the liquid.","images":[],"step":7},{"description":"Simmer for 2 minutes until it reduce to a thick syrup. Add lime juice, then simmer for a further 30 seconds until it thickens back to a thick syrup.","duration":2,"images":[],"step":8},{"title":"Coat chicken","description":"Turn heat off. Return chicken to pan, turning to coat in sauce.","images":[],"step":9},{"description":"Serve chicken, topping with remaining sauce in skillet, garnished with green onions, sesame seed and extra lime wedges, if desired.","images":[],"step":10}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian","Modern Asian"],"categories":["asian-recipes","chicken","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","mains","modern-asian","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_438b29404531', 'en', 'US', '12 Minute Thai Chicken Peanut Noodles', 'Recipe video above. Thai Chicken Peanut Noodles is what you make when you''ve got less than 15 minutes to get dinner on the table and you need a Thai fix! Using chicken mince means no meat prep - and you can switch it out with literally any ground meat (beef, turkey, pork). It might not be authentic Thai ... but it''s fast and 100% delicious!NOTE: Trick here is to work quickly so the sauce isn''t all absorbed by the noodles which will make them bloated and clumpy. If your noodles do absorb all the sauce, just add a splash of water to thin it out.', 'https://www.recipetineats.com/tachyon/2021/01/12-Minute-Thai-Chicken-Noodles_2.jpg', 3, 9, 12, 2, '[{"id": "ing_oil", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_mince", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_red_curry_paste", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.007, "unit": "can of 400ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.12, "unit": "jar of 375g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_peanuts", "quantity": {"value": 0.075, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp oil","1 garlic clove (, minced)","200g/7oz chicken mince (ground chicken) (Note 1)","1 tsp curry powder (Note 2)","1 1/2 tbsp red curry paste (, separated (Note 3))","1 tsp dark soy sauce (Note 4)","1 1/2 cups chicken stock/broth (, low sodium)","3/4 cup coconut milk ((~1/2 a can), full fat for best flavour)","2 tbsp cider vinegar","3 tbsp peanut butter","2 instant ramen or noodle cakes (~70-100g/2.5-3.5oz per cake; any brand (discard seasoning pack, Note 5))","2 (big!) handfuls baby spinach"]},{"ingredients":["2 tbsp peanuts (, finely chopped)","Roughly chopped fresh coriander/cilantro leaves","Sriracha or other chilli paste (, optional)"],"purpose":"To serve:"}]', '[{"title":"Sauté garlic","description":"Heat oil in a medium skillet over high heat (not too large, else the sauce will evaporate too quickly). Add garlic and cook for 20 seconds until it turns golden.","duration":0.3333333333333333,"images":[],"step":1},{"title":"Cook chicken","description":"Add chicken mince and cook for 2 minutes, breaking it up as you go, until it mostly changes from pink to white.","duration":2,"images":[],"step":2},{"title":"Add flavourings","description":"Add 1 tbsp red curry paste, curry powder and soy sauce. Cook for 1 minute.","duration":1,"images":[],"step":3},{"title":"Cook extra curry paste","description":"Clear a space in the middle of the pan, add remaining 1/2 tbsp curry paste, stir the curry paste for 30 seconds.","duration":0.5,"images":[],"step":4},{"title":"Simmer stock","description":"Add chicken stock, bring to a simmer then reduce to medium-high. Simmer for 1 minute.","duration":1,"images":[],"step":5},{"title":"Add noodles","description":"Squish the noodle cakes in, pushing chicken aside so the noodles are as submerged as possible.","images":[],"step":6},{"title":"Cook 45 sec, flip, 30 sec","description":"Leave to cook for 45 seconds, then flip noodles. Leave for another 30 seconds, then separate the noodles with 2 wooden spoons.","duration":0.75,"images":[],"step":7},{"title":"Add peanut sauce","description":"Push noodles aside, add coconut milk, peanut butter and vinegar, then give it a quick mix to mostly dissolve the peanut butter.","images":[],"step":8},{"title":"Toss with spinach","description":"Add spinach, toss with the noodles for 30 seconds until wilted. Make sure it''s still pretty saucy - everybody loves sauce!","duration":0.5,"images":[],"step":9},{"title":"Serve","description":"Transfer to serving bowls, sprinkle with coriander, peanuts and Sriracha or chilli paste if desired.","images":[],"step":10}]', '["gluten","peanuts","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Thai-ish"],"categories":["asian-recipes","dinner-tonight","noodles","one-pot-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5fc7e5dae9a7', 'en', 'US', 'Chop Suey - Chicken Stir Fry', 'Recipe video above. The essential ingredient for a great Chop Suey sauce is Chinese cooking wine. All Chinese restaurants use it! See notes for subs if you can''t get your hands on it. Veggie loaded, light on the meat, this is healthy and adaptable to whatever you''ve got in your fridge!', 'https://www.recipetineats.com/tachyon/2017/11/Chicken-Stir-Fry-Chop-Suey-5.jpg', 9, 6, 14, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.18, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.005, "unit": "tub of 200g"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_stems_choy_sum", "quantity": {"value": 5.5, "unit": "unit"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}]', '[{"ingredients":["180g (6oz ) chicken breast (, thinly sliced)","1/2 tsp baking soda / bi-carb (optional, Note 1)"],"purpose":"Optional Tenderised Chicken (Note 1):"},{"ingredients":["1 tbsp cornflour / corn starch","1 1/2 tbsp light soy sauce (, or all purpose soy(Note 3))","1 tbsp Oyster Sauce (Note 4)","1 tbsp Chinese Cooking Wine (OR Mirin (Note 5))","1/2 tsp sesame oil (optional)","Dash of white pepper (or black)","3/4 cup (185 ml) water"],"purpose":"Sauce (or use Charlie, Note 2):"},{"ingredients":["1 1/2 tbsp vegetable oil (or other cooking oil)","2 garlic cloves (, finely chopped)","1/2 onion (, sliced (white, brown, yellow))","5 - 6 stems choy sum (or other Asian greens)","1 medium carrot","1/2 cup sliced mushrooms (shiitake is authentic, but any will do)","1 cup bean sprouts"],"purpose":"Stir Fry:"}]', '[{"description":"\"Velvet\" Chicken (optional, Note 1)","images":[],"step":1},{"description":"Place chicken in a bowl, sprinkle over baking soda. Use your fingers to mix then set aside for 20 minutes, no longer than 30 minutes (can get too tender). Rinse well, pat excess water with paper towels, set aside (see video).","duration":20,"images":[],"step":2},{"description":"Prep Ingredients:","images":[],"step":3},{"title":"Sauce","description":"Place cornflour and soy sauce in a bowl. Mix until lump free. Then add remaining Sauce ingredients and stir.","images":[],"step":4},{"title":"Chop choy sum","description":"Trim end off choy sum. Then cut into 7cm (3\") pieces. Separate stems from leaves.","images":[],"step":5},{"title":"Chop carrot","description":"Peel then cut into 3cm (1.3\") pieces. Then slice the pieces thinly.","images":[],"step":6},{"description":"Heat oil in a wok or skillet over high heat. Add garlic, stir quickly, then add onion, Cook for 1 minute, moving constantly, until onion is starting to wilt.","duration":1,"images":[],"step":7},{"description":"Add chicken, cook for 1 minute until the surface changes from pink to white.","duration":1,"images":[],"step":8},{"description":"Add choy sum stems, carrot and mushrooms. Stir fry for 1 minute.","duration":1,"images":[],"step":9},{"description":"Add choy sum leaves, bean sprouts and Sauce. Stir fry for 1 to 2 minutes until the Sauce thickens to a thick syrup consistency. Vegetables should still be tender/crisp, not soggy and soft.","duration":1.5,"images":[],"step":10},{"description":"Serve immediately with rice (for low carb, low cal option, try Cauliflower Rice!)","images":[],"step":11}]', '["gluten","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e299f8e365a5', 'en', 'US', 'Honey Garlic Chicken Breast', 'Recipe video above. An incredible quick and easy way to serve up chicken breast - seared then simmered in the most amazing honey garlic sauce. Don''t be deceived by the short ingredient list! It''s absolutely worth the extra step of dusting the chicken with flour because it creates a crust for the sauce to cling to. BONUS: See notes for how to make this with any protein - beef, pork, lamb, prawns/shrimp, tofu!', 'https://www.recipetineats.com/tachyon/2018/09/Honey-Garlic-Chicken-Breast_5.jpg', 4, 8, 12, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 2.0, "unit": "bottle of 500ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.002, "unit": "jar of 500g"}}]', '[{"ingredients":["500g / 1 lb chicken breast (, boneless and skinless (2 pieces))","Salt and pepper","1/4 cup flour (Note 1)","3 1/2 tbsp (50g) unsalted butter (or 2 1/2 tbsp olive oil)","2 garlic cloves (, minced)","1 1/2 tbsp apple cider vinegar (or white or other clear vinegar)","1 tbsp soy sauce (, light or all purpose (Note 2))","1/3 cup honey (or maple syrup)"]}]', '[{"description":"Cut the breasts in half horizontally to create 4 steaks in total. Sprinkle each side with salt and pepper.","images":[],"step":1},{"description":"Place flour in a shallow dish. Coat chicken in flour and shake off excess.","images":[],"step":2},{"description":"Melt most of the butter in a large skillet over high heat - hold back about 1 tsp for later.","images":[],"step":3},{"title":"Place chicken in skillet and cook for 2","description":"3 minutes until golden. Turn and cook the other side for 1 minute.","duration":2.5,"images":[],"step":4},{"description":"Turn heat down slightly to medium high.","images":[],"step":5},{"description":"Make a bit of room in the pan and add garlic and top with remaining dab of butter. Stir garlic briefly once butter melts.","images":[],"step":6},{"description":"Add vinegar, soy sauce and honey. Stir / shake pan to combine. Bring sauce to simmer, then simmer for 1 minute or until slightly thickened.","duration":1,"images":[],"step":7},{"description":"Turn chicken to coat in sauce. If the sauce gets too thick, add a touch of water and stir.","images":[],"step":8},{"description":"Remove from stove immediately. Place chicken on plates and drizzle over remaining sauce.","images":[],"step":9}]', '["gluten","milk","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","mains","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8b6d2a374fe0', 'en', 'US', 'Creamy Lemon Chicken Breast', 'Recipe video above. Cream and lemon is a luscious combination and is stellar served over crispy chicken! It''s super easy and fast to make, and the sauce is absolutely to die for. A little dusting of flour creates a terrific crispy coating on the chicken and gives the sauce something to cling to.', 'https://www.recipetineats.com/tachyon/2016/01/Creamy-Lemon-Chicken_8.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.003, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.012, "unit": "carton of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 3.5, "unit": "net of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_parmesan", "quantity": {"value": 3.0, "unit": "pack of 200g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["600g / 1.2lb chicken breasts (2 large) (Note 1)","1/2 tsp cooking salt (kosher salt)","1/4 tsp Black pepper","1/4 cup flour (plain / all-purpose)","40g / 3 tbsp butter (, unsalted)","1 - 2 garlic clove, minced","1 1/4 cups chicken broth/stock","3/4 cup cream (, heavy/thickened (Note 2))","3 - 4 tbsp lemon juice (adjust to taste, start with 3 tbsp)","2 tsp Dijon mustard","3/4 cup parmesan cheese (, freshly grated OR store bought finely shredded (Note 3))"],"purpose":"Crispy Chicken"},{"ingredients":["Pasta of choice (I used linguine)","Finely chopped parsley"],"purpose":"To serve"}]', '[{"description":"Slice chicken breast horizontally to create two thin steaks (so you end up with 4 thin steaks in total).","images":[],"step":1},{"description":"Sprinkle each side with salt and pepper, then coat with flour, shaking off excess.","images":[],"step":2},{"description":"Melt butter in a large skillet over medium high heat. Cook chicken 2 minutes on each side until golden and crispy, then remove onto plate.","images":[],"step":3},{"title":"Add a touch of butter if your pan is dry","description":"but you shouldn''t need it. Add garlic, stir 10 seconds.","images":[],"step":4},{"description":"Then add chicken broth, cream, lemon and Dijon mustard. Bring to simmer and scrape the bottom of the pan to dissolve brown bits into the liquid. Use a whisk if needed to dissolve mustard.","images":[],"step":5},{"description":"Add parmesan then simmer rapidly for 3 minutes or until sauce thickens slightly. Add salt, pepper and adjust lemon to taste.","duration":3,"images":[],"step":6},{"description":"Return the chicken to the pan (pour in any juices on the plate too), turn to coat.","images":[],"step":7},{"description":"Place chicken on serving plates with pasta or mashed potatoes. Sprinkle with fresh parsley if using. Spoon over Lemon Sauce and serve! (Bread for mopping wouldn''t go astray either)","images":[],"step":8}]', '["gluten","milk","mustard"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fa2342ba401a', 'en', 'US', 'Baked Fish with Lemon Cream Sauce (One Baking Dish!)', 'Recipe video above. A fantastic quick-fix dinner - baked fish in a lemon cream sauce, all made in ONE PAN! Don''t let the short ingredient list fool you, this tastes so good! The key to the tasty sauce is the fish juices that leeches out while baking and is essentially the broth for the sauce!', 'https://www.recipetineats.com/tachyon/2016/10/Baked-Fish-with-Lemon-Cream-Sauce_9.jpg', 5, 10, 15, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.003, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 x 150- 180g / 5 - 6 oz fish fillets (, about 1.5cm / 1/2\" thick, skinless and boneless (Note 1))","50g / 4 tbsp unsalted butter","1/4 cup cream, heavy / thickened (See Note 2 for sub options)","1 - 2 garlic cloves (, minced)","1 tbsp Dijon mustard","1 1/2 tbsp lemon juice","Salt & pepper","1 1/2 tbsp eschallots (French onion) (, finely chopped (Note 3))","Fresh parsley and lemon slices (, to serve)"]}]', '[{"description":"Preheat oven to 200°C / 390°F (all oven types).","images":[],"step":1},{"title":"Place fish in a baking dish","description":"ensure the fish isn''t crammed in too snugly. See video or photos in post. Sprinkle both sides of fish with salt and pepper.","images":[],"step":2},{"description":"Place butter, cream, garlic, mustard, lemon juice, salt and pepper in a microwave proof jug or bowl. Microwave in 2 x 30 sec bursts, stirring in between, until melted and smooth.","images":[],"step":3},{"description":"Sprinkle fish with shallots, then pour over sauce.","images":[],"step":4},{"title":"Bake for 10","description":"12 minutes, or until fish is just cooked. Remove from oven and transfer fish to serving plates. Spoon over sauce, and garnish with parsley and lemon wedges if using.","duration":11,"images":[],"step":5}]', '["fish","milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","easter-mains-fish-seafood","emergency-recipes","fish-recipes","low-calorie-recipes","main-dishes","most-popular","one-pot-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_338eae1fe368', 'en', 'US', 'Chow Mein Ramen Noodles', 'Recipe video above. The fastest, easiest Chow Mein recipe ever! Made using a couple of cheeky shortcuts - ramen noodles, a Coleslaw mix, with the noodles cooked in the same skillet. It''s a quicker version of real Chow Mein - 99% of the flavour, but FASTER!', 'https://www.recipetineats.com/tachyon/2019/06/Chow-Mein-Ramen_3.jpg', 7, 8, 15, 2, '[{"id": "ing_oil", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_chicken", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_pre_shedded_coleslaw_mix", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_heaped_cup_beansprouts", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 tbsp oil","200g/7oz chicken (, sliced (thigh, breast))","2 garlic cloves (, minced)","2 ramen or instant noodle cakes (, discard seasoning (Note 1))","200g/7oz pre shedded Coleslaw mix (, cabbage and carrot (Note 2))","3 green onion stems (, cut into 5cm/2\" lengths)","1 heaped cup beansprouts","1 cup (250 ml) water"]},{"ingredients":["1.5 tbsp light soy sauce (Note 3)","1.5 tbsp Oyster Sauce (Note 4)","1 tbsp Chinese Cooking Wine or Mirin (Note 5)","2 tsp sesame oil (, toasted (Note 6))","1 tsp white sugar (SKIP if using Mirin)"],"purpose":"Chow Mein Sauce:"}]', '[{"description":"Mix Sauce in a bowl.","images":[],"step":1},{"description":"Heat oil in a large skillet over high heat. Add garlic, cook 10 seconds.","images":[],"step":2},{"description":"Add chicken and cook until mostly changes from pink to white, then add Sauce.","images":[],"step":3},{"description":"Cook for 1 minute, then add Coleslaw mix and white part of green onions.","duration":1,"images":[],"step":4},{"description":"Cook for 1 1/2 minutes until cabbage wilts, then push everything to the side to make room for the ramen (see video & photos in post).","images":[],"step":5},{"description":"Add water then squidge the ramen cakes in side by side.","images":[],"step":6},{"description":"When water simmers, leave for 45 seconds. Flip, then leave for 30 seconds.","duration":0.75,"images":[],"step":7},{"description":"Loosen noodles, add bean sprouts and green onion, then toss energetically for 1 1/2 - 2 minutes until sauce reduces and coats noodles. (Note 7)","images":[],"step":8},{"description":"Serve immediately!","images":[],"step":9}]', '["gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","dinner-tonight","emergency-recipes","noodles","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_75598a23ec49', 'en', 'US', 'Lime Marinated Grilled Chicken', 'Recipe video above. This lime marinade has a beautiful depth of flavour and really infuses the chicken with lime flavours! Touch of sugar caramelises the chicken, and depth of flavour is achieved by using soy or fish sauce instead of salt (it doesn''t taste Asiany at all, I swear!). Stove or BBQ best, but can also bake!', 'https://www.recipetineats.com/tachyon/2016/04/Lime-Chicken_2.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.675, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["600-750g / 1.2 - 1.5 lb chicken breasts (4 pieces) or boneless thigh ( (Note 1))","Zest of 1 lime (zest before juicing)","4 tbsp lime juice (1 - 2 limes)","2 garlic cloves (, minced)","3 tbsp brown sugar","1/4 tsp pepper","1 tbsp olive oil","2 tbsp finely chopped cilantro/coriander (optional)","1 tbsp fish sauce (OR 2 tbsp soy sauce) ( (Note 2))"],"purpose":"Chicken Marinade"},{"ingredients":["1 - 2 tbsp olive oil"],"purpose":"To Cook"}]', '[{"description":"Use fist (or rolling pin!) to pound fat end of chicken breast to about 1.7 cm / 2/3\" thickness (not required for thigh).","images":[],"step":1},{"description":"Place chicken and Marinade in a ziplock bag, massage to distribute marinade evenly. Place on a plate or bowl and refrigerate for 24 hours (min 12 hrs, max 48 hrs - Note 3)","images":[],"step":2},{"description":"Remove chicken, discard Marinade. Cook using one method below.","images":[],"step":3},{"description":"To Cook (cooked internal temp 165F/75C)","images":[],"step":4},{"title":"STOVE","description":"Heat oil in a large skillet over medium high heat. Cook chicken for 3 minutes on each side or until caramelised and golden brown (see video!).","duration":3,"images":[],"step":5},{"title":"BBQ","description":"Brush grills with oil and heat to medium high (or medium if your BBQ is strong). Cook chicken for 3 minutes on each side until caramelised (see video!).","duration":3,"images":[],"step":6},{"title":"OVEN","description":"Preheat oven to 425F/220C. Bake 15 minutes, then flick broiler/grill on high and grill for 3 minutes to caramelise surface & finish cooking.","duration":3,"images":[],"step":7},{"description":"Rest and Serve:","images":[],"step":8},{"description":"Transfer chicken to a serving plate, cover loosely with foil and rest for 3 minutes.","duration":3,"images":[],"step":9},{"description":"Garnish with extra coriander/cilantro, lime wedges and chilli if desired, then serve!","images":[],"step":10}]', '["fish","gluten","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","low-calorie-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_625457ad8802', 'en', 'US', 'Asian Beef Bowls', 'Recipe VIDEO above. A fabulous quick stir fry made using beef mince (ground beef) <<-- No slicing meat! It''s not saucy like usual stir fries, you don''t need sauce because the beef mixes through the rice, and it has plenty of flavour and it''s JUICY. Great recipe to add diced or julienned veggies!', 'https://www.recipetineats.com/tachyon/2017/05/Asian-beef-Bowls.jpg', 5, 7, 12, 4, '[{"id": "ing_hoisin_sauce", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 3.0, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp Hoisin Sauce (or sub with Oyster)","2 tbsp Oyster Sauce (or sub with 1 1/2 tbsp Hoisin)","1 tbsp Chinese cooking wine (or Mirin, dry sherry, sake or any rice wine) (Note 1)","2 1/2 tbsp dark soy sauce (Note 2)","2 tsp white sugar","1/2 tsp sesame oil","1/4 tsp white pepper (or sub with black)"],"purpose":"Sauce:"},{"ingredients":["1 tbsp oil","2 garlic cloves, minced","1 small onion, finely chopped","500 g /1 lb beef mince (ground beef) ( (lean is good))","1/2 cup shallots / scallions (, sliced, plus more for garnish)"],"purpose":"Stir Fry:"},{"ingredients":["Sesame seeds"],"purpose":"Garnishes:"}]', '[{"description":"Mix Sauce together in a bowl","images":[],"step":1},{"description":"Heat oil in a large skillet over high heat. Add garlic and onion, cook for 1 minute or until onion starts browning.","duration":1,"images":[],"step":2},{"description":"Add beef and cook, breaking it up as you go.","images":[],"step":3},{"description":"Once the beef has all changed from red to brown, add Sauce. Cook for a further 2 minutes, or until Sauce has evaporated and beef is cooked. If you want the beef cooked more, add a splash of water and keep cooking (I don''t do this).","images":[],"step":4},{"description":"Stir through shallots, then serve over rice, garnished with more shallots and sesame seeds, if desired. Or for a low carb, low cal option, try Cauliflower Rice!","images":[],"step":5}]', '["gluten","sesame","shellfish","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef-mince-recipes","beef-recipes","chinese-recipes","dinner-tonight","emergency-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5d7d6ed9afef', 'en', 'US', 'Crispy Pan Fried Fish', 'Recipe video above. 3 key tips to ensure your pan fried fish comes out beautifully golden and crispy every time: pat the fish dry, press flour on well but shake excess off well, and heat the pan first before adding the oil or use a heavy duty non stick pan. With a good fish, well seasoned and crispy skin, I don''t need a sauce....but I''ve added a couple in the notes just in case! :)', 'https://www.recipetineats.com/tachyon/2017/06/Crispy-Pan-Fried-Fish-3-1.jpg', 3, 5, 8, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_oil", "quantity": {"value": 0.15, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 thin fish fillets, around 150g/5 oz each, 1 cm / 2/5\" thick, skin on or off (Note 1)","Salt and pepper","1/4 cup / 35g flour (plain/all purpose, wholemeal)","1 tsp paprika (, optional (Note 2))","2 - 3 tbsp oil, enough to mostly thinly cover base (I use vegetable or canola)"]},{"ingredients":["Lemon wedges","Finely chopped parsley or dill (, for garnish, optional)"],"purpose":"Garnishes:"}]', '[{"description":"Use scrunched up paper towels to pat the fish dry on both sides. This is especially important if you are using thawed frozen fish.","images":[],"step":1},{"description":"Season the fish well on both sides with salt and pepper (key!).","images":[],"step":2},{"description":"Mix the flour and paprika on a plate.","images":[],"step":3},{"description":"Coat fish on both sides with flour, pressing down firmly so it adheres, but shake well to remove excess. (Note 2)","images":[],"step":4},{"description":"Heat a heavy based skillet (normal or non stick) over medium high heat until you see wisps of smoke. Add oil and swirl to coat the pan - it will heat within seconds.","images":[],"step":5},{"title":"Add fish","description":"it should sizzle straight away. Shake the pan lightly to move the fish. Cook for 2 minutes until golden and crisp, pressing down gently, then flip. Cook the other side for 2 minutes until crisp then remove.","duration":2,"images":[],"step":6},{"description":"If it''s browning too quickly, just remove pan from the stove briefly. If it''s stuck, don''t move - it will release naturally once golden.","images":[],"step":7},{"description":"Serve fish immediately with lemon wedges and garnished with dill or parsley, if using. It starts to lose crispiness after 5 minutes.","images":[],"step":8}]', '["fish","gluten"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1778cbc607c7', 'en', 'US', 'Quick Asian Beef Ramen Noodles', 'Recipe video above. A great quick beef ramen noodle recipe that requires very little prep, and it''s a handy one-pan recipe (no need to boil the noodles separately!). It''s a great noodle stir fry that''s family friendly - everybody loves the sweet-savoury flavour of the sauce!The flavour-trick here is to caramelise the beef well, it makes all the difference, so don''t shortcut it. Next time: try the Chicken and vegetable and Mushroom versions!', 'https://www.recipetineats.com/tachyon/2018/12/Asian-Beef-Noodles_4.jpg', 7, 8, 15, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 0.02, "unit": "bottle"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 0.04, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["2 packets ramen or other instant noodles (, discard seasoning (Note 1))","1 tsp oil","2 tsp sesame oil (or more oil) (Note 2)","2 garlic cloves (, minced)","1/2 onion (, sliced)","200g / 7oz beef mince (ground beef) (Note 3)","1 1/4 cups (315 ml) water, plus more as needed","Big handful bean sprouts"]},{"ingredients":["1 tbsp dark soy sauce (Note 4)","1 tbsp Oyster sauce (or Hoisin, Note 5)","2 tsp Hoisin sauce (or more Oyster sauce)","1 tbsp mirin (Note 6)"],"purpose":"Sauce:"},{"ingredients":["Finely sliced green onion / shallots","Sesame seeds"],"purpose":"Garnishes (optional):"}]', '[{"description":"Mix Sauce.","images":[],"step":1},{"title":"Sauté onion and garlic","description":"Heat oils in a medium skillet over high heat. Add onion and garlic, cook for 1 1/2 minutes until starting to go golden.","images":[],"step":2},{"title":"Cook beef","description":"Add beef and cook, breaking it up as you go, until it changes from pink to light brown.","images":[],"step":3},{"title":"Caramelise beef","description":"Add Sauce and cook for 2 to 3 minutes until well caramelised (see video).","duration":2.5,"images":[],"step":4},{"title":"Add water and noodles","description":"Push beef to the side to make enough space for the noodles. Add water, place noodles in water.","images":[],"step":5},{"title":"Cook ramen","description":"Leave for 45 seconds then turn. Leave for 30 seconds, then untangle the noodles, then toss through the beef.","duration":0.75,"images":[],"step":6},{"description":"Add beansprouts, toss for 1 minute or until sauce reduces to coat the noodles and the noodles are cooked. (Note 7)","duration":1,"images":[],"step":7},{"description":"Serve immediately, garnished with green onions and sesame seeds.","images":[],"step":8}]', '["gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef-mince-recipes","beef-recipes","dinner-tonight","emergency-recipes","main-dishes","noodles","one-pot-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bfa4790039a1', 'en', 'US', 'Peanut Sauce for Stir Fries', 'Recipe VIDEO above. A simple, really tasty peanut sauce to use in stir fries and noodles! Tastes like a Satay Peanut Sauce. To use, follow formula below or for full directions, use this Satay Peanut Chicken Stir Fry or this Stir Fried Noodles with Peanut Sauce recipe. Makes enough sauce for 2 - 3 people, a stir fry with rice, or stir fried noodles.', 'https://www.recipetineats.com/tachyon/2018/03/Peanut-Sauce-for-Stir-Fries_5.jpg', 5, 0, 5, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.005, "unit": "jar of 375g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_single_batch_peanut_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.003, "unit": "pack of 3 heads"}}, {"id": "ing_proteins", "quantity": {"value": 190.0, "unit": "unit"}}, {"id": "ing_vegetables_of_choice_as_required_and_grouped_by_cooking_time", "quantity": {"value": 3.5, "unit": "unit"}}, {"id": "ing_double_batch_peanut_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_stir_fry_ingredients_above", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.267, "unit": "pack of 375g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp fish sauce (Note 1)","1/2 tbsp dark soy sauce (Note 2)","1 1/2 tsp sugar","2 tsp cornflour / cornstarch","1 garlic clove (, minced)","1 tsp grated ginger","1 tsp curry powder (any type)","1 1/2 tbsp / 30 g crunchy peanut butter, regular (Note 1)","3 tbsp water"],"purpose":"Peanut Sauce"},{"ingredients":["1 SINGLE batch Peanut Sauce (above)","2 tbsp oil","1/2 onion, sliced","1 - 2 garlic cloves, finely chopped or minced","180- 200g / 6 - 7 oz protein of choice, sliced","3 - 4 cups vegetables of choice, chopped / sliced as required and grouped by cooking time (Note 4)"],"purpose":"Stir Fry"},{"ingredients":["DOUBLE batch Peanut Sauce (tap Servings & slide)","Stir fry ingredients above","100g / 3.5 oz dried rice noodles OR 180g/6 oz fresh noodles of choice (, prepared per packet)"],"purpose":"Noodle Stir Fry – you will need"},{"ingredients":["Finely chopped coriander / cilantro, crushed peanuts"],"purpose":"Garnish (optional):"}]', '[{"description":"Place all ingredients other than water in a bowl. Mix to combine. Then add water and mix again.","images":[],"step":1},{"description":"Heat oil in a skillet or wok over high heat. Add garlic and 1/2 sliced onion. Cook 1 minute.","images":[],"step":2},{"description":"Add protein of choice or sliced tofu. Cook 2 minutes until just cooked.","images":[],"step":3},{"description":"Add vegetables in order of time to cook, starting with the veggies that take the longer. Cook briefly until just cooked but still crisp.","images":[],"step":4},{"description":"Add delicate veggies (eg bean sprouts, spinach and other leafy greens) and Sauce. Toss until Sauce thickens (add extra water if needed).","images":[],"step":5},{"description":"Garnish with peanuts and coriander / cilantro, if using. Serve over rice - or for a low carb, low cal option, try Cauliflower Rice!","images":[],"step":6},{"description":"Follow Stir Fry directions. Add NOODLES with the Sauce in step 4.","images":[],"step":7},{"title":"Toss for 1","description":"2 minutes until Sauce thickens and coats noodles. Remove from heat, garnish and serve immediately!","duration":1.5,"images":[],"step":8}]', '["fish","gluten","peanuts","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dinner-tonight","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b0b2c3e0f4be', 'en', 'US', 'Bacon Pasta with tomato pasta sauce', 'Recipe video above. You''re just 15 minutes away from this pasta with golden crispy bacon in a garlic tomato pasta sauce! Scale recipe by hovering cursor over Servings (see Note 2).', 'https://www.recipetineats.com/tachyon/2017/05/Bacon-Tomato-Pasta-3.jpg', 5, 10, 15, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.32, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.825, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["160 g / 5 oz spaghetti or other long strand pasta of choice","1 tsp olive oil (or butter)","150 - 180 g / 5 - 6 oz bacon (, diced)","1 garlic clove (, minced)","1/2 onion (, finely diced (brown, white, yellow))","400 g / 14 oz canned crushed tomato","Salt and pepper","Pinch of sugar (, if needed (Note 1))","Extra virgin olive oil","Finely chopped parsley"]}]', '[{"description":"Have the ingredients lined up and ready to start cooking at the same time.","images":[],"step":1},{"description":"Bring a large pot of water to the bowl. Add a pinch of salt. Cook pasta according to packet but MINUS 2 minutes.","images":[],"step":2},{"description":"Meanwhile, heat oil in a skillet over high heat. Add bacon and cook for 1 minute, then add garlic and onion and cook for 3 minutes or until onion is translucent and bacon is golden. Drain excess fat if desired.","duration":1,"images":[],"step":3},{"description":"Scoop out a mug of pasta cooking water, then pour about 1/2 cup into the skillet. Bring to simmer and stir, scraping the skillet to dissolve in all the golden bits stuck on the pan into the liquid.","images":[],"step":4},{"description":"Add tomato, bring to simmer and cook for 2 minutes, then turn down to medium high.","duration":2,"images":[],"step":5},{"description":"Drain pasta, or if you timed it right, use tongs to transfer it straight from the pot into the skillet.","images":[],"step":6},{"description":"Toss gently using two wooden spoons for 2 minutes, or until the sauce is no longer sitting in the skillet, it''s all on the pasta (see video). If it gets too thick, just add an extra splash of the pasta cooking water.","duration":2,"images":[],"step":7},{"description":"Season with salt and pepper (remember bacon is salty!).","images":[],"step":8},{"description":"Serve immediately, garnished with parmesan, parsley and final drizzle of olive oil if desired.","images":[],"step":9}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dinner-tonight","italian-recipes","main-dishes","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5b92238318f5', 'en', 'US', 'One Pot Chicken Alfredo Pasta', 'Recipe video above. Pasta in a silky, creamy sauce with tender, juicy chicken, all made in ONE POT! (Well, pan:) )', 'https://www.recipetineats.com/tachyon/2017/03/One-Pot-Chicken-Alfredo-2.jpg', 2, 13, 15, 3, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_chicken_stock", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 3.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["200 g / 7oz chicken breast, cut in half horizontally","Salt and pepper","1 tbsp olive oil","250 g / 8 oz fettuccine","2 cups milk, any fat %","1 1/2 cups chicken stock / broth","1 large garlic clove, minced","1/2 cup thickened / heavy cream (Note 1)","3/4 cup freshly grated parmesan (Note 2)","Parsley, for garnish"]}]', '[{"description":"Sprinkle both sides of the chicken with salt and pepper.","images":[],"step":1},{"description":"Use a skillet large enough to fit the pasta.","images":[],"step":2},{"description":"Heat oil over medium high heat. Add chicken and cook for 2 minutes on each side until golden and cooked through. Remove onto plate and rest for 5 minutes, then slice while pasta is cooking.","duration":2,"images":[],"step":3},{"description":"Add milk, chicken broth and garlic. Bring to simmer then add pasta.","images":[],"step":4},{"description":"Move pasta around every 30 seconds or so until it is softened (around 3 minutes) so it doesn''t stick. Once pasta is softened, reduce heat to medium and stir every couple of minutes.","images":[],"step":5},{"title":"At about 9","description":"10 minutes, the pasta should be almost cooked but there should still be liquid covering the base of the skillet. Add cream and parmesan and mix.","images":[],"step":6},{"description":"Simmer, stirring occasionally, for ~2 minutes, until sauce is thickened and pasta is cooked. If you cook it too long and the sauce goes gluggy, add a splash of hot tap water - will go back to silky with a few tosses.","images":[],"step":7},{"description":"Adjust salt and pepper to taste and serve immediately, garnished with freshly grated parmesan and parsley!","images":[],"step":8}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","italian-recipes","main-dishes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bbe82b35b97c', 'en', 'US', 'Asian Steak', 'An incredible Asian Steak recipe, with a simple yet stunning sauce inspired by the great Tetsuya, a highly regarded Japanese-Australian chef. Make this with small pieces of high quality beef steak! See notes for my tips on FREEZING rice - so handy to have on standby for quick meals!', 'https://www.recipetineats.com/tachyon/2017/03/Asian-Steak-3.jpg', 5, 10, 15, 2, '[{"id": "ing_beef_steak", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_cooking_sake", "quantity": {"value": 0.18, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 45.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}]', '[{"ingredients":["2 beef tenderloin steaks, around 150g/5oz each (Note 1)","1 tbsp vegetable oil (or other neutral cooking oil)"]},{"ingredients":["1 tbsp soy sauce, all purpose (Note 2)","2 tbsp Mirin (Note 3)","3 tbsp cooking sake (Note 3)","45g/3tbsp unsalted butter","1 small garlic clove, minced","1/2 tsp ginger, minced (can exclude)","3 tsp shallots/scallions (green part) or chives, finely chopped"],"purpose":"Sauce"}]', '[{"description":"Take the steak out of the fridge 20 minutes prior to cooking (or 10 minutes if it''s a stinking hot summer day).","images":[],"step":1},{"description":"Combine soy sauce, Mirin and sake in a small bowl.","images":[],"step":2},{"description":"Heat oil in a skillet over medium high heat until smoking. Add steak and cook to your liking. Mine were 150g/5oz each and 3cm/1.25\" thick and I cooked it 3 minutes on the 1st side and 2 minutes on the second side for medium rare.","images":[],"step":3},{"description":"Transfer steak onto a plate and cover loosely with foil. Rest for 5 minutes.","duration":5,"images":[],"step":4},{"description":"Let the skillet cool down a bit then return to the stove over medium high heat. Add Sauce and bring to simmer, then add butter. When the butter melts and is incorporated into the sauce, immediately remove it from the stove.","images":[],"step":5},{"description":"Stir through garlic, ginger and 2 tsp of shallots (reserve rest for garnish), the sauce should be slightly thickened (if not, keep stirring, thickens more as it cools).","images":[],"step":6},{"description":"Place steak on plates and spoon over sauce. I served the steaks with finely shredded cabbage without dressing (very typical Japanese side) and white rice, plus some edamame on the side.","images":[],"step":7}]', '["gluten","milk","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef-recipes","modern-asian","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a138b4e67631', 'en', 'US', 'Beef Soba Noodle Bowl with Green Beans', 'A fusion Japanese soba noodle dish with an amazing dressing that matches perfectly with the juicy steak slices and for slurping up the soba noodles. Fantastic quick meal for hot summer nights!', 'https://www.recipetineats.com/tachyon/2017/03/Beef-Bean-and-Soba-Bowls.jpg', 5, 10, 15, 2, '[{"id": "ing_soy_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 3.0, "unit": "bottle"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_soba", "quantity": {"value": 6.0, "unit": "pack"}}, {"id": "ing_green_beans_trimmed", "quantity": {"value": 6.0, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 tbsp soy sauce, light or ordinary (Note 1)","2 1/2 tbsp peanut oil","3 tbsp rice vinegar (Note 2)","1 tbsp mirin (Note 3)","2 tsp brown sugar","2 tsp ginger, minced","1 clove garlic, minced"],"purpose":"Dressing"},{"ingredients":["200g/7 oz rump or sirloin beef steak, excess fat trimmed (Note 4)","1 tsp vegetable oil","6oz/180g soba (Note 5)","6oz/200g green beans, trimmed","1 scallion/shallot, finely sliced","1 tbsp crispy Asian Shallots (Note 6)"],"purpose":"Steak"}]', '[{"description":"Take the steak out of the fridge 30 minutes prior to cooking (or 15 minutes if it''s a stinking hot summer day).","images":[],"step":1},{"description":"Combine dressing ingredients in a jar and shake.","images":[],"step":2},{"description":"Heat the oil in a skillet over high heat until smoking, then cook the steak to your liking. I like mine medium rare - perfect for absorbing the flavours of the delicious dressing - so I cook this rump steak for 2 minutes on the first side and 1 minute 45 seconds on the second side.","duration":2,"images":[],"step":3},{"description":"Transfer to a plate and loosely cover with foil. Rest for 5 minutes, then slice into fairly thin slices against the grain (i.e. find the direction of the fibres then cut at a 90 degree angle straight through them).","duration":5,"images":[],"step":4},{"description":"Meanwhile, bring a pot of water to boil. Cook the soba according to packet instructions (usually 5 minutes). For the last 1 minute of cooking, add the green beans.","images":[],"step":5},{"description":"Drain the noodles and beans and rinse under cold water to stop them from cooking further and to cool the noodles. Roughly separate beans from noodles.","images":[],"step":6},{"description":"To serve, divide the noodles between 2 bowls, top with the beans then the steak slices. Drizzle with the dressing (over the steak and noodles), then garnish with shallot slices and Crispy Asian Shallots.","images":[],"step":7}]', '["gluten","peanuts","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef-recipes","dinner-tonight","main-dishes","modern-asian","noodles","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_35f1ebeeecf3', 'en', 'US', 'Chinese Pork with Noodles ("Chinese Bolognese")', 'Don''t be put off by the Asian speciality sauces, this is one of those recipes that still works GREAT using the substitutions. Some people may even prefer it made with the subs! . The proper name for this stir fried pork with noodles is "Zha Jiang Mian" noodles and is also affectionally referred to as "Chinese Bolognese". Minced / ground pork is stir fried with tasty classic Chinese flavours that are savoury with a touch of spice and sweet. Recipe video is below recipe.', 'https://www.recipetineats.com/tachyon/2016/12/Chinese-Pork-and-Noodles-7.jpg', 10, 10, 20, 3, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.5, "unit": "pack of 500g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_vinegar", "quantity": {"value": 0.02, "unit": "L"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_chinese_sweet_bean_sauce", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.002, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_pork", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["700 - 800 g / 1.4 - 1.6 lb white noodles (flour noodles), fresh (Note 1)","2 tsp vegetable oil*","2 tsp Chinese black vinegar (Chinkiang vinegar)* (Note 2)"],"purpose":"Noodles"},{"ingredients":["1/3 cup chicken stock / broth","1 tbsp Chilli Bean Sauce (Note 3)","1 tbsp Chinese Sweet Bean Sauce (Note 4)","1 tbsp dark soy sauce (Note 5)","2 tsp Chinese black vinegar (Chinkiang vinegar)* (Note 2)","1 tsp sugar (white or brown)"],"purpose":"Sauce"},{"ingredients":["1 tbsp vegetable oil","2 garlic cloves (, minced)","1 1/2 tsp ginger (, minced or finely chopped)","1/2 onion (, finely chopped (white, brown or yellow))","400 g / 14 oz minced pork (ground pork)"],"purpose":"Stir Fry"},{"ingredients":["2 cucumbers (, cut into batons (deseed if you can be bothered, I don''t!))","Chinese chilli sauce (Note 6)","Coriander / cilantro leaves"],"purpose":"To Serve"}]', '[{"description":"Mix Sauce ingredients together.","images":[],"step":1},{"description":"Prepare noodles according to packet directions. If it says to soak the noodles, you can do that while cooking the stir fry.","images":[],"step":2},{"title":"Optional","description":"Just before serving, toss the noodles with oil and vinegar.*","images":[],"step":3},{"description":"Heat oil in a wok or skillet over medium high heat. Add onions and cook for 1 minute. Add garlic and ginger and cook for 1 minute or until onion is translucent.","duration":1,"images":[],"step":4},{"description":"Add pork and cook, breaking it up as you go, until browned.","images":[],"step":5},{"title":"Add sauce and cook for 3","description":"5 minutes, or until most of the sauce has reduced.","duration":4,"images":[],"step":6},{"description":"Divide noodles between bowls. Top with pork, coriander and fresh cucumbers on the side.","images":[],"step":7},{"description":"To eat, mix up the noodles and pork. I use chopsticks and a spoon - so it''s easier to get the pork and noodles in one mouthful. Don''t hold back on the chilli paste! It goes great with this dish!","images":[],"step":8}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","chinese-recipes","dinner-tonight","main-dishes","noodles","pork-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f61e271fd51a', 'en', 'US', 'Spicy Thai Chicken Stir Fry', 'The Thai stir fry sauce used in this recipe is a fantastic versatile stir fry sauce! It''s similar to many well known Thai stir fries like Pad See Ew, Thai Chilli Basil Chicken and Drunken Noodles (Pad Kee Mao). Make this using ground/mince chicken, pork or turkey. See notes for how to use this sauce for other stir fries. Ensure all ingredients are ready to toss into the wok before you start cooking because once you start, it cooks fast!', 'https://www.recipetineats.com/tachyon/2016/11/Spicy-Thai-Chicken-Stir-Fry_4.jpg', 7, 8, 15, 3, '[{"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.008, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tsp light soy sauce (Note 1)","1 tsp dark soy sauce (Note 1)","2 tsp fish sauce","1 tbsp oyster sauce","1 tsp sugar"],"purpose":"Sauce"},{"ingredients":["2 tbsp cooking oil (I use peanut or vegetable oil)","3 Thai or birds eye chillis or other small hot red chilli (, finely chopped (Note 2))","4 garlic cloves (, finely chopped)","1 small onion (, halved and sliced (brown, white or yellow))","500 g / 1 lb ground / mince chicken","3 shallot / scallions stems (, chopped into slices)","1 cup coriander/cilantro leaves (loosely packed)"],"purpose":"Stir Fry"},{"ingredients":["Steamed jasmine rice"],"purpose":"Serving"}]', '[{"description":"Mix Sauce ingredients in a small bowl.","images":[],"step":1},{"description":"Heat oil in a wok or heavy based skillet over high heat. Add garlic and chilli - cook for 15 seconds.","duration":0.25,"images":[],"step":2},{"description":"Add onion and cook for 45 seconds.","duration":0.75,"images":[],"step":3},{"description":"Add chicken and cook, breaking it up as you go. When it changes from pink to white, add Sauce. Cook until the liquid mostly disappears - about 2 minutes.","images":[],"step":4},{"description":"Stir through shallots. Then stir through coriander and immediately take off the heat.","images":[],"step":5},{"title":"Serve immediately with jasmine rice or other rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Add slices of cucumber and tomato wedges (very authentic Thai!). Garnish with extra chilli and coriander if desired.","images":[],"step":6}]', '["fish","gluten","peanuts","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","chicken-breast-recipes","chicken-mince-recipes","chicken-recipes","cuisines","dinner-tonight","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","stir-fries","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d1e50df8d1cc', 'en', 'US', 'Lemon Pepper Chicken', 'A homemade version of lemon pepper chicken made without store-bought lemon pepper seasoning. It tastes incredible - fresh, fragrant with lovely pops of heat from the pepper. No marinating time required. Great for pork and seafood too! RECIPE VIDEO BELOW.', 'https://www.recipetineats.com/tachyon/2016/10/Lemon-Pepper-Chicken_5.jpg', 10, 5, 15, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.009, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.007, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 chicken breasts (~250 - 300g / 8 - 10oz each)","2 lemons (Note 1)","1 tbsp olive oil","3 tbsp flour","1/2 - 3/4 tsp salt","2 1/2 tsp cracked black pepper (adjust to taste) (Note 2)","1/2 tsp garlic powder (or sub with onion powder) (Note 3)"]},{"ingredients":["1 tbsp olive oil","Fresh parsley (, for garnish)"],"purpose":"Cooking"}]', '[{"description":"Cut the chicken in half horizontally to make 2 steaks. Optional: pound to make them even thickness around 1cm / 2/5\" thick (I do this).","images":[],"step":1},{"title":"Zest the lemons to make 1 1/2","description":"2 tbsp lemon zest. Avoid grating too much of the white part - it''s bitter.","images":[],"step":2},{"description":"Place zest into bowl with 1 tbsp olive oil and mix to combine. Add chicken and use your hands to slather oil mixture onto chicken.","images":[],"step":3},{"description":"Mix flour, salt, pepper and garlic powder in a shallow bowl.","images":[],"step":4},{"description":"Dip chicken into flour mixture, shaking to remove excess.","images":[],"step":5},{"description":"Heat oil in a skillet over medium high heat. Cook chicken for 2 minutes on each side, or until golden.","duration":2,"images":[],"step":6},{"title":"Optional","description":"Slice zested lemon and cook the slices, like pictured.","images":[],"step":7},{"description":"Serve chicken, garnished with fresh parsley if using.","images":[],"step":8}]', '["gluten"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_33ef46acfc29', 'en', 'US', 'Creamy Dill Sauce with Salmon or Trout', 'A fantastic quick meal! Dill Sauce is refreshing, rather than heavy as many "creamy" sauces can be, because it is made with sour cream. The slight acidity is a great pairing with salmon or trout which are quite rich and oily. I made this with trout.', 'https://www.recipetineats.com/tachyon/2016/09/Creamy-Dill-Sauce-with-Salmon_5.jpg', 10, 5, 15, 4, '[{"id": "ing_sour_cream", "quantity": {"value": 0.012, "unit": "tub of 250g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_dill", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 1.5, "unit": "net of 500g"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 0.045, "unit": "bottle"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["3/4 cup sour cream (1)","2 tsp Dijon or hot English mustard (2)","1/2 tsp garlic powder or 1 small garlic clove (, minced)","2 1/2 tbsp fresh dill (, finely chopped)","1 tsp lemon zest","1 - 2 tbsp lemon juice","2 tbsp milk (or olive oil, for richness)","1/4 - 1/2 tsp salt","1/2 tsp white sugar"],"purpose":"Dill Sauce"},{"ingredients":["1/2 - 1 tbsp oil","4 salmon or trout fillets (125g / 4oz each)","Salt and pepper"],"purpose":"Fish"}]', '[{"description":"Mix the Dill Sauce ingredients together (Mix well to loosen the sour cream). Adjust consistency with milk and tartness with lemon juice. Set aside for 10 minutes if you can - if using fresh garlic, set aside for 20 min.","duration":10,"images":[],"step":1},{"description":"Pat fish dry with paper towel. Sprinkle with salt and pepper.","images":[],"step":2},{"description":"Heat oil in skillet over medium high heat. Place fish in skillet skin side down. Cook for 2 minutes, then flip and cook the other side for 1 1/2 minutes.","duration":2,"images":[],"step":3},{"description":"Remove from skillet onto serving plates. Serve with Dill Sauce on the side, garnished with fresh dill and lemon wedges if desired.","images":[],"step":4}]', '["fish","milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","easter-mains-fish-seafood","easter-recipes","fish-recipes","gluten-free-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_867c1d0de072', 'en', 'US', 'Honey Lemon Chicken', 'Succulent chicken with a lip smacking honey-lemon sauce. Dinner in a snap - 5 minutes prep, 4 minutes to cook the chicken, 3 minutes for the sauce = 12 minute dinner! Dusting the chicken in flour makes the skin slightly crispy which makes the sauce cling to it. Recipe VIDEO below!', 'https://www.recipetineats.com/tachyon/2016/03/Honey-Lemon-Chicken_2.jpg', 5, 7, 12, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.002, "unit": "jar of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500g chicken breast (2 pieces)","Salt and pepper","1/4 cup / 35 g flour (any)"],"purpose":"Chicken"},{"ingredients":["1 1/2 tbsp butter","1 tbsp olive oil","1 garlic clove, minced","3/4 cup / 185 ml chicken broth / stock","1/4 cup / 85g honey","1/4 cup / 60 ml lemon juice (fresh)","1 tsp soy sauce","2 tbsp water"],"purpose":"Sauce"},{"ingredients":["Lemon slices","Finely chopped parsley"],"purpose":"To serve (optional)"}]', '[{"description":"Slice each chicken breast horizontally to form 4 steaks in total. OPTIONAL (for more even cooking): Pound to even thickness about 1cm/ 2/5\" thick.","images":[],"step":1},{"description":"Sprinkle each side generously with salt and pepper.","images":[],"step":2},{"description":"Place flour in shallow dish. Coat the chicken in the flour, shaking off excess.","images":[],"step":3},{"description":"Mix 1 tsp of the flour (reserved from step 3) with the water. Set aside.","images":[],"step":4},{"description":"Cooking","images":[],"step":5},{"description":"Place butter and oil in a skillet over medium high heat until butter is melted and hot. Add chicken and cook for 2 minutes or until golden brown. Turn and cook the other side until golden brown, then transfer onto a plate to rest.","duration":2,"images":[],"step":6},{"description":"Add garlic into the skillet and stir for 20 seconds or until golden. Add chicken broth / stock and bring to simmer. Use a spatula to scrape the brown bits from the bottom of the pan into the liquid.","duration":0.3333333333333333,"images":[],"step":7},{"description":"Add honey, lemon juice, soy sauce and flour/water mixture (from step 4) into the skillet. Mix and bring to simmer for 2 to 3 minutes until thickened into a syrup. Add salt and pepper to taste.","duration":2.5,"images":[],"step":8},{"description":"To serve, pour Sauce over the chicken and garnish with parsley and lemon slices if using. Alternatively, return the chicken to the pan for 30 seconds (to reheat), turning to coat in the sauce.","duration":0.5,"images":[],"step":9}]', '["gluten","milk","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0b62b8259ea8', 'en', 'US', 'Creamy Salmon Risoni / Orzo (15 Minute Meal)', 'A creamy risoni dinner in a flash! Get the ingredients out on the bench and it will take just 15 minutes to get this on the table. Watch the video to see how easy it is!', 'https://www.recipetineats.com/tachyon/2016/03/Creamy-Salmon-Risoni-Orzo_2.jpg', 5, 10, 15, 4, '[{"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_parmesan", "quantity": {"value": 0.005, "unit": "pack of 200g"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.5 oz / 40g / 3 tbsp unsalted butter","1/2 onion (, diced (brown, white, yellow))","2 garlic cloves (, minced)","1 tbsp plain flour","2 cups milk (light or full fat)","2 1/4 cups chicken broth / stock","1 1/2 cups dried risoni / orzo (Note 1)","2 cups frozen peas","1/2 cup grated parmesan","6 oz / 185 g hot-smoked salmon (, flaked into large chunks using 2 forks)","Parsley (, chopped, to garnish)"]}]', '[{"description":"Melt butter in a deep skillet or pot over medium high heat.","images":[],"step":1},{"description":"Add onion and garlic, cook for 2 minutes until translucent.","duration":2,"images":[],"step":2},{"description":"Add flour and cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Switch to a whisk and add half the milk. Whisk to dissolve the pasty onion mixture into the milk (about 20 seconds). Then add remaining milk, chicken broth, risoni and peas.","images":[],"step":4},{"description":"Bring to simmer then turn heat down to medium so it bubbles gently. Cook for 5 minutes - stir occasionally for the first half then more frequently during the second half.","duration":5,"images":[],"step":5},{"title":"At 5 minutes, take it off the stove","description":"it will still be quite saucy (see video) but will reduce in the next steps and while serving.","images":[],"step":6},{"description":"Stir through parmesan cheese, salt and pepper to taste. Then gently stir through salmon.","images":[],"step":7},{"description":"Serve immediately, sprinkled with parsley leaves if desired.","images":[],"step":8}]', '["fish","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dinner-tonight","fish-recipes","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9e8a6628d37f', 'en', 'US', 'Fish with Spicy Salsa', 'Super fast to prepare, this is a light, fresh, healthy dinner that''s a satisfying meal for less than 500 calories. By setting the salsa aside, it sweats and the juices become the "sauce" for this recipe without the need to use tons of oil! I made this spicy - Salsa Picante (which means spicy) - but you can just as just omit the chili if you prefer! I added eggplant slices to fill this out, add nutrition and interest to the dish - but this is optional.', 'https://www.recipetineats.com/tachyon/2016/03/Italian-Fish-Spicy-Salsa_4.jpg', 5, 10, 15, 2, '[{"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 6.0, "unit": "carton of 12"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}]', '[{"ingredients":["2 ripe tomatoes (, deseeded and diced (Note 1))","1/2 tsp fresh chili (, finely chopped (or 1/4 tsp red pepper flakes))","2 tsp extra virgin olive oil","1/4 tsp salt","Black pepper","1/4 cup , packed, basil leaves"],"purpose":"Spicy Salsa"},{"ingredients":["6 slices eggplant (, 1cm / 1/2\" thick)","2 x 150g / 5oz fish fillets (I used perch)","Salt and pepper","1 tbsp plain flour","1 tbsp oil"],"purpose":"Fish"},{"ingredients":["4 slices sourdough bread (, toasted)"],"purpose":"To Serve"}]', '[{"description":"Combine the Spicy Salsa ingredients except basil in a bowl. Set aside for 20 minutes to sweat so juices seep and the tomatoes soften.","duration":20,"images":[],"step":1},{"description":"Season eggplant and fish generously with salt and pepper. Then dust fish with flour, shaking off excess.","images":[],"step":2},{"description":"Heat 1/2 tbsp oil in a non stick skillet over high heat. Add the eggplant and cook each side until charred and softened - about 2 minutes first side, 1 1/2 minutes second side. Remove onto a plate.","images":[],"step":3},{"description":"Heat remaining oil. Add fish and cook until light golden on both sides, pressing down with an egg flip to brown it evenly.","images":[],"step":4},{"description":"Tear basil leaves with your hands and toss through the salsa.","images":[],"step":5},{"description":"To serve, place 3 eggplants on each plate, top with a piece of fish and spoon over the salsa + juices. Serve with toasted sourdough on the side.","images":[],"step":6}]', '["fish","gluten"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dietary","dinner-tonight","fish-recipes","italian-recipes","low-calorie-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e04cc7b5370c', 'en', 'US', 'Cajun Blackened Fish {+ Video}', '"Blackening" is a classic Cajun cooking technique which involves searing spice coated seafood and meats in a hot skillet so the rub turns black (but not burnt). I think the black crust and white juicy flesh inside looks so stunning! I served this with a simple Corn Butter Rice Salad - refer to the Notes for the recipe. This is adapted from this Blackened Fish Tacos recipe, a guest post here on RecipeTin Eats by Kathleen of Hapa Nom Nom. Watch the video on my YouTube Channel!', 'https://www.recipetineats.com/tachyon/2016/02/Cajun-Blackened-Fish_3.jpg', 5, 5, 10, 4, '[{"id": "ing_paprika", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["1 tbsp paprika","1 tsp ground cumin","1 tsp onion powder","1 tsp garlic powder","1 tsp dried thyme","1 tsp dry mustard","3/4 tsp salt (table salt)","1/8 tsp cayenne pepper (or to taste)","Good grind of black pepper"],"purpose":"Spice Mix"},{"ingredients":["4 firm white fish fillets (about 150g/5oz each) (Note 1)","2 tbsp extra virgin olive oil"],"purpose":"To Cook"}]', '[{"description":"Combine Spice Mix in a shallow dish and mix.","images":[],"step":1},{"description":"Coat both sides of the fish fillets with the Spice Mix, shaking off excess.","images":[],"step":2},{"description":"Heat oil in a large heavy based skillet over medium high heat.","images":[],"step":3},{"description":"Add fish and cook until the rub turns black, then flip and cook the other side until the fish is cooked to your taste. (Note 2)","images":[],"step":4},{"description":"Serve immediately. I served mine with a buttery Corn Rice Salad - refer to the Notes for the recipe.","images":[],"step":5}]', '["fish","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Cajun"],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","grilling-ideas-and-recipes","low-calorie-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_592f9a715eb2', 'en', 'US', 'Grilled Eggplant with Yoghurt Sauce', 'This is adapted from a recipe by Karen Martini, a great Australian chef. Simple to make and so incredibly delicious. A "meaty" meat free dish for carnivores! I have noted where I strayed from the original recipe. This serves 3 to 4 as a light meal (accompanied with, for example, couscous), or 6 to 8 as a side.', 'https://www.recipetineats.com/tachyon/2015/01/DSC_0489.jpg', 8, 7, 15, 3, '[{"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.4, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_tahini", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pomegranate", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_mint", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["3 large eggplants","1/4 cup olive oil","Salt and pepper"],"purpose":"Grilled Eggplant"},{"ingredients":["1 cup plain unsweetened yoghurt (Greek or natural)","1 garlic clove (, minced (Medium size. 1 large clove will make it too garlicky))","1 tsp cumin powder (Note 1)","1 to 2 tbsp fresh lemon juice (use amount to taste) (Note 2)","2 tbsp tahini (sesame paste) (you can leave this out if you don''t have it, it is still a tasty sauce)","1/4 tsp salt (, slightly heaped (about 3/8 tsp))","Black pepper"],"purpose":"Yoghurt Sauce"},{"ingredients":["1/2 pomegranate (, seeds only (Note 3))","2 tbsp mint leaves (, finely sliced)","2 tbsp coriander / cilantro leaves","Red chilli (, finely sliced (to taste) (Note 4))","Wedges or cheeks of lemon (optional)"],"purpose":"Garnish"}]', '[{"description":"Combine the Yoghurt Sauce ingredients in a bowl and mix well. Set aside for the flavours to develop. The longer you leave it, the better it will taste.","images":[],"step":1},{"description":"Use a potato peeler to peel \"strips\" off the eggplant vertically as per the photo below. If your potato peeler is not sharp enough or if the eggplant is on the soft side, you might need to do this with a small sharp knife.","images":[],"step":2},{"description":"Cut the eggplant into 1.5cm / 2/3\" thick rounds.","images":[],"step":3},{"description":"Brush one side of each eggplant with olive oil. The more you use, the yummier it will be!","images":[],"step":4},{"description":"Sprinkle the oiled side of the eggplant with salt and pepper.","images":[],"step":5},{"description":"Heat a griddle pan (or BBQ) on medium high heat. (Note 5)","images":[],"step":6},{"description":"Place the oiled side of each eggplant onto the pan and grill for 2 to 3 minutes until it gets deep char lines on it. While the first side is cooking, brush the other side of each eggplant with the remaining olive oil and sprinkle with salt and pepper.","duration":2.5,"images":[],"step":7},{"description":"Turn the eggplant and cook the other side until the eggplant is cooked through but still holding it''s shape. The easy way to tell is to prod the centre - if you feel resistance, it needs to cook more.","images":[],"step":8},{"description":"Remove the eggplant onto a serving plate and let it cool for a few minutes. Then spoon a dollop of the yoghurt sauce on each, and scatter with coriander/cilantro, mint, pomegranate seeds and chili. Drizzle with extra olive oil and serve with cheeks or wedges of lemon, if desired.","images":[],"step":9}]', '["milk","sesame"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Contemporary Middle Eastern"],"categories":["all-vegetable-sides","cuisines","dietary","easter-sides-warm-hearty","eggplant","gluten-free-recipes","grilling-ideas-and-recipes","middle-eastern-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3efd06e449ae', 'en', 'US', 'Super Quick Chicken Dinner: Crumbed Chicken with Mashed Potatoes', 'With few clever shortcuts and a bit of multi tasking, you''ll get this complete dinner on the table in 15 minutes. The crunchy crumbed chicken is sensational. The secret is mayonnaise which is used to make the panko breadcrumbs stick to the chicken, plus it provides the seasoning.', 'https://www.recipetineats.com/tachyon/2014/12/Fast-Crumbed-Chicken-1.jpg', 5, 10, 15, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.15, "unit": "jar of 400g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_bread", "quantity": {"value": 6.0, "unit": "loaf"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["400 g / 13oz chicken breast minute steaks (4 pieces x 100g/3oz each) (Note 1)","4 tbsp mayonnaise (, preferably whole egg (Note 2))","2 tbsp parmesan cheese (, grated)","6 tbsp panko breadcrumbs (Note 3)"],"purpose":"Chicken"},{"ingredients":["2 medium potatoes ((Note 4), not peeled)","1/4 to 1/2 cup milk (full fat or low fat)","1 tbsp butter (optional)","Salt and pepper (, to taste)"],"purpose":"Fast Mashed Potato"},{"ingredients":["1 large cucumber (or 2 small cucumbers)","1 punnet cherry tomatoes (or 2 medium tomatoes)","1 tbsp lemon juice","2 tbsp olive oil","Salt and pepper (, to taste)"],"purpose":"Salad"}]', '[{"description":"Turn grill/broiler on high and place the shelf about 20cm/8\" from the heat source.","images":[],"step":1},{"description":"Place potatoes in the microwave and cook on high for 3 minutes. Then turn the potatoes over and cook on high for a further 2 minutes (or until cooked). Squeeze the potatoes to check if they are cooked.","duration":3,"images":[],"step":2},{"description":"Mix the mayonnaise and parmesan cheese in a small bowl.","images":[],"step":3},{"description":"Place the chicken in a large oven proof fry pan (Note 5). Using the back of a spoon, spread the mayonnaise mixture over each chicken breast.","images":[],"step":4},{"description":"Sprinkle panko breadcrumbs over each piece of chicken. Use your fingers to pat the panko so it sticks to the chicken. (Note 6)","images":[],"step":5},{"description":"Place chicken under the grill/broiler for 8 minutes, or until just cooked through and the crumbs are golden. Check it once at around 6 minutes and rotate the fry pan if necessary so the crumb cooks evenly all over. When cooked, set aside to rest for a few minutes before serving.","duration":8,"images":[],"step":6},{"description":"While the chicken is cooking, get the potatoes out of the microwave (use a dishcloth). Cut each potato in half, then use a dessert spoon to scoop the flesh out into a bowl. Add milk, butter, salt and pepper. Use a potato masher to mash. Add more milk to achieve the desired consistency.","images":[],"step":7},{"title":"Salad","description":"Use a potato peeler to make ribbons from the cucumber. Cut the cherry tomatoes in half. Pile the cucumber and cherry tomatoes onto a plate, then drizzle over lemon juice, olive oil and scatter with salt and pepper.","images":[],"step":8},{"title":"To Serve","description":"Place mashed potato on each plate then top with the chicken. Drizzle with extra olive oil and garnish with finely chopped fresh parsley, if desired. Serve the Salad on the side.","images":[],"step":9}]', '["egg","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_79b19833d9ef', 'en', 'US', 'Pea, Zucchini and Pesto Orzo (Risoni)', 'This is a great super quick midweek meal. It''s better made with homemade pesto, but store bought is fine too. I store homemade pesto in the freezer by pouring it into ice cube trays. That way I have serving size portions of pesto on hand when I need it. Sometimes I stir through frozen spinach to add more nutrition into this.', 'https://www.recipetineats.com/tachyon/2014/11/Green-Vegetable-Pesto-Risoni-Orzo-51.jpg', 5, 10, 15, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_zucchini", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["2/3 cup risoni","1 tbsp olive oil","2 1/2 tbsp basil pesto (, preferably homemade (see notes for recipe))","1 small onion ((brown, yellow or white), diced)","1 garlic clove (, crushed)","3 cups zucchini (, diced)","1 cup frozen peas (, preferably defrosted)","1/4 tsp salt","Black pepper"]},{"ingredients":["Parmesan cheese (, freshly grated)"],"purpose":"To Serve"}]', '[{"description":"Place about 8 cups of water in a large saucepan and bring to boil.","images":[],"step":1},{"description":"Add risoni and cook for 4 minutes, then add peas and cook for a further 1 minute. Note: The risoni will be slightly underdone at this point. It will finish cooking in the remaining steps.","duration":4,"images":[],"step":2},{"description":"Scoop out 1/2 cup of the water from the saucepan, then drain the risoni and set aside until ready to add to the pan.","images":[],"step":3},{"description":"Heat olive oil in a fry pan over medium high heat.","images":[],"step":4},{"description":"Add garlic and onion and sauté for 1 minute until starting to soften.","duration":1,"images":[],"step":5},{"title":"Add zucchini and sauté for a further 2","description":"3 minutes until both the zucchini and onion are softened and the onion is starting to turn a light golden brown.","images":[],"step":6},{"description":"Add pesto, risoni, pasta water reserved in step 3, salt and pepper. Bring the water to a simmer and stir for 1 minute until the water is absorbed.","duration":1,"images":[],"step":7},{"description":"Serve immediately, garnished with freshly grated parmesan.","images":[],"step":8}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","gluten-free-recipes","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e3c745336ab5', 'en', 'US', 'Fish Piccata With Crispy Smashed Potatoes (15 Minute Meal)', 'It''s amazing what you can make in 15 minutes (from scratch) if you get a bit creative! Make this with fresh fish or good quality frozen fish. I made these with beans but I often make it with asparagus and broccolini. You can really use any vegetables you want as long as they cook quickly in a pan with just a bit of braising liquid.', 'https://www.recipetineats.com/tachyon/2014/10/Fish-Piccata-Smashed-Potatoes-Green-Beans-15-minutes.jpg', 5, 10, 15, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 6.0, "unit": "bag of 2kg"}}, {"id": "ing_green_beans", "quantity": {"value": 7.0, "unit": "pack"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.5, "unit": "net of 500g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_baby_capers", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 pieces firm white fish fillets (around 150 - 200g / 5 - 7 oz each) (with or without skin, your choice) (see notes)","6 baby / chat / new potatoes (about the size of a golf ball) (see notes)","7 oz / 200 g green beans (, trimmed)","1 tbsp fresh parsley (, finely chopped)","2 tbsp olive oil","3 tbsp plain flour","1 tsp salt","Black pepper"]},{"ingredients":["1/3 cup white wine","1/2 cup water","1 - 2 tbsp fresh lemon juice (adjust to your taste)","2 tbsp butter","1 tbsp baby capers (canned)","Salt and pepper"],"purpose":"Sauce"}]', '[{"description":"Cook the potatoes in the microwave for 2 minutes, turn potatoes, then cook for another 1 1/2 - 2 minutes. You will be able to tell by squeezing them if they are ready. Don''t worry if the skin bursts, you are smashing them anyway.","duration":2,"images":[],"step":1},{"description":"Use the side of a knife, meat mallet or your hand (covered with a dish cloth) and smash each potato so they are flattened to around 1.5cm/ 0.5\" thick with a flattish surface. Sprinkle with a pinch of salt.","images":[],"step":2},{"description":"Meanwhile, combine flour, salt and pepper on a plate and dredge each side of the fish in the flour mixture. Shake off excess flour.","images":[],"step":3},{"description":"Heat olive oil in a non stick pan over high heat. Place fish and potatoes in the pan. Press the potatoes down lightly with a spatula to help it crisp up.","images":[],"step":4},{"description":"Cook the first side of both the fish and potatoes for around 2 minutes until golden brown, then turn. Make sure the potato is crispy and brown.","images":[],"step":5},{"description":"Cook the other side of the fish for 1 1/2 minutes (also see notes for fish cooking time). Then remove from the pan onto a plate and cover loosely with foil.","images":[],"step":6},{"description":"Give the potatoes another 30 seconds to 1 minute to make it nice and brown and crispy, then remove from the pan.","images":[],"step":7},{"description":"Turn heat down to medium high.","images":[],"step":8},{"description":"Add wine and water to the pan. Scrape the brown bits off the bottom of the pan and mix it in. When the liquid comes to a rapid simmer, add the beans.","images":[],"step":9},{"description":"Shake the pan occasionally to help the beans cook evenly. Cook the beans in the liquid for around 1 1/2 minutes until \"tender crisp\" (i.e. cooked but still crisp) and remove from pan. If the liquid reduces too much while cooking the beans (which might be the case if you are using a very large heavy based pan), just add a splash of water.","images":[],"step":10},{"description":"Remove pan from heat. By the time you remove the beans, there should just be a bit of sauce left at the bottom of the fry pan, not even covering the entire base of the fry pan.","images":[],"step":11},{"description":"Add lemon juice then stir through butter and capers. Adjust seasoning to taste with salt and pepper.","images":[],"step":12},{"description":"To Serve","images":[],"step":13},{"description":"Place half the beans on each plate and place 3 potatoes on top. Top with a piece of fish. Spoon over the Sauce onto each fish and scatter with parsley. Serve immediately.","images":[],"step":14}]', '["fish","gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_12e89ad9167d', 'en', 'US', 'Lemon Pepper Pork', 'A complete meal on the table in just 15 minutes! Made from scratch, so fresh and easy.', 'https://www.recipetineats.com/tachyon/2014/09/Lemon-Pepper-Pork-Grilled-Veg-Feta-Couscous-4.jpg', 5, 10, 15, 2, '[{"id": "ing_pork", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.037, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_zucchini", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.5, "unit": "net of 500g"}}, {"id": "ing_mint", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_couscous", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["2 pork cutlets (, at room temperature (200g/7oz each, bone in) (see notes))","1 tbsp lemon pepper (see notes)","2 tbsp olive oil (, separated)","2 zucchinis (, sliced)","1 small red capsicum ((bell pepper), sliced)","1 small red onion ((spanish onion), sliced)","1/2 small lemon","1/4 cup mint leaves (loosely packed)","1/2 cup couscous","1/2 cup boiling water (or chicken or vegetable stock/broth)","50 g / 1.5 oz g / 1.5 oz feta cheese","Salt and pepper","Lemon wedges or cheeks (, to serve (optional))"]}]', '[{"description":"Combine couscous and boiling water in a bowl, cover with cling wrap and set aside for 5 minutes.","duration":5,"images":[],"step":1},{"description":"Sprinkle lemon pepper on both sides of each cutlet and pat to make it stick.","images":[],"step":2},{"description":"Heat 1 tbsp olive oil in fry pan over high heat. Place pork in fry pan and cook the first side for 2 minutes and the second side for 1 1/2 minutes or until cooked to your liking. I like mine medium rare. Remember the pork will continue to cook while resting.","duration":2,"images":[],"step":3},{"description":"Remove pork from the fry pan onto a plate, cover loosely with foil and set aside to rest.","images":[],"step":4},{"description":"Heat remaining 1 tbsp olive oil in the fry pan still on high heat. Add onion and capsicum and sauté for 1 minute, then add the zucchini. Stir and cook the vegetables until charred and just cooked through. Remove pan from heat.","duration":1,"images":[],"step":5},{"description":"Fluff up the couscous with a fork. Add the vegetables and mint leaves. Squeeze over a drizzle of lemon juice and season to taste with salt and pepper. Toss gently to combine.","images":[],"step":6},{"description":"Divide couscous between plates, scatter over feta cheese. Top with pork cutlet and drizzle over resting juices. Serve with lemon cheeks or wedges on the side, if using.","images":[],"step":7}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","pork-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ab018d3a384c', 'en', 'US', 'Chicken Marsala', 'Recipe video above. A beloved Italian-American classic comprised of a crispy golden chicken cutlet smothered in a rich Marsala wine flavoured mushroom sauce. A restaurant favourite that''s easy to make at home, one bite and you''ll be hooked for life like I was!The key flavour here is Marsala wine so if you can''t consume alcohol or don''t have it, make Chicken in Creamy Mushroom Sauce instead! Also, this dish uses more alcohol than my usual "just a splash of wine" so it''s not recommended for kids. :)', 'https://www.recipetineats.com/tachyon/2023/06/Chicken-Marsala_0b.jpg', 10, 15, 25, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_eschalots", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 large chicken breasts (300g/10oz each), cut in half horizontally (or 4 thighs, Note 1)","1/2 tsp cooking salt / kosher salt","1/2 tsp black pepper","1/4 cup flour (, plain/all-purpose)"],"purpose":"Golden crusted chicken:"},{"ingredients":["2 tbsp extra virgin olive oil","2 tbsp / 30g unsalted butter","2 eschalots (US: shallots), peeled and cut into 1cm / 1/3\" squares (Note 2)","1 garlic (, finely minced)","2 cups white mushrooms (, sliced 0.5cm / 1/5\" thick)","1 cup dry marsala wine (Note 3)","1/2 cup chicken stock/broth (, low sodium)","1/2 cup thickened / heavy cream ( (Note 4))","1/4 tsp cooking salt / kosher salt","1/8 tsp black pepper","1 tbsp finely chopped parsley (, for garnish (optional))"],"purpose":"Marsala sauce:"}]', '[{"description":"Chicken escalopes:","images":[],"step":1},{"title":"Pound","description":"Cut each breast in half to form 2 thin steaks. Cover with a freezer bag or Go-Between (Note 5) and pound to 1 cm / 0.4″ thickness using a meat mallet or rolling pin. This tenderises and ensures even cooking of the chicken.","images":[],"step":2},{"title":"Dust","description":"Sprinkle the surface with half the salt, pepper then flour. Lightly rub flour across surface, turn and repeat with remaining salt, pepper and flour. Shake excess flour off each piece just before cooking.","images":[],"step":3},{"title":"Cook","description":"Put half the butter and oil in a large non-stick pan over medium high heat. Once the butter is melted and foamy, place chicken in, then cook for 3 to 4 minutes until it''s gorgeously golden and crispy. Turn and cook the other side for 2 minutes. Remove onto a plate.","duration":3.5,"images":[],"step":4},{"description":"Creamy marsala sauce:","images":[],"step":5},{"title":"Sauté aromatics","description":"In the same pan, add remaining butter and oil. Once butter is melted, add eschalots and garlic. Cook for 1 minute.","duration":1,"images":[],"step":6},{"title":"Cook mushrooms","description":"Add mushrooms. Cook for 3 minutes, stirring regularly.","duration":3,"images":[],"step":7},{"title":"Reduce marsala","description":"Add marsala, turn up heat to high and boil for 3 minutes or until reduced by half.","duration":3,"images":[],"step":8},{"title":"Thicken sauce","description":"Add chicken stock, cream, salt and pepper. Stir, then lower heat so it''s simmering (not boiling rapidly) and simmer for 3 to 5 minutes until the sauce thickens to a cream consistency (not too thick, will thicken more).","duration":4,"images":[],"step":9},{"title":"Rewarm chicken","description":"Nestle chicken into sauce and leave for 30 seconds to reheat.","duration":0.5,"images":[],"step":10},{"description":"Serve! Take off the stove. Sprinkle with parsley, serve over starchy vehicle of choice (I chose mash. Rice, small pasta, polenta or bread for plate mopping also work well!).","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Italian-American"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9bb071c80b13', 'en', 'US', 'Greek Lamb and Salad Dinner', 'A super quick Greek dinner!', 'https://www.recipetineats.com/tachyon/2014/08/Greek-lamb-salad-dinner-4.jpg', 10, 5, 15, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.5, "unit": "pack of 3 heads"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_olives", "quantity": {"value": 16.0, "unit": "bottle"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 8.0, "unit": "loaf"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_honey", "quantity": {"value": 0.02, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.001, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["600 g / 20 oz lamb steaks (4 pieces in total)","2 large cucumbers","4 medium tomatoes","1 red onion (spanish onion)","1/2 cup (combined) parsley and mint leaves","1/2 small garlic clove","1/4 cup crumbled feta cheese","16 olives (black or green)","2 tsp dried oregano","8 slices sourdough bread","Salt and pepper"]},{"ingredients":["1/2 cup extra virgin olive oil","1/4 cup lemon juice","2 tsp honey","1/2 garlic clove (, minced)","1 tsp salt","Black pepper"],"purpose":"Dressing"}]', '[{"description":"Combine the Dressing ingredients and mix well (or put in a jar and shake).","images":[],"step":1},{"description":"Pour 1/4 cup of the Dressing, dried oregano, and a pinch of salt and pepper onto the lamb steaks and use your hands to coat evenly.","images":[],"step":2},{"title":"To freeze","description":"Place the lamb and marinade in a ziplock bag, remove as much air as possible and freeze. To cook, defrost completely and bring back to room temperature.","images":[],"step":3},{"description":"Heat BBQ (grill) or a heavy based pan on the stove over high heat.","images":[],"step":4},{"description":"Remove lamb from marinade. Place lamb on BBQ (or in the pan) and grill each side for 1 to 1 1/2 minutes, or until cooked to your liking. Remove lamb steaks from the BBQ / pan onto a plate and cover loosely with foil to rest.","images":[],"step":5},{"description":"Cut cucumber vertically into 8 pieces.","images":[],"step":6},{"description":"Cut tomatoes into thick slices.","images":[],"step":7},{"description":"Peel red onion and slice finely.","images":[],"step":8},{"description":"Toast bread, either in the toaster or on the BBQ/grill. While still warm, rub lightly with the cut side of the garlic. Optional: drizzle with extra olive oil.","images":[],"step":9},{"description":"Slice lamb into thin slices.","images":[],"step":10},{"description":"Place 4 slices of cucumber on each plate and top with tomato slices, red onion and olives.","images":[],"step":11},{"description":"Place lamb on top, sprinkle over the feta, parsley and mint leaves.","images":[],"step":12},{"description":"Drizzle over Dressing and serve with toasted bread on the side.","images":[],"step":13}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["dinner-tonight","greek-recipes","grilling-ideas-and-recipes","lamb-recipes","main-dishes","mediterranean-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3b426a11fb45', 'en', 'US', '8 simple Italian Pasta Recipes', 'These pasta recipes are simple Italian classics you''ll find in trattorias all across Italy. “Pantry” meals that take less than 15 minutes to make, each makes enough for 6 people. For all recipes, follow the Base Steps then move onto the recipe specific steps.Use the recipe slider to change the serving size. Key step (especially for simple pastas like these) - tossing the sauce with the cooked pasta and a splash of pasta cooking water. The fat in the sauce reacts with the starch in the cooking water, thickening the sauce and making it stick to the pasta strands. This is the proper way to make pasta - no self respecting Italian or restaurant would ever skip this step!', 'https://www.recipetineats.com/tachyon/2014/06/Pasta1.jpg', 5, 15, 20, 6, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 5.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.05, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 0.06, "unit": "pack of 100g"}}, {"id": "ing_parsley", "quantity": {"value": 5.0, "unit": "bunch"}}, {"id": "ing_canned_tomatoes", "quantity": {"value": 91.0, "unit": "can of 400g"}}, {"id": "ing_chilli", "quantity": {"value": 0.06, "unit": "pack of 100g"}}, {"id": "ing_anchovies", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_thinly_guanciale", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 24.0, "unit": "punnet of 250g"}}, {"id": "ing_basil", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_black_olives", "quantity": {"value": 4.0, "unit": "bottle"}}, {"id": "ing_capers", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_tinned_tuna", "quantity": {"value": 5.0, "unit": "pack"}}]', '[{"ingredients":["1 lb/500 g dried spaghetti (or other long pasta)"]},{"ingredients":["1/2 cup extra virgin olive oil","10 garlic cloves (, sliced)","1 tbsp red chilli flakes","1/4 cup chopped parsley"],"purpose":"PASTA WITH OLIVE OIL & GARLIC (AGLIO E OLIO):"},{"ingredients":["1/4 cup extra virgin olive oil","2 garlic cloves (, crushed)","21 oz / 600g crushed tinned tomatoes","2 tbsp chilli flakes","1/4 cup chopped parsley"],"purpose":"FIERY PASTA (ARRABIATA):"},{"ingredients":["1/3 cup extra virgin olive oil","2 garlic cloves (, crushed)","2 tbsp anchovies (, finely chopped)","1 tbsp red chilli flakes","1/4 cup chopped parsley"],"purpose":"PASTA WITH ANCHOVIES (SPAGHETTI CON LE ACCIUGHE):"},{"ingredients":["2 tbsp extra virgin olive oil","2 garlic cloves (, crushed)","1/2 brown onion (, diced)","14 oz/400g crushed tinned tomatoes","1/2 tsp red chilli flakes","6 oz/ 180g thinly sliced guanciale (, or diced pancetta or bacon)"],"purpose":"AMATRICE SPAGHETTI (SPAGHETTI ALL’AMATRICIANA):"},{"ingredients":["4 tbsp extra virgin olive oil","2 garlic cloves (, crushed)","24 oz/800g fresh cherry tomatoes (, halved)","1/4 cup fresh basil (, lightly packed)"],"purpose":"FRESH TOMATO & BASIL SAUCE (POMAROLA):"},{"ingredients":["1/4 cup olive oil","3 garlic cloves (, crushed)","1 brown onion (, diced)","28 oz / 800g crushed tinned tomatoes","1/4 cup fresh basil (, lightly packed)"],"purpose":"TOMATO SPAGHETTI (SPAGHETTI NAPOLITANA):"},{"ingredients":["1/4 cup extra virgin olive oil","2 garlic cloves (, crushed)","14 oz/400g crushed tinned tomatoes","1/2 tbsp red chilli flakes","4 oz/100g black sliced olives","2 tbsp capers","1/4 cup chopped parsley"],"purpose":"SPAGHETTI WITH OLIVES AND CAPERS (SPAGHETTI ALLA PUTTANESCA):"},{"ingredients":["1/4 cup extra virgin olive oil","2 garlic cloves (, crushed)","1/2 brown onion (, diced)","14 oz/400g crushed tinned tomatoes","5 oz/150g tinned tuna","1/4 cup chopped parsley"],"purpose":"PASTA WITH TUNA (SPAGHETTI AL TONNO):"}]', '[{"description":"Base Directions (for All):","images":[],"step":1},{"description":"Cook 1lb/500g of dried spaghetti (or any other long dried pasta) in a large pot of salted boiling water per packet MINUS 1 minute.","images":[],"step":2},{"description":"Meanwhile, prepare one of the sauces below.","images":[],"step":3},{"description":"When pasta is ready, scoop out 1 cup of pasta cooking water, and drain pasta.","images":[],"step":4},{"description":"Add pasta into chosen sauce with 3/4 cup pasta cooking water. Toss pasta until sauce thickens and sticks to pasta (called \"emulsifying\" the sauce), 1 - 2 minutes. Use more pasta water if needed to loosen sauce.","images":[],"step":5},{"description":"Season with salt and pepper to taste. Finish pasta per chosen recipe.","images":[],"step":6},{"description":"PASTA WITH OLIVE OIL & GARLIC (AGLIO E OLIO):","images":[],"step":7},{"description":"Heat oil over medium high heat. Add garlic and cook until golden - be careful not to burn it.","images":[],"step":8},{"description":"Toss with pasta and cooking water per Base Directions. Toss through parsley and chilli flakes, serve with parmesan.","images":[],"step":9},{"description":"Heat oil over medium high heat. Add garlic, stir until fragrant, then add the tinned tomatoes and chilli flakes, simmer on medium for 5 minutes.","duration":5,"images":[],"step":10},{"description":"Toss with pasta and cooking water per Base Directions. Toss through parsley and serve with parmesan.","images":[],"step":11},{"description":"PASTA WITH ANCHOVIES (SPAGHETTI CON LE ACCIUGHE):","images":[],"step":12},{"description":"Heat oil over medium high heat. Add garlic and anchovies, stir until the garlic is fragrant and the anchovies have melted.","images":[],"step":13},{"description":"Toss with pasta and cooking water per Base Directions. Toss through parsley and chilli flakes, and serve with parmesan.","images":[],"step":14},{"description":"AMATRICE SPAGHETTI (SPAGHETTI ALL’AMATRICIANA):","images":[],"step":15},{"description":"Heat oil over medium high heat. Add the garlic, onion and guanciale (or pancetta or bacon) and cook until the onion has softened and the guanciale is golden.","images":[],"step":16},{"description":"Add the tinned tomatoes and chilli flakes and bring to rapid simmer. Toss with pasta and cooking water per Base Directions. Serve with parmesan.","images":[],"step":17},{"description":"Heat oil over medium high heat. Add garlic and cook until fragrant, add tomato and cook briefly, just to warm through.","images":[],"step":18},{"description":"Toss with pasta and cooking water per Base Directions. Toss through basil, serve with parmesan.","images":[],"step":19},{"description":"TOMATO SPAGHETTI (SPAGHETTI NAPOLITANA):","images":[],"step":20},{"description":"Heat oil over medium high heat. Add garlic and cook until fragrant, then add the onion and cook until softened. Then add tinned tomatoes and 1/2 cup water, simmer 5 minutes.","images":[],"step":21},{"description":"Toss with pasta and cooking water per Base Directions. Toss through basil and serve with parmesan.","images":[],"step":22},{"description":"SPAGHETTI WITH OLIVES AND CAPERS (SPAGHETTI ALLA PUTTANESCA):","images":[],"step":23},{"description":"Heat oil over medium high heat. Add garlic and cook until fragrant, then add tinned tomatoes, chilli flakes, olives, capers and 1/2 cup water. Simmer 3 minutes.","images":[],"step":24},{"description":"Toss with pasta and cooking water per Base Directions. Toss through parsley and serve with parmesan.","images":[],"step":25},{"description":"Heat oil over medium high heat. Add garlic and cook until fragrant. Add the onion and cook until softened, then add the tinned tomatoes and 1/2 cup water. Simmer 3 minutes, then add the tuna.","images":[],"step":26},{"description":"Toss with pasta and cooking water per Base Directions. Toss through parsley. Seafood pasta typically not served with parmesan but you can if you want!","images":[],"step":27}]', '["fish","gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["italian-recipes","most-popular","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e6fcbcb0b379', 'en', 'US', 'Vegetable Tian', 'Recipe video above. I love this colourful Provençal vegetable bake! It’s full of vibrant colours and lovely garlicky Mediterranean flavours, making it just as good as a side dish as it is a vegetarian main. While it feels especially at home alongside French and Mediterranean food, the flavours are so adaptable that it will happily sit beside almost any Western-style meal.Enjoy warm or at room temperature.', 'https://www.recipetineats.com/tachyon/2026/06/Vegetable-tian-5a.jpg', 30, 40, 70, 6, '[{"id": "ing_olive_oil", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.008, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_zucchini", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_herbes_de_provence", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["6 tbsp extra virgin olive oil","4 garlic cloves (, finely minced with a knife)","2 tbsp tomato paste","1 eggplant (aubergine), cut in half lengthways then sliced 8mm / 0.3” half moons (~380g / 13.5oz)","3 zucchini (courgette), sliced into 6mm / 0.25” rounds (~180g / 6oz each)","3 red onion (, sliced into 3mm / 0.1” rounds (~140g / 5oz each) (use a mandolin if you have one))","5 tomato (, sliced into 5mm / 0.2” rounds (~140g / 5oz each))","2 tsp cooking / kosher salt (, (or half for table salt, +50% for flakes))","1/2 tsp black pepper","1 1/2 tsp herbes de Provence"]}]', '[{"description":"Sweat the eggplant and zucchini, spread oil, tomato paste and garlic in a dish. Arrange vegetables, alternating, drizzle/sprinkle with oil, Herbs de Provence, salt and pepper. Bake 40 minutes.","images":[],"step":1},{"title":"Preheat oven","description":"Preheat oven to 200°C / 400°F (180°C fan-forced).","images":[],"step":2},{"title":"Sweat eggplant and zucchini","description":"Toss eggplant and zucchini slices in a bowl with 1 teaspoon of salt. Place them in colander over bowl to sweat and leave to drain for about 10 minutes while you slice the remaining vegetables and prepare the baking dish. (Note 2)","images":[],"step":3},{"title":"Prepare baking dish","description":"Spread 1 tbsp olive oil, tomato paste and half the garlic over the base of a ceramic baking dish (30cm x 20cm x 5cm / 12\" x 8\" x 2\"). As the vegetables bake, they will release their juices which will mix into it to create a beautiful sauce underneath.","images":[],"step":4},{"title":"Season again","description":"Give the colander a shake to remove excess water off the eggplant and zucchini (no need to pat them dry), then put them back into a bowl. A lot of salt comes off with the water, so toss with another 1/2 teaspoon of salt.","images":[],"step":5},{"title":"Layer vegetables","description":"Arrange the vegetables vertically in the dish, alternating eggplant, zucchini, onion and tomato (I do it in this order). I usually make around 14 rows (the video is very useful here). Don''t be afraid to pack the vegetables in quite tightly. They will shrink as they bake, so arranging them snugly together helps them stay upright. (Note 3)","images":[],"step":6},{"title":"Season top","description":"Drizzle all-over with remaining olive oil. Sprinkle evenly with remaining garlic, remaining 1/2 teaspoon of salt, black pepper and Herbes de Provence.","images":[],"step":7},{"title":"Bake","description":"Bake for 40 minutes until the vegetables are soft and lightly browned on the edges. Serve immediately, or leave to cool and serve at room temperature.","duration":40,"images":[],"step":8}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["all-vegetable-sides","dietary","easter-sides-warm-hearty","eggplant","gluten-free-recipes","jbs-recipes","side-dishes","tomato","vegan-lifestyle","vegetarian-recipes","zucchini","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ac448cf78003', 'en', 'US', 'Maple sweet potato salad - with whipped tahini and crispy chickpeas', 'Recipe video above. Channelling my inner Yotam Ottolenghi – maple-roasted sweet potato on a fluffy cloud of whipped tahini, topped with crispy spiced chickpeas and a shower of chopped pistachios. Fabulous statement side or substantial meat-free main - try stuffing into flatbreads. Ridiculously good!', 'https://www.recipetineats.com/tachyon/2025/06/Maple-sweet-potato-salad-with-whipped-tahini_4.jpg', 15, 40, 55, 5, '[{"id": "ing_sweet_potato", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.24, "unit": "bottle of 250ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.004, "unit": "tub of 500g"}}, {"id": "ing_tahini", "quantity": {"value": 0.18, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_pistachios", "quantity": {"value": 4.0, "unit": "unit"}}]', '[{"ingredients":["1.5kg / 3 lb sweet potatoes","1 tbsp maple syrup (or 2 1/2 tbsp honey)","1 1/2 tbsp olive oil","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Maple roasted sweet potato wedges:"},{"ingredients":["400g/ 14 oz can chickpeas (, drained but not dried)","1 tbsp olive oil","1/2 tsp smoked paprika","1/4 tsp garlic powder","1/4 tsp onion powder","1/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Crispy seasoned chickpeas:"},{"ingredients":["3 tbsp maple syrup (sub 2 tbsp honey)","1 tbsp sriracha (Note 2)","1 tbsp extra virgin olive oil","1/4 tsp cooking salt / kosher salt (halve for table salt)","Pinch Black pepper"],"purpose":"Spicy maple sauce"},{"ingredients":["1 1/4 cups plain yogurt (, full fat, unsweetened)","3 tbsp tahini (mix well if oil is separated)","2 tbsp lemon juice","1 large garlic clove (, finely grated)","1 tbsp extra virgin olive oil","1/2 tsp cooking salt / kosher salt"],"purpose":"Whipped tahini yogurt sauce:"},{"ingredients":["2 tbsp finely chopped coriander/cilantro leaves (sub parsley)","4 tbsp toasted pistachios (, finely chopped (Note 3))"],"purpose":"Garnishes:"}]', '[{"description":"Preheat the oven to 220°C/450°F (200°C fan). Arrange the oven racks so they are 20 cm/8\" apart (for air circulation).","images":[],"step":1},{"title":"Spicy maple sauce","description":"Mix until combined. Set aside.","images":[],"step":2},{"title":"Sweet potato","description":"Cut each sweet potato lengthways into 6 wedges (or 8, if they are thicker potatoes). Put on a paper lined tray, then toss with the maple syrup, olive oil, salt and pepper. Lay sweet potato wedges on their side.","images":[],"step":3},{"title":"Chickpeas","description":"Drain the chickpeas then spread on a tray (still wet).","images":[],"step":4},{"title":"Baking","description":"Put both trays in the oven (sweet potato on the top shelf). Roast the potatoes for 30 minutes, turning them at the halfway mark. Take the chickpeas out after 10 minutes to flavour them.","duration":30,"images":[],"step":5},{"title":"Crispy seasoned chickpeas","description":"Remove the oven dried chickpeas from the oven after 10 minutes (Note 4). Push them to one side of the tray, drizzle/sprinkle and toss with the oil, spices, salt and pepper. Toss well using a rubber spatula, then return to the oven for a further 15 - 20 minutes until they''re crispy (they will clatter! Note 4).","images":[],"step":6},{"title":"Sweet potato charring (optional)","description":"After 30 minutes (or when the potatoes are soft), switch the oven grill/broiler to high. Tuck in or fold down excess paper around the tray edges (so it doesn''t touch heat element and catch fire). Stand the wedges sharp edge facing up, then pop it under the broiler for 3 to 5 minutes until a bit charred on the edges. ⚠️ SAFETY NOTE: Do not walk away, make sure the paper does not catch fire.","duration":4,"images":[],"step":7},{"title":"Whipped tahini yogurt sauce","description":"While the potatoes are roasting whisk ingredients in a heat-proof bowl just to combine. When ready to use, microwave for just 30 seconds on high, then whisk again for 10 seconds – it will resemble softly whipped cream. (Note 5)","duration":0.16666666666666666,"images":[],"step":8},{"title":"Optional tahini drizzle","description":"Remove 1/4 cup of the tahini sauce and loosen with a little water to a drizzle-able consistency.","images":[],"step":9},{"title":"Assemble","description":"Spread the whipped tahini on a large plate. Pile the sweet potato on, mostly in a single layer. Drizzle with the tahini drizzle (if using), the spicy maple sauce, sprinkle with most of the pistachio and coriander. Sprinkle over chickpeas, then sprinkle with the remaining coriander and pistachios. EAT! (PS Great served warm or at room temperature)","images":[],"step":10}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["MIddle eastern vibes","Western"],"categories":["all-vegetable-sides","dietary","gluten-free-recipes","sweet-potato","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_33d5fbd91088', 'en', 'US', 'The most amazing Chicken Kale Salad', 'Recipe video above. WORTH MAKING - don''t let the length of the ingredients deter you!! This is a big, hearty salad that may well be the best kale salad you''ve ever had. Big call I stand by! :)Filled with good-for-you nutrition yet anything but bland, that creamy tahini sauce totally makes it, thanks to the parmesan. Crunchy seasoned chickpeas add starchy bulk, flavour pops and texture, the cherry tomatoes add juicy bursts and the chicken provides protein. Oh yeah, and there''s kale in it too! :) Powerhouse greens!', 'https://www.recipetineats.com/tachyon/2024/04/Kale-salad-with-creamy-tahini-dressing_9.jpg', 20, 30, 50, 3, '[{"id": "ing_very_tightly_packed_cups_tuscan_kale", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_tahini", "quantity": {"value": 0.24, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 0.06, "unit": "L"}}]', '[{"ingredients":["5 very tightly packed cups Tuscan kale (cavolo nero) (, leafy part stripped off stem, sliced into 1 cm / 1/2\" ribbons (Note 1))","1 tsp extra virgin olive oil","1/4 tsp salt and pepper"],"purpose":"SOFTENED KALE:"},{"ingredients":["1/4 red onion (, very finely sliced)","1 1/2 cups shredded cooked chicken","2 soft boiled eggs (, halved (optional))"],"purpose":"SALAD:"},{"ingredients":["1 1/2 cups cherry or grape tomatoes","2 tsp extra virgin olive oil","1/4 tsp cooking salt/kosher salt","1/8 tsp black pepper"],"purpose":"BURST TOMATOES"},{"ingredients":["400 g/ 14 oz can chickpeas (, drained but not dried)","1 tbsp olive oil","1/2 tsp smoked paprika","1/4 tsp EACH garlic powder , onion powder","1/4 tsp EACH cooking salt / kosher salt & black pepper"],"purpose":"CRISPY SEASONED CHICKPEAS"},{"ingredients":["4 tbsp (60 g) tahini (, hulled (Note 3))","2 1/2 tbsp lemon juice","3 tbsp extra virgin olive oil","1/3 cup parmesan (finely grated (pack the cup tight), plus extra for serving)","1/2 tsp cooking salt/kosher salt","1/8 tsp black pepper","1 large garlic clove (, peeled)","4 tbsp water (plus more, if needed)"],"purpose":"CREAMY PARMESAN TAHINI DRESSING"}]', '[{"title":"Oven","description":"Roast tomatoes 12 min at 200°C/425°F (180°C fan). Roast plain chickpeas 10 min, toss with oil & seasonings, roast 20 min until crispy (same temp).","images":[],"step":1},{"title":"Salad","description":"Massage kale, leave 20 min. Blitz dressing. Toss kale, chicken, tomatoes, onion with half. Pile on chickpeas, drizzle with remaining dressing, shower with parmesan. EAT!","images":[],"step":2},{"description":"Preheat the oven to 200°C/425°F (180°C fan).","images":[],"step":3},{"title":"Roast tomatoes","description":"Toss the tomatoes with the oil, salt and pepper on a small tray. Roast 12 minutes, then cool on the tray.","images":[],"step":4},{"title":"Crispy chickpeas","description":"Drain the chickpeas then spread on a tray (still wet). Bake 10 minutes (same time as tomatoes). Push the oven dried chickpeas to one side of the tray. Drizzle with the oil and sprinkle with the chickpea spices, salt and pepper. Toss well using a rubber spatula, then return to the oven for a further 20 – 25 minutes until they''re crispy (They should clatter! Note 4).","images":[],"step":5},{"title":"Soften kale","description":"Rub/scrunch the kale with the oil, salt and pepper in a large bowl. Put the kale in a large bowl then drizzle with the oil and add the salt and pepper. Set aside for 20 minutes (softens leaves).","duration":20,"images":[],"step":6},{"title":"Tahini dressing","description":"Put the ingredients in a jug just large enough to fit the head of a stick blender. Blitz until smooth, using extra water if needed to loosen into a thick but pourable consistency (see video).","images":[],"step":7},{"title":"Toss","description":"Pour half the dressing over the kale and toss. Add onion, chicken and most of the tomatoes (save a few for decoration). Toss again.","images":[],"step":8},{"title":"Serve","description":"Transfer into a serving bowl or individual bowls. Top with remaining tomatoes, all the chickpeas and eggs if using. Drizzle with remaining sauce then sprinkle with extra parmesan. DIG IN. SWOON!","images":[],"step":9}]', '["egg","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["all-vegetable-sides","beans-lentils","leafy-greens","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e8fdbc3d0e04', 'en', 'US', 'Spicy maple roast carrots with crispy chickpeas and yogurt sauce', 'Recipe video above. This is a combination of 3 simple things that are devilishly good together: slightly spicy caramelised maple roasted carrots, crispy seasoned chickpeas and a cooling, creamy yogurt sauce with a subtle hint of garlic. The chickpeas add terrific crunch and because they''re a starch, you can easily serve this substantial side dish as a meal. Both the carrots and chickpeas take around 30 minutes in the oven but you might need to add an extra 5 minutes or so depending on how long you take when you take the trays out to toss/season etc .', 'https://www.recipetineats.com/tachyon/2024/02/Spicy-maple-roasted-carrots-with-crispy-chickpeas-and-yogurt-sauce-1.jpg', 15, 40, 55, 5, '[{"id": "ing_carrot", "quantity": {"value": 16.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.2, "unit": "pack of 1kg"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.24, "unit": "bottle of 250ml"}}, {"id": "ing_sriracha", "quantity": {"value": 0.075, "unit": "bottle of 400ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.4, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_pistachios", "quantity": {"value": 3.0, "unit": "unit"}}]', '[{"ingredients":["16 Dutch carrots (, scrubbed clean and tops trimmed (keep 2cm/1\" of tops for looks))","600 g/ 1.2 lb regular carrots (5 medium), peeled, cut into quarters (Note 1)"],"purpose":"Carrots (choose one):"},{"ingredients":["3 tbsp maple syrup (or 2 1/2 tbsp honey)","2 tbsp sriracha","1 1/2 tbsp olive oil","1/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Spicy maple sauce (for carrots):"},{"ingredients":["400g/ 14 oz can chickpeas (, drained but not dried)","1 tbsp olive oil","1/2 tsp smoked paprika","1/4 tsp garlic powder","1/4 tsp onion powder","1/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Crispy seasoned chickpeas:"},{"ingredients":["1 tbsp maple syrup","1/2 tbsp sriracha"],"purpose":"Extra sauce (optional) – Note 2"},{"ingredients":["1 cup plain yogurt","1/2 tsp garlic (, finely grated)","1 tbsp lemon juice","1 tbsp extra virgin olive oil","1/4 tsp cooking salt / kosher salt"],"purpose":"Lemon garlic yogurt sauce:"},{"ingredients":["2 tbsp finely chopped coriander/cilantro leaves (sub parsley)","3 tbsp toasted pistachios (, finely chopped (Note 3))"],"purpose":"Garnishes:"}]', '[{"description":"Preheat the oven to 200°C/425°F (180°C fan). Arrange the oven racks so they are 20 cm/8\" apart (for air circulation).","images":[],"step":1},{"title":"Chickpeas & carrots","description":"Drain the chickpeas then spread on a tray (still wet). Toss the carrots with the Spicy Maple Sauce ingredients. Put both trays in the oven (carrots on the top shelf).","images":[],"step":2},{"title":"Crispy chickpeas","description":"Remove the oven dried chickpeas from the oven after 10 minutes (Note 4). Push them to one side of the tray, drizzle with the oil and sprinkle with the chickpea spices, salt and pepper. Toss well using a rubber spatula, then return to the oven for a further 20 - 25 minutes until they''re crispy (listen for the clatter when you shake the tray - or eat one! Note 4).","images":[],"step":3},{"title":"Carrots 30 min","description":"Roast the carrots for 30 minutes, tossing halfway, until they are tender and caramelised on the edges.","duration":30,"images":[],"step":4},{"title":"Yogurt Sauce","description":"Mix the ingredients in a bowl and set aside for at least 20 minutes to allow the flavours to develop.","images":[],"step":5},{"title":"Extra sauce","description":"Mix until combined.","images":[],"step":6},{"title":"Assemble","description":"Spread the yogurt sauce on a plate. Pile on the carrots, scraping out every drop of juices on the tray. Drizzle with extra sauce, if using. Sprinkle over chickpeas, then coriander and pistachios. EAT!","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["MIddle eastern vibes","Western"],"categories":["all-vegetable-sides","beans-lentils","carrots","easter-sides-warm-hearty","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0401325e5931', 'en', 'US', 'Glass noodle salad (cellophane / bean thread noodles)', 'Recipe video above. This Asian-style salad combines glass noodles with fresh herbs, vegetables and shredded chicken with a hoisin dressing that''s slightly creamy so it clings nicely to the slippery noodles. The lime cashew crumble really makes this, so don''t skip it!Terrific no-cook meal for hot summer nights. Skip the chicken to turn it into a fabulous starch + veg side for Asian meals. Serves 3 to 4 as a meal, 5 to 6 as a side. More meal-size salads here!', 'https://www.recipetineats.com/tachyon/2023/01/Glass-noodle-salad_2.jpg', 20, 0, 20, 3, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.2, "unit": "pack of 500g"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_mint", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_roasted_cashew_nuts", "quantity": {"value": 0.5, "unit": "jar"}}, {"id": "ing_ime_zest", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.005, "unit": "jar of 400g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 0.003, "unit": "jar"}}]', '[{"ingredients":["100 g / 3.5 oz bean thread vermicelli noodles / cellophane noodles (Note 1)","3 cups shredded cooked chicken (about 1/2 store bought roast chicken) (Note 2)","2 packed cups ((180g) green cabbage, finely sliced)","1 cucumber (, cut in half, sliced 3mm / 1/8\" thick on the diagonal)","1 carrot (, peeled then julienned)","2 green onion stems (, finely sliced on a diagonal)","1 cup lightly packed coriander/cilantro leaves","1 cup lightly packed mint leaves"],"purpose":"Glass noodle salad:"},{"ingredients":["1 cup unsalted roasted cashew nuts (, roughly chopped)","1 1/2 tsp lime zest","2 tsp lime juice","3/4 tsp caster sugar / superfine sugar (sub ordinary / granulated)","1/2 tsp cooking/kosher salt"],"purpose":"Lime cashew crumble:"},{"ingredients":["3 tbsp light soy sauce","3 tbsp rice vinegar","1 1/2 tbsp sesame oil","1 1/2 tbsp canola oil","1 1/2 tbsp kewpie mayonnaise (or other mayo) (Note 3)","1 tbsp hoisin sauce","3/4 tsp finely grated fresh ginger","1/4 tsp Chinese five spice powder (Note 4)"],"purpose":"Creamy hoisin dressing:"}]', '[{"title":"Glass noodles","description":"Place dry noodles in a bowl and cover with freshly boiled water. Leave for 3 to 4 minutes or until transparent and softened. Drain using a colander, rinse under tap water (for rapid cool and reduce stickiness) then detangle using your fingers. Drain thoroughly before use. Set aside to fully cool.","duration":3.5,"images":[],"step":1},{"title":"Lime cashew crumble","description":"Place ingredients in a bowl and toss. (No marinating time needed)","images":[],"step":2},{"title":"Dressing","description":"Place ingredients in a jar and shake until well combined.","images":[],"step":3},{"title":"Salad","description":"Place glass noodle salad ingredients in a large bowl. Pour over dressing, toss well. Add half the cashews, toss again.","images":[],"step":4},{"title":"Serve","description":"Transfer to a large salad bowl or individual bowls. Sprinkle with remaining lime cashew crumble and serve!","images":[],"step":5}]', '["gluten","nuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner","lunch"],"cuisine":["Asian"],"categories":["all-vegetable-sides","no-cook-food","noodles","salad-recipes-main-course","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ecc2ab94db14', 'en', 'US', 'Twice Baked Potatoes (Stuffed Jacket Potatoes)', 'Recipe video above. Baked potatoes stuffed with a creamy, cheesy, mashed potato filling hit with salty pops of bacon. Think of it as the spud love-child of jacket potatoes and mashed potato! This is pretty much every cheese lovin,’ carb monster''s dream come true. Dainty food this ain''t – this is proper comfort food, turned up to 11!Serve it as a side, or as a meal.', 'https://www.recipetineats.com/tachyon/2021/05/Twice-Baked-Potatoes_5.jpg', 15, 75, 90, 8, '[{"id": "ing_potato", "quantity": {"value": 4.0, "unit": "bag of 2kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chives", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["4 x 300g / 10oz potatoes ( - Sebago (Aus), Russet (US), Maris Piper / King Edwards (UK) (Note 1))","1 tbsp canola or vegetable oil","1/2 tsp salt"]},{"ingredients":["200g / 7oz bacon (streaky) (, chopped into small batons (Note 2))","120g / 8 tbsp unsalted butter","1/3 cup cream (pure or thickened / heavy)","1 cup cheddar cheese (, shredded (Note 3))","3 green onions (, finely sliced)","1/4 tsp salt","1/4 tsp pepper"],"purpose":"Creamy potato filling:"},{"ingredients":["1 1/2 tbsp chives (, finely chopped (garnish))","Sour cream (recommended!)"],"purpose":"Garnish and serving (optional)"}]', '[{"description":"Preheat oven to 220°C / 430°F (200°C fan). Place a rack on a tray (recommended but not critical).","images":[],"step":1},{"title":"Prick potatoes","description":"Wash, scrub and dry potatoes well. Prick each potato 8 times with a fork.","images":[],"step":2},{"title":"Oil and salt","description":"Put potatoes in a bowl, pour over oil and rub onto potatoes. Then sprinkle over salt and use your hands to coat. (Just do this as best you can. Some will stick, much will not!)","images":[],"step":3},{"title":"Bake","description":"Place potatoes on rack and bake for 75 minutes or until you can pierce with a small knife with no resistance.","duration":75,"images":[],"step":4},{"description":"Prepare filling add-ins:","images":[],"step":5},{"title":"Cook bacon","description":"Place bacon in a cold non-stick pan over medium heat. When the fat starts to melt, turn the heat up to high and cook bacon until golden. Drain on paper towels.","images":[],"step":6},{"title":"Heat butter and cream","description":"Melt butter in a saucepan over medium heat. Then add cream and heat until hot, but don''t let it boil. (You could also do this in a microwave)","images":[],"step":7},{"description":"Stuff potatoes:","images":[],"step":8},{"title":"Lower oven","description":"Turn oven down to 200°C / 390°F (180°C fan).","images":[],"step":9},{"title":"Scoop out potato flesh","description":"Allow potatoes to cool enough so you can handle them (or use a tea towel). Cut in half lengthwise and scoop out potato flesh, leaving 0.7cm (1/3\") thick layer of potato still stuck to skin.","images":[],"step":10},{"title":"Mash potato","description":"Place potato flesh in a bowl and mash while hot until smooth.","images":[],"step":11},{"title":"Add-ins","description":"Add half the cheese (save the rest for topping), most of the bacon (save a bit for garnish), all the green onion, hot cream and butter, salt and pepper. Stir to combine.","images":[],"step":12},{"title":"Stuff and top with cheese","description":"Fill potato skins with the mashed potato mixture. Top with remaining cheese.","images":[],"step":13},{"title":"Bake","description":"Bake for 20 to 25 minutes until the cheese is melted, golden and bubbly.","duration":22.5,"images":[],"step":14},{"title":"Serve","description":"Serve immediately, garnish with sour cream, reserved bacon and chives.","images":[],"step":15}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["American","Western"],"categories":["all-vegetable-sides","dietary","easter-sides-warm-hearty","gluten-free-recipes","potato-recipes","potatoes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_330f864f40e2', 'en', 'US', 'Ratatouille (French Vegetable Stew)', 'Recipe video above. Ratatouille is a French vegetable stew that at first glance seems like a humble dish – because it is. Made well though, it''s a summery stunner bursting with the sunny tastes of the Mediterranean! The key to flavour-packed ratatouille is to sauté each vegetable separately before braising everything together. Ratatouille can comfortably star as a vegetarian main, otherwise it makes a perfect vegetable side.Makes side for 6 to 8 people, main meal for 4 people.', 'https://www.recipetineats.com/tachyon/2021/04/Ratatouille_0.jpg', 15, 45, 60, 8, '[{"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_black_olives", "quantity": {"value": 20.0, "unit": "bottle"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 eggplant (aubergine) (, cut into 2cm / ¾\" cubes (leave skin on) (~450g / 16oz))","1/2 tsp salt (, cooking / kosher salt)"],"purpose":"Eggplant:"},{"ingredients":["3 tomatoes (, chopped (~150g / 5oz each), Note 1 canned subs)","6 tbsp extra virgin olive oil","2 brown onion (, chopped 1cm / ⅖\" cubes (~150g / 5oz each))","2 capsicum (1 red, 1 yellow), ( cut into 2cm / ⅘\" cubes (~200g / 7oz each))","2 zucchinis (courgettes), ( diced into 1.5cm / ½\" pieces (~200g / 7oz each))","2 garlic cloves (, finely chopped (~3 tsp))","1 tsp fresh thyme leaves (, chopped (Note 2 for subs))","3/4 tsp salt (, cooking/kosher salt)","1/4 tsp black pepper","20 black olives (, pitted, halved)"],"purpose":"Other ingredients for Ratatouille:"},{"ingredients":["1 tbsp fresh basil (, finely chopped, plus more for garnish (Note 2 subs))","Extra virgin olive oil (, for drizzling)"],"purpose":"Finishing:"}]', '[{"title":"Sweat eggplant","description":"Place eggplant in a colander set over a bowl. Sprinkle with salt, toss with hands. Leave for 30 minutes to sweat (no need to wipe off water that beads on surface).","duration":30,"images":[],"step":1},{"title":"Make tomato puree","description":"Place tomato in a blender, food processor or other appliance of choice. Blitz until smooth. (No need to do this if using passata or crushed tomato.)","images":[],"step":2},{"description":"Cook vegetables:","images":[],"step":3},{"title":"Cook eggplant","description":"Heat 2 tbsp oil in a large skillet over medium high heat. Add eggplant and cook for 4 to 5 minutes, stirring regularly, until it''s golden on the surface but still somewhat firm and raw inside. Transfer to a large pot.","duration":4.5,"images":[],"step":4},{"title":"Cook onion and garlic","description":"In the same skillet, add another 1 tbsp olive oil. Add onion and garlic with a pinch of the salt. Cook for 3 minutes until onion is soft with a hint of golden on the edges. Add to pot holding eggplant.","duration":3,"images":[],"step":5},{"title":"Cook capsicum","description":"Add another 1 tbsp of olive oil and cook the capsicum with a pinch of salt for 3 minutes. It should still be firm inside. You won''t get much colour on the capsicum, this is OK. Add to pot.","duration":3,"images":[],"step":6},{"title":"Cook zucchini","description":"Add another 1 tbsp olive oil and cook the zucchini with a pinch of salt for 3 minutes. Make sure it stays firm (ie. raw inside). Like the capsicum, it won''t go golden. Add to pot.","duration":3,"images":[],"step":7},{"title":"Add remaining ingredients to pot","description":"Turn the stove under the pot to medium-high. Add tomato, thyme, olives, remaining salt and all the pepper, and mix. Once the mixture is hot, reduce heat to a low simmer.","images":[],"step":8},{"title":"Braise: Cook for 20","description":"25 minutes with the pot lid off, stirring every now and then, until all the vegetables are cooked through and the liquid has reduced. The mixture should be thick enough so you can pile it on a plate (ie. not watery), but still very moist and juicy.","duration":22.5,"images":[],"step":9},{"title":"Basil and salt","description":"Taste and add more salt if needed; vegetables can taste bland if not enough salt is added. Stir through basil then serve immediately, drizzled with extra virgin olive oil and a sprinkle of extra basil on top, if desired. Serve as a main with crusty bread, or as a side dish. See above recipe card for more ideas!","images":[],"step":10}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["French","Western"],"categories":["all-vegetable-sides","dietary","easter-sides-warm-hearty","gluten-free-recipes","low-calorie-recipes","side-dishes","stews","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_247f08932ef8', 'en', 'US', 'Eggplant Curry - South Indian Brinjal Curry', 'Recipe video above. This curry is not for the faint hearted! Eggplant (Brinjal) stars in this strong flavoured curry, roasted rather than fried for a healthier yet equally delicious (high temp does the trick here), then simmered in an intensely spiced South Indian curry sauce so it sucks up the flavour and partially collapses to create a big pot of juicy (delicious) mush. Incidentally vegan (as much of South Indian food is). See recipe notes for subs for the harder to find spices. And when you''ve made this, use the same spices to make this Vegetable Samosa Pie!Spiciness: Pretty mild. Spiciness only comes from the chilli powder so if you''re concerned, skip or reduce it!', 'https://www.recipetineats.com/tachyon/2020/08/Eggplant-Curry-Indian__2.jpg', 15, 60, 75, 4, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 58.333, "unit": "carton of 12"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_mustard", "quantity": {"value": 0.015, "unit": "jar of 200g"}}, {"id": "ing_curry_leaves", "quantity": {"value": 0.07, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.03, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.113, "unit": "can of 400ml"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_round_clove", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.05, "unit": "jar of 40g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["2 tbsp vegetable oil (or canola)","700g / 1.2 lb eggplant (aubergine) (, 2 medium (Note 1))","1/2 tsp each salt and pepper"],"purpose":"Roasted Eggplant:"},{"ingredients":["3 tbsp vegetable oil (or canola)","3/4 tsp black mustard seeds (Note 2)","14 curry leaves, fresh (Note 3)","1 red onion (, quartered and thinly sliced)","3 tbsp passata or tomato pulp (or canned tomato) (Note 4)","1 tbsp garlic (, grated (4 cloves approx))","1 tbsp ginger (, grated (1.5cm piece approx))","1 1/4 cups water","3/4 tsp salt","3 tbsp coconut milk (or cream, full fat (Note 5))"],"purpose":"Curry:"},{"ingredients":["1/4 tsp cardamom powder","1/4 tsp ground clove","1/4 tsp black pepper","1/2 tsp chilli powder (or cayenne (NOT US Chilli Powder))","4 tsp coriander powder","4 tsp cumin powder"],"purpose":"Curry Spices:"},{"ingredients":["Basmati rice","Yogurt (, highly recommended)","Coriander/cilantro leaves (, optional)","Easy flatbread (as naan!) (, optional)"],"purpose":"Serving"}]', '[{"description":"Roasted Eggplant:","images":[],"step":1},{"description":"Preheat oven to 240°C / 450°F (220°C fan). Line tray with parchment/baking paper.","images":[],"step":2},{"description":"Cut eggplant into 2cm / 4/5\" slices, then cut into 2cm / 4/5\" batons.","images":[],"step":3},{"description":"Place in large bowl, toss with oil, salt and pepper.","images":[],"step":4},{"description":"Spread on tray, roast 20 minutes. Turn, roast for a further 10 minutes - edges should be caramelised, soft inside, but they''re not shrivelled up and dismal. Use per recipe.","images":[],"step":5},{"description":"Heat oil in a large pot over medium heat. Add mustard seeds, let them sizzle for 15 seconds.","duration":0.25,"images":[],"step":6},{"description":"Add curry leaves, stir, leave to sizzle for 15 seconds - seeds might pop, Indian cooking is very dramatic!","duration":0.25,"images":[],"step":7},{"description":"Add onions, cook 5 minutes until golden brown.","images":[],"step":8},{"description":"Add tomato, cook for 1 minute, stirring.","duration":1,"images":[],"step":9},{"description":"Add garlic and ginger, cook 2 minutes.","images":[],"step":10},{"description":"Add Curry Spices and salt, and cook for another 3 minutes - it will be a thick paste and might stick to the bottom of the pot, don''t let it burn (if it starts to, remove from stove and quickly add splash of water to loosen).","images":[],"step":11},{"description":"Stir in water, and then add the eggplant.","images":[],"step":12},{"description":"Gently stir, partially cover, reduce heat to low and simmer 30 minutes. Stir carefully once or twice (so the eggplants don''t break up completely), add more water if it dries out.","images":[],"step":13},{"description":"Stir in coconut milk, taste then add more salt if needed.","images":[],"step":14},{"description":"Your result should be a very thick, juicy, strongly flavoured curry with eggplant partially intact but half collapsed.","images":[],"step":15},{"description":"Serve with basmati rice and a dollop of yogurt and fresh coriander leaves, if you want.","images":[],"step":16}]', '["milk","mustard"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["all-vegetable-sides","curry-recipes","dietary","eggplant","gluten-free-recipes","indian-recipes","low-calorie-recipes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1f4ba82bdc05', 'en', 'US', 'Roasted Broccolini with Tahini Sauce', 'Recipe video above. I think that roasting is the best way to cook broccolini. It brings out the flavour and you get crunchy golden tips - the best part! It makes a wonderful side dish eaten plain, but if you drizzle it with a simple Tahini Sauce and sprinkle with nuts, it becomes company-worthy as an impressive side dish OR a main served with crusty bread or stuffed into flatbreads.Especially brilliant served with all things Middle Eastern.', 'https://www.recipetineats.com/tachyon/2020/08/Roasted-Broccolini-with-Tahini-Sauce_5.jpg', 10, 15, 25, 4, '[{"id": "ing_broccoli", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_tahini", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.015, "unit": "jar of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.001, "unit": "pack of 3 heads"}}, {"id": "ing_pine_nuts", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["500g/1 lb broccolini (, ends trimmed (3 standard bunches in Australia))","1 tbsp extra virgin olive oil","1/4 tsp each salt and pepper","1 garlic clove (, finely minced)"]},{"ingredients":["1/4 cup tahini","2.5 tbsp water","1.5 tsp honey","1 tbsp lemon juice","1/2 garlic clove (, pressed through garlic crusher or grated using microplan (to make sauce smooth))","1/4 tsp each salt and pepper"],"purpose":"Tahini Sauce:"},{"ingredients":["1/4 cup flaked almonds, pine nuts or pistachios (, toasted (Note 2))"],"purpose":"Garnish:"}]', '[{"description":"Preheat oven to 220°C/425°F (200°C fan).","images":[],"step":1},{"title":"Sauce","description":"Mix Tahini Sauce ingredients until combined. It should be loose enough so it can be drizzled, but not too runny. Set aside 15 minutes.","images":[],"step":2},{"title":"Toss broccolini","description":"Pile broccolini on tray, drizzle with oil, sprinkle with salt, pepper and garlic.","images":[],"step":3},{"title":"Roast for 12","description":"15 minutes until the broccolini floret ends are dark brown and crunchy (the best part!), and the broccolini stem is just tender. (But if you want it really soft, lower temp to 180C/350F and cook 20 min).","duration":13.5,"images":[],"step":4},{"title":"Plate up","description":"Transfer to serving plate, allow to cool until warm. Drizzle over tahini sauce, sprinkle with almonds or pine nuts and serve! Excellent served warm OR at room temp.","images":[],"step":5},{"description":"The Tahini Sauce goes brilliantly with other roasted vegetables too, including: carrots, cauliflower, broccoli, green beans and asparagus.","images":[],"step":6}]', '[]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["all-vegetable-sides","broccoli","quick-and-easy","side-salads","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_606208bf5626', 'en', 'US', 'Roasted Eggplant Lentil Salad (Aubergine Salad)', 'Recipe video above. Lentils and roasted eggplant (aubergine) is such a great combination - especially when you infuse the lentils with flavour by cooking them in a seasoned broth, and you try my method of roasting eggplant so they stay plump and juicy inside with great caramelisation on the outside! (For more roasted eggplant uses, visit this roasted eggplant recipe).Great to serve at a brunch as a main - it holds up well for hours. Serve warm, or at room temp. Serves 3 to 4 as main, 8 - 10 as a side.', 'https://www.recipetineats.com/tachyon/2020/07/Roasted-Eggplant-Lentil-Salad_4.jpg', 15, 1470, 1485, 4, '[{"id": "ing_lentils", "quantity": {"value": 0.5, "unit": "can of 400g"}}, {"id": "ing_chicken", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_egg", "quantity": {"value": 58.333, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 250.0, "unit": "punnet of 250g"}}, {"id": "ing_lettuce", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_feta_cheese", "quantity": {"value": 60.0, "unit": "block of 200g"}}]', '[{"ingredients":["1 cup dried green or brown lentils (or French/puy) (Note 1 for canned)","1 cup vegetable or chicken broth (or water + 1 bouillon cube, crumbled)","1 1/2 cups water","1 large garlic clove (, smashed, skin removed (Note 2))","Lemon peel (about 1.5 x 5 cm / 3/4 x 2\")","1 bay leaf (, dry or fresh)","2 sprigs thyme (, or 1/2 tsp dried thyme)","1 rib celery (, broken into 3 or 4 pieces (or just a handful of celery leaves, can skip))"],"purpose":"TASTY LENTILS!"},{"ingredients":["700g / 1.4 lb eggplant / aubergine (2 medium)","2 1/2 tbsp olive oil","1/4 tsp EACH salt and pepper"],"purpose":"Roasted Eggplant:"},{"ingredients":["2 tbsp lemon juice (or cider vinegar, white or red wine vinegar)","4 tbsp extra virgin olive oil","1 tsp Dijon mustard","1 garlic clove (, minced using garlic press)","1 tsp thyme leaves (, fresh (or 1/2 ts dried - can omit, or other herbs, Note 3))","1 tsp sugar (, optional)","1/2 tsp EACH salt + black pepper"],"purpose":"Garlic Lemon Dressing:"},{"ingredients":["250g/ 8 oz cherry tomatoes (, halved (large quartered))","2 handfuls rocket / arugula lettuce (, torn into 5cm/2\" pieces)","60g/ 2 oz feta (, crumbled (or more!))"],"purpose":"Salad:"}]', '[{"title":"Dressing","description":"shake in a jar.","images":[],"step":1},{"description":"Place Lentil ingredients in a saucepan, bring to simmer over medium heat. Place lid on then lower heat to medium low so it''s simmering gently.","images":[],"step":2},{"description":"Cook for 20 minutes (for al dente, my preference), or 25 minutes (for soft), stirring occasionally.","duration":20,"images":[],"step":3},{"description":"Drain, then pick out all the flavouring bits (garlic etc). BRIEFLY rinse to get grit off - don''t wash off all the flavour! Shake off excess water well.","images":[],"step":4},{"description":"Preheat oven to 240°C / 450°F (220°C fan). Line a tray with parchment/baking paper.","images":[],"step":5},{"title":"Cut eggplant into large cubes","description":"3 cm / 1.2\". Place in large bowl, drizzle with oil, salt and pepper.","images":[],"step":6},{"description":"Toss well, then immediately spread on tray and roast 20 minutes. Flip, then roast for a further 10 minutes - edges should be caramelised, soft inside, but they''re not shrivelled up and dismal.","images":[],"step":7},{"description":"Add tomato and rocket into lentils, drizzle over most of the Dressing then toss.","images":[],"step":8},{"description":"Pour onto serving platter. Pile over eggplant.","images":[],"step":9},{"description":"Drizzle eggplant with remaining Dressing, sprinkle with feta . Serve warm or at room temp! Great with a side of flatbread or this easy crusty bread.","images":[],"step":10}]', '["mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner","lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","beans-lentils","eggplant","lentil-recipes","salad-recipes-main-course","side-salads","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c738d2314315', 'en', 'US', 'Garlic Butter Roasted Mushrooms', 'Recipe video above. Here''s a simple, incredibly delicious way to roast mushrooms: tossed in garlic butter then roasted on a high temp to make them golden brown on the outside whilst keeping them juicy on the inside. The addition of olive oil stops the butter from burning and also adds a touch of extra flavour - but the dominant flavour is still butter (and garlic!). The lemon and thyme finishing touch is optional - it''s terrific plain - it''s an extra flavour option.Serves 2 as a main, 4 - 5 as a side.', 'https://www.recipetineats.com/tachyon/2018/10/Roasted-Mushrooms-Garlic-Butter_0.jpg', 5, 20, 25, 4, '[{"id": "ing_mushroom", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["500g / 1lb mushrooms (, button or Swiss brown / cremini OR 8 large (like portabello))","50g / 3 tbsp unsalted butter (, melted)","1 tbsp olive oil","2 garlic cloves (, finely minced)","1/2 tsp each salt and pepper"]},{"ingredients":["1 1/2 tbsp lemon juice","1 tsp fresh thyme leaves (parsley also good for colour)"],"purpose":"Optional finishing flavour:"}]', '[{"description":"Preheat oven to 220°C/450°F (200°F fan).","images":[],"step":1},{"description":"Toss mushrooms with butter, oil, garlic, salt and pepper in a large bowl using a rubber spatula.","images":[],"step":2},{"title":"Spread on a baking tray and roast for 25 minutes","description":"do not toss or turn.","duration":25,"images":[],"step":3},{"description":"Remove from oven. If using lemon and thyme, push mushrooms together onto one side of the tray, drizzle with lemon, sprinkle with thyme and toss. Serve immediately!","images":[],"step":4},{"description":"How to roast LARGE MUSHROOMS (eg portabello)","images":[],"step":5},{"description":"(Video here for large mushrooms) Place mushrooms cap side down (ie stems facing up) in a medium baking dish (so they are kind of snug - they shrink).","images":[],"step":6},{"description":"Spoon 1 tsp of butter over each mushroom, then use the rest to brush the edges (or carefully drizzle over edges).","images":[],"step":7},{"description":"Drizzle over olive oil, sprinkle with salt and pepper.","images":[],"step":8},{"description":"Roast for 20 minutes (tender but still a slight firmness) or 25 minutes (tender) - no turning. There will be juices in the pan and plenty pooled in the mushrooms caps.","duration":20,"images":[],"step":9},{"description":"Squeeze over a bit of lemon juice, sprinkle with thyme. Serve mushrooms, drizzled with pan juices (see notes for serving suggestions).","images":[],"step":10}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["all-vegetable-sides","dietary","dinner-tonight","easter-sides-warm-hearty","gluten-free-recipes","main-dishes","mushroom-recipes","mushrooms","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bf6e7621c638', 'en', 'US', 'Incredible BBQ Grilled Vegetables - marinated!', 'Recipe video above! An assortment of vegetables grilled on the BBQ until tender-crisp with charred edges, then while still hot, tossed in a Lemon Herb & Garlic Marinade so they suck up the flavour. Great served freshly made, even better the next day! See in post for serving ideas - antipasto / cheeseboard, starter, side dish, main, salad, or pasta. Oven roasted directions also included.', 'https://www.recipetineats.com/tachyon/2019/06/Marinated-Grilled-Vegetables_3.jpg', 20, 20, 40, 8, '[{"id": "ing_capsicum", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_zucchini", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_es_asparagus", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 3.0, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.007, "unit": "pack of 100g"}}]', '[{"ingredients":["2 red capsicum/bell peppers","2 yellow capsicum/bell peppers","2 red onions","1 eggplant (, halved lengthwise, then 1.25cm/ 0.5\" thick semi circles)","2 zucchini (, 0.7cm / 1/3\" thick slices on diagonal)","2 bunches asparagus (, ends trimmed)","200g/ 7oz button mushrooms"],"purpose":"Vegetables (Note 1):"},{"ingredients":["1/4 cup (65ml) extra virgin olive oil","1 tsp each salt and pepper","3 cloves garlic (, minced)","1/4 cup parsley (, roughly chopped (or chives))"],"purpose":"Grilling/Roasting:"},{"ingredients":["1/3 cup (85ml) lemon juice","1/3 cup (85ml) extra virgin olive oil","2 tsp white sugar","2 garlic cloves (, minced)","1/2 tsp each salt and pepper","1/2 tsp each dried basil, parsley, oregano, thyme (Note 2)","1/2 - 1 tsp chilli flakes (adjust spice to taste, Note 3)"],"purpose":"Grilled Vegetable Marinade (Dressing):"}]', '[{"description":"Place ingredients in a jar and shake well. Set aside 10 minutes+.","images":[],"step":1},{"description":"Cutting Vegetables (see video):","images":[],"step":2},{"description":"Keep pieces large for easy handling on the BBQ (so you don''t have to turn hundreds of pieces!) and so they don''t fall through the grills.","images":[],"step":3},{"title":"Capsicum/bell peppers","description":"cut the \"walls\" off, then cut each each on the diagonal into fairly large pieces.","images":[],"step":4},{"title":"Onion (Note 4)","description":"keep the root end (hairy end!) in tact. Peel, cut in half, then cut into wedges through the root end.","images":[],"step":5},{"description":"Grilling/Roasting Vegetables:","images":[],"step":6},{"description":"Brush BBQ grills lightly with oil, then preheat to high. Or oven 250°C/480°F.","images":[],"step":7},{"description":"Place vegetables in a very large bowl or use a big tray. Drizzle with oil, sprinkle with salt, pepper and garlic. Toss with hands (there is no better way!).","images":[],"step":8},{"description":"Place on BBQ and cook until tender crisp with charred edges - cook times below. Then remove into large bowl.","images":[],"step":9},{"description":"Cook times:","images":[],"step":10},{"title":"Asparagus, zucchini","description":"grill 2 min each side. (Oven - 10 min, no flipping)","images":[],"step":11},{"title":"Capsicum, mushroom, onion","description":"grill 3 min each side (oven 15 min, flip at 10 min)","images":[],"step":12},{"title":"Eggplant","description":"grill 4 min each side. Jab in middle to ensure soft but not soggy! (oven 18 min)","images":[],"step":13},{"description":"While vegetables are still hot, drizzle over Dressing and toss.","images":[],"step":14},{"description":"Set aside 10 minutes+ before serving, sprinkled with parsley. See in post for serving ideas.","images":[],"step":15}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["all-vegetable-sides","grilling-ideas-and-recipes","side-dishes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eacdf979ea96', 'en', 'US', 'Caesar Salad - with homemade Caesar Salad Dressing', 'Recipe video above. This homemade Caesar Salad Dressing recipe will rival that of any great restaurant! Anchovy is key to proper flavour in the dressing - every self respecting restaurant uses it, so if you''ve had Caesar Salad out and loved it, you''ve eaten anchovies!Add chicken to make a meal, or serve it straight up the classic way.', 'https://www.recipetineats.com/tachyon/2016/05/Caesar-Salad_7.jpg', 20, 20, 40, 5, '[{"id": "ing_mayonnaise", "quantity": {"value": 0.5, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 0.02, "unit": "bottle"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_milk", "quantity": {"value": 0.052, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 2.5, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_lettuce", "quantity": {"value": 10.0, "unit": "head"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 0.25, "unit": "carton of 12"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 cup mayonnaise (Hellman''s or S&W Whole Egg) (Note 1)","1/2 tsp garlic (, finely minced (use garlic press, if you can))","2 anchovy fillets ( or 3/4 tsp Anchovy paste (Note 2))","2 tbsp fresh lemon juice","1 tsp Dijon mustard","1 tsp Worcestershire sauce","1/2 cup freshly grated parmesan cheese (, or 1/3 cup store bought grated parmesan cheese (Note 3))","3 - 4 tbsp milk (to adjust consistency)","1/4 tsp salt","1/4 tsp Black pepper"],"purpose":"Dressing"},{"ingredients":["2 - 3 slices white bread (, 2/3\" / 1.5cm thick (Note 4))","1 garlic (, cut in half)","1 tbsp olive oil","1/4 tsp salt"],"purpose":"Garlic Croutons"},{"ingredients":["150g / 5oz streaky bacon (, cooked and chopped)","10 cups cos / romaine lettuce (, chopped, wash & dried (1 large, 2 medium, 3 small) (Note 5))","Freshly grated parmesan (, for garnish)"],"purpose":"Salad"},{"ingredients":["2 - 4 eggs (, cooked to your taste, peeled and halved)","500g / 1lb chicken breast fillets (2 pieces)","1/2 tsp EACH salt and pepper","1 tbsp olive oil"],"purpose":"Optional Extras – Chicken & Egg"}]', '[{"description":"Whizz all ingredients in food processor until smooth, starting with 3 tbsp milk.","images":[],"step":1},{"description":"Taste and adjust salt and pepper as desired, and use milk to get the dressing to the desired consistency. (Note 6)","images":[],"step":2},{"description":"Set aside for 20 minutes+ to allow flavours to develop.","duration":20,"images":[],"step":3},{"description":"Place bacon into a cold skillet (no oil), then turn onto medium high. Cook until golden, turn, cook other side until golden. Remove onto paper towels, cool, then chop.","images":[],"step":4},{"description":"Garlic Croutons","images":[],"step":5},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":6},{"description":"Toast bread in the toaster for 1 minute (or oven for 2 minutes each side) until surface is dried but not browned.,","duration":1,"images":[],"step":7},{"description":"Rub both sides of each piece of bread with the cut side of the garlic (Note 7).","images":[],"step":8},{"description":"Remove crust from bread (optional) and cut into cubes - around 1.5 cups. Drizzle with 1 - 2 tbsp olive oil, sprinkle with salt, then bake until golden, shaking the tray once. Sandwich bread will take around 7 minutes, sourdough and similar breads take 12 - 15 min.","images":[],"step":9},{"description":"Place lettuce in bowl with 1/2 the Dressing. Toss well, taste, then decide if you want more Dressing.","images":[],"step":10},{"description":"Transfer to serving bowl. (Top with chicken and egg if using) Scatter over with bacon and croutons. Sprinkle with parmesan and serve!","images":[],"step":11},{"title":"OPTIONAL EXTRAS","description":"Chicken & Egg","images":[],"step":12},{"title":"Eggs","description":"Place the eggs in a saucepan and cover with water. Place over medium high heat and bring to simmer. Once the water is simmering, turn down to medium (gentle simmer) and cook for 3 min (for soft centres), 4 min for firm yolks and 6 min for hard boiled. Remove eggs, run under cold water for 15 sec then leave submerged in a bowl of cold tap water for 5 min. Peel then set aside. (Note 6)","duration":3,"images":[],"step":13},{"title":"Chicken","description":"Either pound the chicken to about 1.2cm/ 1/2\" even thickness, or slice each breast in half horizontally. Sprinkle both sides with salt and pepper. Use bacon fat remaining in skillet. Cook first side for 5 min, turn then cook the other side for 2 min. Remove, cover loosely with foil and rest for 5 min. Cut into slices.","duration":5,"images":[],"step":14}]', '["egg","fish","gluten","milk","mustard"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner","lunch"],"cuisine":["South Western"],"categories":["all-vegetable-sides","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","leafy-greens","main-dishes","no-cook-food","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_19f13d87295c', 'en', 'US', 'Cinnamon Roasted Pumpkin', 'The flavour combination of caramelised roasted pumpkin with cinnamon is stellar and set off perfectly with tangy, creamy yoghurt and bursts of nutty crunch from the pine nuts. Simple to make, satisfying enough to have as a meal or a great side to accompany chicken, beef or lamb.', 'https://www.recipetineats.com/tachyon/2014/07/Cinnamon-Roasted-Pumpkin-2.jpg', 10, 30, 40, 4, '[{"id": "ing_pumpkin", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_cinnamon", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.25, "unit": "net of 500g"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1/4 Jap Pumpkin ((1 kg / 2lb), unpeeled, deseeded, cut into 6 wedges)","3 tbsp olive oil","1 tsp cinnamon","1/4 salt","Black pepper"],"purpose":"Roasted Pumpkin"},{"ingredients":["1/2 cup plain greek yoghurt (, loosened with a bit of water)","1/4 lemon","1 tbsp pine nuts (, toasted)","1 tbsp coriander leaves","1 birds eye chilli (, finely sliced)"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 200C/390F.","images":[],"step":1},{"description":"Combine olive oil, cinnamon, salt and pepper in a shallow dish large enough to fit the pumpkin wedges. Even a plate will work, it just needs to be large enough to lay the pumpkin wedge flat.","images":[],"step":2},{"description":"Place each side of the pumpkin wedge in the olive oil mixture, using your hands if needed to spread the cinnamon over each piece, including on the skin. Place pumpkin on baking tray and drizzle over any remaining olive oil.","images":[],"step":3},{"description":"Bake for 20 to 30 minutes until the pumpkin is golden and cooked through (no need to turn). (See notes on cooking tips)","duration":25,"images":[],"step":4},{"description":"When the pumpkin is cooked, remove from baking tray and place on serving platter. Drizzle over lemon juice. Rest for 5 to 10 minutes before garnishing.","duration":7.5,"images":[],"step":5},{"description":"If you are making it ahead, let it come to room temperature before putting on the other garnishes.","images":[],"step":6},{"description":"To serve, season with extra salt and pepper, drizzle over the yoghurt, scatter over pine nuts, coriander leaves and chilli.","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner","lunch"],"cuisine":["Contemporary Middle Eastern"],"categories":["all-vegetable-sides","cuisines","easter-sides-warm-hearty","middle-eastern-recipes","pumpkin","pumpkin-squash","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4c234ed40853', 'en', 'US', 'Middle Eastern Roasted Eggplant with Couscous', 'Eggplant slathered in a fragrant chermoula paste, then roasted until soft and gooey, and piled high with a fresh couscous. Easy to prepare and absolutely divine. This is satisfying enough to be a meal on its own with just a very simple side salad. The recipe makes about twice the amount of couscous you actually need, but it''s difficult to make in a smaller quantity and also extra couscous on the side makes this a more complete meal. The couscous is versatile and you can easily add your own touch to it. Capers would be lovely, as would crumbled feta, sundried tomatoes, fresh tomatoes and cucumber.', 'https://www.recipetineats.com/tachyon/2014/06/Eggplant-Couscous-2-Version-2-680x1024-1.jpg', 15, 40, 55, 4, '[{"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_paprika", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_couscous", "quantity": {"value": 3.0, "unit": "pack"}}, {"id": "ing_sultanas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_olives", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_almonds", "quantity": {"value": 1.0, "unit": "pack of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["2 medium eggplants"]},{"ingredients":["2 garlic cloves (, crushed)","2 tsp ground cumin","2 tsp ground coriander","1 tsp chilli flakes","1 tsp paprika","Rind of 1 medium lemon","4 tbsp olive oil","1/2 tsp salt"],"purpose":"Chermoula"},{"ingredients":["1/2 tsp salt","3/4 cup couscous","1/4 cup sultanas or currants","3/4 cup boiling water","1/4 cup roughly chopped green olives","1/4 cup flaked almonds (, dry toasted on stove or in oven)","1/4 cup scallions or spring onion (, chopped)","1/4 cup chopped cilantro (coriander) and mint (1/4 cup together)","Black pepper","Juice of 1/2 lemon","2 tbsp extra virgin olive oil"],"purpose":"Couscous"}]', '[{"description":"Preheat the oven to 350F/180C.","images":[],"step":1},{"description":"Slice the eggplant lengthwise, then use small knife to make diagonal criss cross scores deep into the eggplant, making sure you don''t cut the skin. (See notes)","images":[],"step":2},{"description":"Combine the chermoula ingredients and mix into a paste. Slather onto the eggplant.","images":[],"step":3},{"description":"Place on baking tray, flesh side up, and roast for 40 minutes until completely soft. The cooking time will vary depending on the size of the eggplant you are using.","duration":40,"images":[],"step":4},{"description":"Place the couscous, salt and sultanas into a bowl, add the boiling water and cover for 5 minutes.","duration":5,"images":[],"step":5},{"description":"Fluff the couscous with a fork, add the remaining ingredients and toss through to combine. Adjust seasoning to your taste.","images":[],"step":6},{"description":"To serve, pile each eggplant high with couscous, finish with a dollop of yoghurt (see notes for vegan alternative) and garnish with cilantro. Best served warm but also delicious at room temperature.","images":[],"step":7}]', '["gluten"]', '["vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["all-vegetable-sides","cuisines","eggplant","middle-eastern-recipes","quick-and-easy","side-dishes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_32be45094d73', 'en', 'US', 'Popcorn chicken - better than KFC!', 'Recipe video above. This is better than KFC because it''s actually crispy - KFC popcorn chicken is not, it''s soft and greasy! The flavour is remarkably similar with my copycat of the KFC''s 11 secret herbs and spices. It''s ridiculously good - you want to shovel it in your mouth by the handful!Relatively straightforward and on the easy end of frying recipes because it''s just shallow fried and takes just 2 minutes. Serve in cups or mini popcorn boxes with Honey Mustard Dipping Sauce for a fun meal or snack that everyone loves! Air fryer and baking options - not covered in this recipe, please see FAQ above for reason.', 'https://www.recipetineats.com/tachyon/2025/01/Popcorn-chicken_2-close-up.jpg', 25, 10, 35, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 1.0, "unit": "pack of 400g"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.007, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_ginger", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_oil", "quantity": {"value": 3.25, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.003, "unit": "jar of 200g"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["500g / 1lb chicken breast (, skinless boneless, tenderloin or boneless thighs (Note 1))"]},{"ingredients":["3/4 cup buttermilk (Note 2 for yogurt/milk sub)","1 1/2 tsp cooking salt / kosher salt (Note 3)","1 large egg (~50 - 55g, 2 oz in shell)"],"purpose":"Buttermilk marinade:"},{"ingredients":["1 1/2 cups flour (, plain / all purpose)","1/2 cup corn flour / cornstarch (makes it crispy!)"],"purpose":"Popcorn Chicken Breading (Note 4):"},{"ingredients":["1 tsp cooking salt / kosher salt (Note 3)","1/2 tsp celery salt (sub 1/4 tsp extra salt)","1 tsp black pepper","1 tsp regular paprika (aka sweet paprika, not hot or smoked)","1 tsp dried thyme (, crushed with fingers to make it finer)","1 tsp dried oregano (, crushed with fingers to make it finer)","3/4 tsp onion powder","2 tsp garlic powder","1/2 tsp mustard powder","1/2 tsp ginger powder","1/4 tsp cayenne pepper (, optional (tiniest background warmth, doesn''t make it spicy))"],"purpose":"KFC 11 Secret Herbs and Spices (Note 4):"},{"ingredients":["2 1/2 - 3 1/2 cups canola oil (2.5 cm / 1\" depth) (, or vegetable or peanut oil (Note 8 for re-use))"],"purpose":"To fry:"},{"ingredients":["1/2 batch Honey mustard dipping sauce (pictured in post)","Ketchup, tomato sauce,"],"purpose":"Dipping sauce suggestions"}]', '[{"description":"Abbreviated directions:","images":[],"step":1},{"description":"Marinade chicken 1 hour+ in Buttermilk Marinade. Dribble then rub 3 tbsp marinade in breading to make small clumps. Dredge chicken, fry 2 minutes at 180C/350F.","images":[],"step":2},{"description":"Marinade chicken:","images":[],"step":3},{"description":"Cut chicken into small 1.25 cm / 1/2\" cubes.","images":[],"step":4},{"title":"Marinade","description":"Whisk marinade in a bowl. Add chicken, stir to coat, then refrigerate for 1 hour (no longer than 24 hours).","images":[],"step":5},{"description":"Prepare breading:","images":[],"step":6},{"title":"Breading mixture","description":"Mix together Breading and all KFC Secret Herbs & Spices in a large bowl (larger surface area = coat more chicken in one go).","images":[],"step":7},{"description":"Clump = crunchy! Drizzle 3 tablespoons of the Marinade into the flour mixture. Use your fingers to rub in so you get lots of small lumpy bits all throughout (this fries up into extra crunchy bits, secret trick!).","images":[],"step":8},{"description":"Prepare to cook (work in specified order of steps):","images":[],"step":9},{"title":"Frying vessel (Note 5)","description":"Large saucepan / small pot ~20cm/8\" recommended for beginners. Large pot / deep skillet ~24cm/9.5\" or larger recommended only for capable cooks. Use heavy based (not light and flimsy), for safety and heat retention.","images":[],"step":10},{"description":"Preheat oven to 50°C/125°F, to keep cooked chicken warm.","images":[],"step":11},{"description":"Breading (PS I''m right handed):","images":[],"step":12},{"title":"Bread chicken","description":"Pick up a handful of chicken from the marinade with your left hand, then scatter across surface of the flour mixture. Spoon flour over chicken then toss with the spoon to coat.","images":[],"step":13},{"title":"Shake off excess (use right hand)","description":"Separate the chicken pieces and press the clumpy flour onto the chicken pieces. Pick up a handful, shake excess flour off through fingers (no need to be thorough). Spread chicken on tray. Repeat with remaining chicken. Voila! No clumpy flour-batter-caked fingers!","images":[],"step":14},{"title":"Separate and last minute coat (Note 6)","description":"Just before frying, use your fingers to briefly re-toss the chicken you''re about to cook in the residual flour on the tray (to freshen up the flour coating, as it sits around it sweats/gets wet), and make sure the chicken pieces are not stuck together.","images":[],"step":15},{"description":"Line a tray with paper towels (for draining cooked chicken). Preheat oven to 50°C/125°F to keep cooked chicken warm.","images":[],"step":16},{"title":"Heat oil","description":"Add oil to your pot to a depth of 2.5 cm / 1\". Heat it over medium high to 180°C/350°F (Note 7).","images":[],"step":17},{"title":"Fry 2 minutes","description":"Pick up some chicken and put it in a spider with large holes (Note 8) and shake so excess flour falls through (or use hands to shake off excess flour then then transfer into a scoop to lower into oil). Carefully lower chicken into the oil. Fry for 2 - 2.5 minutes until golden, separating any that get stuck together around halfway through.","images":[],"step":18},{"title":"Drain","description":"Scoop out with a spider and spread on a paper towel lined tray Keep cooked chicken warm in the oven and cook remaining chicken.","images":[],"step":19},{"title":"Serve chicken","description":"in popcorn boxes, for extra fun factor! - with dipping sauce of choice (pictured, Honey Mustard).","images":[],"step":20}]', '["egg","gluten","milk","mustard","peanuts"]', '["high_protein","keto_friendly","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Southern","Western"],"categories":["american","chicken-breast-recipes","chicken-recipes","deep-fried-recipes","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_28f5dd915897', 'en', 'US', 'Chili dogs', 'Recipe video above. A pan-fried or BBQ sausage smothered in chili sauce in a hot dog bun. Cracker of a recipe for summer BBQ''s, gatherings with friends and game-day! My chili sauce is a copy-cat of the famous Ben''s Chili Bowl half-smoke chili dogs in Washington DC. Love how their boldly spiced chili sauce is thick and almost "smooth", so it stays in the hot dog better. I replicated this by blitzing the chili a bit. Releases flavour, thickens the sauce. Win!Also, skip the cheap hot dog "footy franks". Do what Ben''s does - use a good smoked sausage.', 'https://www.recipetineats.com/tachyon/2023/02/Chili-dog.jpg', 20, 210, 230, 6, '[{"id": "ing_smoked_paprika", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sausages", "quantity": {"value": 0.012, "unit": "pack of 500g"}}, {"id": "ing_bread", "quantity": {"value": 6.0, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["3 tsp smoked paprika (sub plain paprika)","3 tsp cumin powder","1 tsp cayenne pepper (, adjust to taste)","1 1/2 tsp garlic powder","1 1/2 tsp onion powder","1 1/2 tsp oregano","1/2 tsp mustard powder","1/2 tsp black pepper"],"purpose":"Homemade chili powder (Note 1):"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, finely minced)","1/2 onion (, finely chopped)","1/2 red capsicum / bell pepper (, finely chopped)","500 g/1 lb ground beef / beef mince","1 tbsp tomato paste","400g / 14 oz canned crushed tomato","2 beef cubes (I like Oxo, easy to crumble, Note 2)","1 1/2 cups water","3/4 tsp cooking/kosher salt (, plus more to taste)"],"purpose":"Chili sauce:"},{"ingredients":["6 good smoked sausages (kransky, bratwurst, half-smoke) or hot dogs of choice (Note 3)","6 hot dog buns","1/2 white onion (, finely chopped)","Yellow mustard (I use Heinz American mustard)","2 cups Colby or Monterey Jack (, shredded (or other cheese of choice))","Plain crinkle cut potato chips (, optional side for serving (traditional!))"],"purpose":"Chili dogs:"}]', '[{"title":"Sauté aromatics","description":"Heat oil over medium high in a heavy based pot. Cook the onion, garlic and capsicum for 3 minutes.","duration":3,"images":[],"step":1},{"title":"Brown beef","description":"Add beef and cook, breaking it up as you go, until you no longer see raw meat. Add tomato paste and stir for 1 minute.","duration":1,"images":[],"step":2},{"title":"Sauce","description":"Add the spices, tomato, water, crumbled beef cube and salt. Stir well.","images":[],"step":3},{"title":"Slow cook 3 hours","description":"Bring the chili to a simmer then turn down to low, on a small burner. Put the lid partially on (to allow for sauce reduction). Simmer for 3 hours on low (goal: small bubble every now and then), stirring just to ensure the base doesn’t catch. OR put it in a 160°C/325°F oven for 3 hours (lid partially cracked).","images":[],"step":4},{"title":"Slow cooker (Note 4)","description":"Reduce water to 3/4 cup. After chili comes to a simmer on the stove, transfer everything to a slow cooker then cook on low for 6 to 8 hours on low.","images":[],"step":5},{"title":"Thicken sauce","description":"Remove 1 1/2 cups of the chili into a container so the head of a stick blender will be submerged under the chili. Then blitz until smooth (~ 15 seconds). Add the pureed sauce back in the pot and stir well.","images":[],"step":6},{"title":"Sauce goal","description":"As you stir, the remaining beef bits should become quite fine (rather than bolognese type chunks) because the beef is so tender. If the beef bits are not as small as desired, use a potato masher in the pot - it won''t take long. The chili sauce should be a thick sauce that mounds up a bit when you scoop it, not runny. (Note 5) Keep sauce warm.","images":[],"step":7},{"title":"Optional rest overnight","description":"Allow the sauce to cool then refrigerate overnight. As with most slow-cooked stewy things, the flavour improves! Reheat on the stove before proceeding.","images":[],"step":8},{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":9},{"title":"Grill/pan-fry","description":"Preheat a pan with 1/2 tbsp oil (or the BBQ) on medium / medium high. Brown the stages all over until they are heated through (they are already cooked inside, it''s just about heating/colour).","images":[],"step":10},{"title":"Assemble","description":"Place hot dog buns on a tray. Stuff with a sausage, top with a squiggle of mustard and a sprinkle of onion. Spoon over a generous amount of warm chili sauce, top with cheese.","images":[],"step":11},{"description":"Bake for 7 to 10 minutes or until the cheese is melted. Serve immediately. Traditionally with a mound of plain crinkle cut potato chips and an ice cold beer!","duration":8.5,"images":[],"step":12}]', '["milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["American","Tex-Mex"],"categories":["american","beef","beef-mince-recipes","beef-recipes","grilling-ideas-and-recipes","mains","sandwiches-and-sliders","sausage-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ef8334721dda', 'en', 'US', 'My best Pulled Pork', 'Recipe video above. This takes 36 hours to make - but it''s worth it. A 24-hour dry brine seasons the pork all the way through, followed by slow-roasting for 12 hours at a really low temperature. I would not tell you to roast a pork for 12 whole hours if I was not 100% sure that this produces the very best results! It really does, and the reason is simple: lower heat means less moisture loss which means more succulent meat. Plus, a great bark on the surface that everybody loves about traditional BBQ food. It’s my favourite part!', 'https://www.recipetineats.com/tachyon/2022/10/12-hour-BBQ-pulled-pork_7-3.jpg', 15, 720, 735, 15, '[{"id": "ing_pork_shoulder", "quantity": {"value": 4.5, "unit": "kg"}}, {"id": "ing_beer", "quantity": {"value": 2.0, "unit": "bottle of 330ml"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.075, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_cumin", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.5, "unit": "bottle of 500ml"}}, {"id": "ing_ketchup", "quantity": {"value": 3.0, "unit": "bottle of 500g"}}, {"id": "ing_molasses", "quantity": {"value": 0.113, "unit": "jar"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 0.08, "unit": "bottle"}}, {"id": "ing_tabasco", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["4 - 5 kg / 8 - 10 lb pork butt / Boston butt / square cut pork shoulder (skinless, bone in, fat cap on, Note 1)","1 1/2 cups beer (, any except dark beers like Guinness (Note 2))","1 cup water"]},{"ingredients":["6 tbsp brown sugar","2 tbsp paprika powder","1 tbsp garlic powder","1 tbsp onion powder","1 tbsp mustard powder","2 tsp cumin powder","2 tsp dried oregano","1 tsp cayenne pepper (can omit)","2 tbsp cooking/kosher salt* (Note 4)","2 tsp black pepper"],"purpose":"RUB (Note 3):"},{"ingredients":["1 cup apple cider vinegar (Note 5)","3 cups ketchup (or Aussie tomato sauce)","1 cup water","3 tbsp molasses (original, not backstrap, Note 6)","2/3 cup brown sugar","4 tsp Worcestershire sauce","2 tsp Tabasco (optional spiciness)","4 tsp mustard powder","3 tsp garlic powder (sub onion powder)","2 tsp cooking/kosher salt (Note 4)","2 tsp black pepper"],"purpose":"BARBECUE SAUCE:"}]', '[{"title":"Dry brine overnight (Note 7)","description":"Pat the pork dry and place in a large ceramic dish. Mix Brine ingredients in a small bowl and rub it all over the pork, being sure to get into the cracks and crevices. Turn it fat side up (smoother side) covered with as much rub as possible. Refrigerate uncovered for 24 hours.","images":[],"step":1},{"description":"Preheat oven to 110°C (both fan-forced and standard) / 230°F.","images":[],"step":2},{"title":"Prepare for roasting","description":"Transfer pork to a roasting pan (do not wipe the rub off) with the fat side up. Discard any liquid and residual rub left in the brining dish. Pour beer and water around the pork, topping up with extra water as needed so the liquid level is 2.5 cm / 1\" (insurance against pan going dry).","images":[],"step":3},{"title":"Slow roast 12 hours (Note 8)","description":"Roast, uncovered, for 12 hours, or until the internal temperature reaches 95°C/203°F and the meat falls apart effortlessly using two forks. ⚠️ Make sure your oven does not automatically turn off mid cook, many have auto-off functions that kick in at 12 hours (also factor in oven pre-heating time)!","images":[],"step":4},{"title":"Shred","description":"Transfer the pork to a large pan (reserve juices in roasting pan). Rest for 20 minutes then shred with tongs / forks - it will be effortless! You can discard the fat cap at this stage if you want. I leave some, it makes the shredded pork even juicier.","duration":20,"images":[],"step":5},{"title":"Sauce it","description":"Pour 3/4 cup of the juices from the roasting pan and 1 cup of Barbecue Sauce (see below) over the pork, and toss.","images":[],"step":6},{"description":"Serve Pulled Pork with remaining Barbecue Sauce on the side so people can help themselves. Either make a big Southern feast with a side of cornbread, coleslaw and potato salad or macaroni salad. Or make Pulled Pork buns with soft rolls stuffed with coleslaw, Pulled Pork and the BBQ sauce!","images":[],"step":7},{"description":"Barbecue sauce:","images":[],"step":8},{"description":"Place ingredients in a large saucepan and whisk to combine.","images":[],"step":9},{"title":"Simmer 45 minutes","description":"Bring to simmer on medium heat, then reduce to a low simmer for 45 minutes. Stir occasionally.","duration":45,"images":[],"step":10},{"title":"Add pork juices","description":"When the pork is cooked, add 1/2 cup of the juices from the roasting pan into the BBQ sauce and simmer for 5 minutes. Use water to control thickness – it should have a thick syrupy consistency. Serve warm or at room temperature (not fridge cold).","duration":5,"images":[],"step":11}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Southern"],"categories":["american","iconic-dishes","main-dishes","mains","pork","pork-recipes","slow-cooked-fall-apart","sunday-supper","super-bowl-party-food","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a6efcb1570e6', 'en', 'US', 'Mapo Tofu', 'Recipe video above. Mapo Tofu is in my all-time Top 5 foods. That''s how much I love it. So I am beyond excited to bring you this Sichuan classic that is everything a great, authentic Mapo Tofu should be - fiery, deeply savoury, unapologetically bold and so incredibly delicious, I almost wept with happiness!It''s a recipe from our RTM Chef Xiao (Hannah) Huang, born and raised in Sichuan. So she knows a thing or two about Mapo Tofu! See all Hannah''s recipes here.See Notes section for spiciness and how to control.PS I know 100g/3.5oz pork doesn''t sound like a lot compared to 600g/21oz tofu, but it seems like so much more in the finished dish! Mapo tofu magic :)', 'https://www.recipetineats.com/tachyon/2026/07/Mapo-tofu-0.jpg', 20, 25, 45, 4, '[{"id": "ing_black_pepper", "quantity": {"value": 0.037, "unit": "jar of 50g"}}, {"id": "ing_tofu", "quantity": {"value": 2.0, "unit": "pack of 300g"}}, {"id": "ing_water", "quantity": {"value": 4.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.06, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_beans", "quantity": {"value": 0.037, "unit": "can of 400g"}}, {"id": "ing_broad_bean_sauce_paste", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_beef_stock", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 tbsp whole pink Sichuan peppercorns (or green) - for 1 tsp powder (Note 1)"]},{"ingredients":["600g/ 21 oz silken tofu (, cut into 1.5cm / 0.6\" squares (Note 2))","2 1/2 cups water","1 tsp cooking salt / kosher salt (halve for table salt, +50% for salt flakes)","1/2 tsp dark soy sauce (Note 3)"],"purpose":"Blanched tofu:"},{"ingredients":["1 tbsp canola oil (, or other neutral oil eg. vegetable, peanut)","100g/ 3.5 oz pork mince (ground pork), preferably 20% fat but even lean is fine, or beef (Note 4)","1 tsp light soy sauce (or regular / all-purpose soy, not dark soy sauce)"],"purpose":"Golden pork:"},{"ingredients":["1/4 cup canola oil (Note 5)","2 tbsp garlic (, finely minced (4 large cloves))","2 1/2 tbsp ginger (, finely minced with a knife)","1 tbsp preserved black beans (aka salted black beans, fermented black beans), finely chopped (Note 6)","1 tbsp broad bean sauce/paste (, we use Pixian doubanjiang, the spicy Sichuan version (Note 7))","1 tsp light soy sauce (or regular / all-purpose soy, not dark soy sauce)","2 tsp chilli powder (, pure - NOT US chili powder blend (Note 8))","1 tsp smoked paprika (substitute regular/sweet paprika)","1 tsp white sugar","1 green onion stem (, finely sliced)","3/4 cup beef stock/broth (, low sodium)","1 tsp sesame oil (toasted ie. brown, not un-toasted which is yellow)"],"purpose":"Mapo tofu:"},{"ingredients":["2 tsp cornflour / cornstarch","1/4 cup water"],"purpose":"Cornflour slurry"},{"ingredients":["White rice"],"purpose":"Serving"}]', '[{"description":"Toast, grind and sift Sichuan peppercorns. Blanch tofu 3 min. Cook pork until golden, remove.","images":[],"step":1},{"description":"Sauté garlic and ginger 90 sec, then black bean and bean sauce 3 min, then chilli and paprika 30 sec. Add beef stock and soy, simmer tofu 10 min. Add sugar, pork, 1/2 tsp Sichuan pepper, then thicken sauce with cornflour slurry. Stir in green onion and sesame, serve garnished with 1/2 tsp Sichuan pepper.","images":[],"step":2},{"description":"Sichuan pepper powder:","images":[],"step":3},{"title":"Toast peppercorns","description":"In a small skillet over medium heat (no oil), toast the peppercorns for 2 - 3 minutes until fragrant (some will “pop” and crack open).","duration":2.5,"images":[],"step":4},{"title":"Grind and sift","description":"Transfer to a mortar and pestle, or spice grinder. Cool for a few minutes, then grind as finely as possible. Sift through a fine mesh sieve to remove the coarser husks (discard these). Measure out 1 teaspoon to use in the dish.","images":[],"step":5},{"title":"Blanch","description":"Bring the water, dark soy and salt to a boil in a large saucepan over higher heat. Carefully add the tofu, then once it comes back up to the boil, lower the heat slightly so it’s simmering rapidly and simmer for 3 minutes. This step removes raw beany flavour and seasons the tofu. And don''t worry, the tofu won''t fall apart!","duration":3,"images":[],"step":6},{"title":"Remove","description":"Use a slotted spoon to carefully scoop the tofu out into a bowl. Set aside.","images":[],"step":7},{"title":"Cook golden pork","description":"Heat the oil in a wok over high heat. (Note 9) Cook pork, breaking it up as you go, until you no longer see pink. Then lower the heat to medium and cook for another 2 minutes until the pork has golden bits. Add the light soy sauce, stir for 5 seconds, the remove the pork into a bowl and set aside.","duration":0.08333333333333333,"images":[],"step":8},{"title":"Sauté aromatics","description":"Reduce heat to low. Add the rest of the oil into the wok, then cook the garlic and ginger for 90 seconds. Add black beans and broad bean paste, cook for 3 minutes, stirring constantly. Add chilli powder and paprika, cook for 30 seconds..","duration":1.5,"images":[],"step":9},{"title":"Simmer","description":"Add the beef stock and light soy. Turn the heat up to medium high, then once it starts bubbling, gently add the tofu (discard any excess water pooled in the tofu bowl). Simmer gently for 10 minutes (lower heat as needed), gently scraping the base with a rubber spatula every now and then to ensure it doesn’t catch (I push across base, avoid stirring as tofu will break). There should still be plenty of liquid at the end, mapo tofu is saucy.","duration":10,"images":[],"step":10},{"title":"Cornflour slurry","description":"Mix the water and cornflour together. This will thicken the sauce.","images":[],"step":11},{"title":"Thicken sauce","description":"Add the sugar, pork mince, 1/2 teaspoon sichuan powder. Stir gently using the rubber spatula. Pour the cornflour slurry all over the surface (not in one place) then gently stir again.","images":[],"step":12},{"title":"Finish and serve","description":"Stir in most of the green onion (reserve a little for garnish) and sesame oil. Pour into a serving bowl. Sprinkle with remaining Sichuan pepper and garnish with green onion. Serve over rice!","images":[],"step":13}]', '["gluten","peanuts","sesame","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese","Sichuan"],"categories":["asian-recipes","asian-takeout","chinese-recipes","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0350dff8c6de', 'en', 'US', 'Easy Chinese Beef Stir Fry', 'Recipe video above. This is my classic Chinese Beef Stir Fry. It''s easy and fast, and really does taste just like your favourite Chinese restaurant thanks for the stir fry sauce (the secret is Chinese cooking wine).Great recipe to use up whatever leftover greens you have in the fridge! And you''ll love the velveting beef technique - simple and highly effective Chinese restaurant method for succulent, soft beef in stir fries.Tip: Instead of making this Sauce, you can use Charlie, my All Purpose Stir Fry Sauce (see Note 3)', 'https://www.recipetineats.com/tachyon/2015/12/Chinese-Beef-Stir-Fry_8.jpg', 15, 8, 23, 3, '[{"id": "ing_beef_steak", "quantity": {"value": 7.0, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.005, "unit": "tub of 200g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bok_choy", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["7 oz / 200 g beef rump steak or flank (, or any other quick cooking steak cut (Note 1))","1/2 tsp baking soda / bi-carbonate soda (, for velveting (Note 2))"],"purpose":"Velveting the beef (tenderising)"},{"ingredients":["2 tbsp soy sauce, light or all-purpose (NOT dark soy (Note 4))","1 tbsp oyster sauce","2 tbsp Chinese cooking wine ( OR Mirin (Note 5))","1 tsp white sugar","1/2 tsp sesame oil (, toasted (brown) not untoasted (yellow))","Pinch white pepper (, substitute with black pepper)"],"purpose":"Sauce (Note 3)"},{"ingredients":["3 tsp cornstarch / corn flour","1/2 cup water (, separated)"],"purpose":"Sauce thickener"},{"ingredients":["1 1/2 tbsp peanut oil","1 garlic clove (, finely minced with a knife)","1/2 small onion (, sliced (yellow, brown or white))","1/2 red capsicum / bell pepper (, sliced into 7mm / 1/3\" thick slices)","1 small carrot (, peeled, halved lengthwise and sliced thinly on the diagonal)","2 bok choy (, cut leaves from stems, cut thick stems lengthways to make them all roughly the same width)","2 green onion (, cut into 1.5\"/3cm pieces, firm white end separated from soft green parts)"],"purpose":"Stir Fry"},{"ingredients":["Steamed white rice","Sesame seeds (optional)"],"purpose":"To Serve"}]', '[{"description":"Abbreviated recipe","images":[],"step":1},{"description":"Tenderise beef 20 minutes, rinse, toss with 1.5 tbsp sauce. Mix in cornflour then water into Sauce. Stir fry in this order: onion + garlic > beef > carrot + capsicum + bok choy stems + green onion stems > sauce > wilt bok choy leaves + green onion. Serve!","images":[],"step":2},{"description":"Velvet beef (tenderise)","images":[],"step":3},{"title":"Velvet beef","description":"Place the beef in a bowl. Sprinkle the baking soda over then use your fingers to toss the beef to coat as evenly as possible. Set aside for 20 minutes (no longer).","duration":20,"images":[],"step":4},{"description":"Rinse the beef under tap water in a colander to remove baking soda. Shake and pat off excess water (doesn''t need to dry fully, just don''t want it soaking). Put in a bowl.","images":[],"step":5},{"description":"Cook stir fry","images":[],"step":6},{"title":"Sauce","description":"Mix ingredients together. Measure out 1 1/2 tablespoons and use it to coat the beef. To the remaining sauce, mix in the cornflour until lump-free, then add the water.","images":[],"step":7},{"title":"Cook aromatics","description":"Heat the oil in a large non-stick pan or wok over high heat. Add the onion and garlic, cook for 10 seconds.","duration":0.16666666666666666,"images":[],"step":8},{"description":"Add the beef and cook until it changes colour from red to light brown but not cooked through.","images":[],"step":9},{"title":"Vegetables #1","description":"Add the capsicum, carrots, bok choy stems and white part of the green onions. Stir fry for 1 minute","duration":1,"images":[],"step":10},{"description":"Add Sauce, then stir until it starts to bubble (it will thicken quickly)","images":[],"step":11},{"title":"Leafy vegetables","description":"Add the bok choy leaves and green part of the green onions. Toss for another 30 seconds to 1 minute until they are just wilted, the sauce thickens and becomes glossy, coating everything nicely.","images":[],"step":12},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Garnish with sesame seeds, if desired.","images":[],"step":13}]', '["gluten","peanuts","sesame","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","beef-recipes","chinese-recipes","dinner-tonight","main-dishes","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_04b91e1bf760', 'en', 'US', 'Korean Beef Bulgogi Rice Bowls - the easy way', 'Recipe video above. This has gone straight to the top of my favourite quick way to use beef mince! An easy version of Korean Beef Bulgogi, one of Korea''s most famous food exports, made with ground beef rather than pricey steaks but using an authentic Bulgogi marinade so it takes a fraction of the effort and cost. I’ve made rice bowls, there''s many ways to serve this - noodles, rice wraps, burritos or tacos (so trendy!). See in post for list!PS Don''t skip the apple and grated onion. This is what sets bulgogi apart from generic soy + sugar + garlic "Asian" sauces!', 'https://www.recipetineats.com/tachyon/2025/09/Easy-Korean-Bulgogi-Beef-Bowls_7.jpg', 15, 10, 25, 4, '[{"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.03, "unit": "pack of 1kg"}}, {"id": "ing_apples", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 3.0, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.06, "unit": "pack of 100g"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 4.0, "unit": "bag of 250g"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["500g / 1 lb beef mince ((ground beef), any fat % you like)","1 tbsp canola oil (, or any other plain flavoured oil, + 2 tsp (to wilt baby spinach))"]},{"ingredients":["1 tbsp onion (, finely grated (~1/4 onion) (Note 1))","3 tbsp red apple (, finely grated (skin on is fine, ~1/2 apple) (Note 1))","3 garlic cloves (, finely grated)","1 tsp ginger (, finely grated)","2 1/2 tbsp soy sauce ( - all-purpose or light (Note 2))","1 tbsp sesame oil","1 tbsp mirin (, omit for no alcohol (Note 3))","1 tbsp brown sugar","1/8 tsp black pepper"],"purpose":"Bulgogi sauce (don’t skip the onion & apple!):"},{"ingredients":["2 tbsp soy sauce ( - all-purpose or light (Note 2))","1 tbsp sesame oil","2 tsp brown sugar","2 tsp rice vinegar (or apple cider vinegar)"],"purpose":"Rice bowl drizzle sauce:"},{"ingredients":["white rice (medium or short grain, if you can)","4 large handfuls baby spinach (or similar chopped leafy greens - cabbage, kale)","1 large carrot (, peeled and julienned or grated using box grater (I use a julienne shredding tool))","1 avocado (, mashed)","1/4 cup pickled ginger (, I like pink for colour)","1 1/2 cups baby cos / romaine lettuce (, torn into bite size pieces)","1 tsp white sesame seeds","1 green onion (, finely sliced)"],"purpose":"For rice bowl (very flexible!):"}]', '[{"title":"Sauces","description":"Mix the Bulgogi sauce in a bowl, and the rice bowl drizzle sauce in a separate bowl.","images":[],"step":1},{"title":"Wilt spinach","description":"Heat the 2 teaspoons of oil in a large non-stick pan over high heat. Add half the spinach, toss with tongs until semi wilted (~30 sec), then add the rest. Toss until wilted (~ 1 minute) then remove into a bowl.","images":[],"step":2},{"title":"Cook Bulgogi beef","description":"Add 1 tablespoon oil to the pan. Still on high heat, add the beef and cook, breaking it up as you go, until you no longer see raw beef. Add the Bulgogi sauce, then let it simmer rapidly, stirring every now and then, until the sauce is mostly evaporated. Then stir regularly until the beef gets a bit of lovely caramelisation on it, but is still moist from the sauce.","images":[],"step":3},{"title":"Assemble","description":"Spoon beef over rice, place spinach and carrot. Top with pickled ginger and a dollop of mashed avocado. Tuck lettuce down the side. Sprinkle with sesame seeds and green onion. Serve with sauce for drizzling all over everything before jumbling it all up and digging in!","images":[],"step":4}]', '["gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","korean fusion"],"categories":["asian-recipes","beef-mince-recipes","beef-recipes","modern-asian","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_004ad51c5489', 'en', 'US', 'Easy Crispy Thai Pork Bites with Sticky Sweet Chilli Sauce', 'Recipe video above. This is the sort of dish you find at modern Thai restaurants - golden cubes of pork tenderloin, crispy on the outside and succulent inside, tossed in a sticky limey, sweet chilli sauce.6 ingredients. Gluten free. No deep frying. All the flavour. None of the fuss! Dinner on the table in 20 minutes.PS Haven''t tried air frying but confident it will work great!', 'https://www.recipetineats.com/tachyon/2025/09/Crispy-Thai-Pork-Bites-Sweet-Chilli-Sauce_4.jpg', 10, 10, 20, 4, '[{"id": "ing_pork", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 2.0, "unit": "pack of 400g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_ime_juice", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["600 g / 1.2 lb pork tenderloin (, cut into 2cm/0.8\" cubes (Note 1))","1 tbsp fish sauce (Note 2)","1 1/2 tbsp + 1/2 cup cornflour / cornstarch","> 1 cup neutral flavoured oil (, 0.5cm / 0.2\" depth (canola, sunflower, vegetable, peanut oil - not olive oil))"],"purpose":"Crispy pork bites:"},{"ingredients":["1/2 cup sweet chilli sauce (Note 3)","1 1/2 tbsp lime juice","1 tbsp fish sauce (Note 2)","2 garlic cloves (. finely grated)"],"purpose":"Sweet chilli sauce:"},{"ingredients":["Coriander/cilantro leaves (, roughly torn by hand, optional)","Lime wedges (, optional)","Jasmine rice (, or other rice of choice)"],"purpose":"Garnish and serving:"}]', '[{"description":"Toss pork with fish sauce and 1.5 tbsp cornflour, then coat in 1/2 cup cornflour, shake off excess. Cook in 2 batches for 3 min until golden, remove from oil. Simmer sauce 3 min, toss to coat pork, serve.","duration":3,"images":[],"step":1},{"description":"Toss the pork with the fish sauce, then the 1 1/2 tbsp cornflour. The coating should be a bit sticky.","images":[],"step":2},{"title":"Crispy coating","description":"Sprinkle over the 1/2 cup of cornflour and toss with fingers to coat each piece, separating pieces stuck together. Give each piece a light squeeze in your fist to make the cornflour stick - you can do 2 or 3 pieces at a time in each hand. Drop into a colander, then give it a shake to remove excess cornflour - important step. (Note 4)","images":[],"step":3},{"description":"Heat 0.5 cm / 0.2\" oil in a non-stick pan or large pot over high heat - dip a piece of pork in, it should sizzle straight away.","images":[],"step":4},{"title":"3 minute cook","description":"Spread half the pork in the oil. Cook for 1 minute undisturbed until golden. Flip then cook for another 2 minutes (3 minutes in total, including time it takes to flip) or until golden and crisp. Don''t overcook - tenderloin is lean!","duration":1,"images":[],"step":5},{"title":"Drain","description":"Remove with a slotted spoon onto a paper towel-lined tray to drain. Cook remaining pork. Taste-test one \"just to check\" crispiness! ;)","images":[],"step":6},{"title":"Sauce","description":"Pour out all the oil (strain and re-use, it''s very clean). Return the pan to medium heat. Add the Sauce ingredients, stir and let it simmer for 2 minutes until it thickens into a syrupy consistency.","duration":2,"images":[],"step":7},{"title":"Quick toss","description":"Add pork, toss quickly to coat.","images":[],"step":8},{"description":"Serve immediately over rice, sprinkled with a little coriander and a lime wedge. I like to serve it classic Thai street-food style with plain tomato and cucumber wedges (no dressing) - the freshness is great with this dish!","images":[],"step":9}]', '["fish","peanuts"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["modern thai"],"categories":["asian-recipes","cuisines","mains","modern-asian","pork","pork-recipes","quick-and-easy","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_58a74d9254a2', 'en', 'US', 'Crispy Chinese Lemon Chicken - old school style!', 'Recipe video above. I like my Chinese Lemon Chicken the old school way, with a crispy battered cutlet sliced then sauced! The twice-fried Chinese fry batter used here stays crisper than regular batters (also less greasy) but once doused with the lemon sauce, it''s best served and eaten fast! Lemon sauce has a high water content so the crust will never stay crispy as long as other Chinese fried foods like, say, Honey Prawns.You''ll love the lemon sauce - brighter flavour and not tooth-achingly sweet like restaurants often are. For crispy bite size pieces, use the sauce in this recipe with the chicken from the Crispy Chinese Honey Chicken.', 'https://www.recipetineats.com/tachyon/2025/08/Crispy-Chinese-Lemon-Chicken_0.jpg', 20, 10, 30, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 2.0, "unit": "pack of 400g"}}, {"id": "ing_oil", "quantity": {"value": 1.25, "unit": "bottle"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.003, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.005, "unit": "tub of 200g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 x 125g/3oz chicken thigh fillets (, skinless and boneless (or 2 breasts - Note 1))","1/2 tsp cooking salt / kosher salt","1/4 cup cornflour / cornstarch","1 - 1 1/2 litres (4 - 6 cups) vegetable or canola oil (, for frying - 4cm / 1.6\" depth (re-usable, Note 2))"]},{"ingredients":["1/3 cup cornflour / cornstarch","1/3 cup + 1 tbsp plain flour (all-purpose flour)","1/2 tsp cooking salt / kosher salt","1/4 tsp baking powder","1/2 cup COLD soda water (, not sparking mineral water (Note 3))"],"purpose":"STAY-CRISP FRY BATTER"},{"ingredients":["6 tsp cornflour/cornstarch","1/2 cup chicken stock/broth (, low sodium)","1/2 cup lemon juice (, fresh)","1/3 cup white sugar","1/2 tsp garlic (, finely grated)","1/2 tsp ginger (, finely grated)","1 tbsp Chinese cooking wine (can omit for alcohol-free)"],"purpose":"LEMON SAUCE"},{"ingredients":["Lemon slices (, to serve (optional))","1 green onion (, finely sliced on the diagonal, to serve (optional))"],"purpose":"GARNISH (optional)"}]', '[{"description":"Pound chicken to 0.7cm / 1/3\", salt, dust with cornflour. Dip in batter, fry 3 min at 160°C/320°F, cool 20 min, fry again 3 min at 200°C/390°F until dark golden and crispy. Slice, serve with sauce (simmer 3 min).","images":[],"step":1},{"title":"Refrigerate batter dry","description":"Whisk the cornflour, flour, baking powder and salt in a bowl, then put it in the fridge which you proceed with other prep (Note 4)","images":[],"step":2},{"title":"Pound chicken","description":"Place chicken on a cutting board and cover with a freezer bag or similar (I use Go-Between, Note 5) then pound with a meat mallet or bottom of a skillet until it is an even 0.7cm / 1/3\" thick. Sprinkle both sides with the 1/2 teaspoon of salt.","images":[],"step":3},{"title":"Dust","description":"Spread the cornflour on a plate and dust each side of the chicken with it, shaking off excess. Put on a plate and set aside while you keep preparing.","images":[],"step":4},{"description":"Preheat oil to 160°C/320°F in a large heavy based pot (mine is 24cm/9.4\"). The oil needs to be at least 4cm/1.6\" depth so the chicken floats.","images":[],"step":5},{"title":"Finish batter","description":"Remove bowl from the fridge, add soda water and whisk just until combined, then stop - some small lumps are ok, better than whisking to death (makes crust less puffy and light). It should be a fairly thin batter, enough to coat the chicken but fairly thinly.","images":[],"step":6},{"title":"Fry #1","description":"Dip a piece of chicken in the batter and let the excess drip off, then carefully place in the oil. Do another piece (if it will fit). Fry for 3 minutes until very pale golden. Remove onto a paper towel lined tray and repeat with remaining chicken.","duration":3,"images":[],"step":7},{"description":"Cool chicken for 20 minutes. (Note 6) Meanwhile, make the sauce.","duration":20,"images":[],"step":8},{"title":"Lemon Sauce","description":"Place the cornflour and a splash of the chicken stock in a small saucepan. Whisk until lump-free, then add remaining stock and sauce ingredients. Whisk and bring to a simmer over medium heat, then let it simmer for 3 minutes, whisking every now and then until it becomes a thin honey consistency. At first, it will go very thick (too thick for sauce) then it becomes thinner. Remove from heat, cover and keep warm (reheated if needed to loosen).","duration":3,"images":[],"step":9},{"title":"Fry #2","description":"Heat the oil to 200°C/390°F. Fry 2 pieces of chicken for 3 minutes until deep golden and super crispy, turning the chicken in the oil at the halfway mark. Remove onto a paper towel lined tray and repeat with remaining chicken.","duration":3,"images":[],"step":10},{"title":"Serving","description":"Cut the chicken into 2cm thick slices (3/4\"), transfer onto individual or shared serving plate. Pour over the Lemon Sauce, garnish with green onions and lemon slices if using. Serve with steamed rice (see in post for more side options).","images":[],"step":11}]', '["gluten"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken","chicken-breast-recipes","chicken-recipes","chinese-recipes","deep-fried-recipes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6e006a653319', 'en', 'US', 'Pork Adobo', 'Recipe video above. Pork Adobo is the pride of the Philippines - one bite and you''ll be hooked! Pork braised until meltingly tender in an intense soy-garlic sauce that reduces down to a glaze, served over steaming rice, this is food so good yet so simple to make, you''ll be shaking your head in disbelief.Our adobo sauce has a well rounded flavour, intensely savoury but not overly salty or too sour (some restaurants make it really sour), and not too sweet. The sauce is meant to be thin so a little goes a long way on your rice.Slow cooker not recommended, sorry, see Note 6.', 'https://www.recipetineats.com/tachyon/2025/08/Pork-adobo-served-with-rice.jpg', 10, 120, 130, 4, '[{"id": "ing_pork_shoulder", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 8.0, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_pineapple", "quantity": {"value": 6.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.01, "unit": "kg"}}]', '[{"ingredients":["1 kg/ 2 lb pork shoulder (the parts ribboned with fat not lean parts), skinless, cut into 6cm/2.5\" cubes - or belly (Note 1)","2 tbsp vegetable oil (, or any other neutral flavoured oil)","1 large onion (, cut in half then 0.8\" / 1/3\" wedges)","8 cloves garlic (, finely sliced)","3 cups water","1/2 cup light soy sauce (, sub regular/all-purpose soy (Note 2))","1 1/2 tsp dark soy sauce (Note 2)","1/4 cup rice vinegar (sub regular white vinegar)","3 tbsp (tightly packed) brown sugar","1 1/2 tsp black peppercorns (, can omit (Note 3))","5 bay leaves (, preferably fresh, dried ok too)"]},{"ingredients":["6 pineapple rings (, each cut into 8 pieces, from canned pineapple in juice not syrup, or 2 cups fresh pineapple pieces)","2 tsp vegetable oil (, or any other neutral flavoured oil)"],"purpose":"Optional pineapple (Note 4):"},{"ingredients":["1 green onion (, finely sliced)","2 batches jasmine rice"],"purpose":"Garnish/serving:"}]', '[{"description":"Brown pork, remove, sauté onion and garlic, add everything else. Return pork, bring to boil, slow cook 1 1/2 hours until fall-apart. Caramelise pineapple pieces. Remove pork, reduce sauce to 1 1/2 cups (375 ml), stir in pork and caramelised pineapple until warmed. Serve over rice!","images":[],"step":1},{"title":"Sear pork","description":"Heat the oil in a large heavy based pot over high heat. Sear half the pork until golden all over - about 4 minutes - then remove into a bowl. Repeat with remaining pork, add to the bowl.","images":[],"step":2},{"title":"Sauté","description":"Reduce heat to medium. Add the onion, cook for 2 minutes. Add garlic and cook for another minute until the onion is softened.","duration":2,"images":[],"step":3},{"title":"Braising liquid","description":"Add water, soy sauces, vinegar, sugar, peppercorns and bay leaves. Stir. Add the pork back in, including any juices accumulated in the bowl.","images":[],"step":4},{"title":"Slow cook 1 1/2 hours","description":"Bring to a boil, then partially cover with a lid (leave a 2cm / 1\" crack) and reduce the heat to low/medium low so the liquid is simmering very, very gently. (Note 5) Simmer for 1 1/2 hours or until the pork is fall-apart tender (keep simmering if not tender).","images":[],"step":5},{"title":"Caramelise pineapple","description":"While pork is simmering, heat the oil in a non-stick pan over medium heat. Spread the pineapple out in one layer and cook each side until golden, about 4 minutes each side (I use spatula + tongs to turn). Remove onto plate until required.","images":[],"step":6},{"title":"Reduce sauce","description":"Remove pork with a slotted spoon (onion etc doesn''t matter when it''s in or out). Increase heat to high and boil to reduce the liquid down to 1 1/2 cups - it will be a very thin syrup (it''s not supposed to be thick), about 7 to 10 minutes.","images":[],"step":7},{"title":"Coat pork","description":"Reduce heat to low. Add the pork and pineapple pieces, plus any juices in the bowl. Stir gently to coat in the sauce and warm the pork through again.","images":[],"step":8},{"description":"Serve over jasmine rice, garnished with green onion if using.","images":[],"step":9}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Filipino"],"categories":["asian-recipes","iconic-dishes","pork-recipes","slow-cooked-fall-apart","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d6d383962b8e', 'en', 'US', 'The fastest noodle stir fry I know - from scratch!', 'Recipe video above. This family-size noodle stir fry is a complete meal with protein and plenty of veg, made from scratch in just 15 minutes, and it’s seriously tasty. The sauce uses just two ingredients, fish sauce and kecap manis, which might sound like an unusual combination but these have more flavour than regular sauces like soy sauce! Together, they deliver big savoury, sweet, glossy flavour with zero fishiness. I can’t stop making this, it’s perfect for busy weeknights!** Saltiness note: Be sure not to miss the step to use some of the sauce to season the chicken, otherwise too much ends up on the noodles and it can taste a bit too salty. **', 'https://www.recipetineats.com/tachyon/2025/06/2-ingredient-noodle-stir-fry-_5.jpg', 7, 8, 15, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 7.0, "unit": "bunch"}}, {"id": "ing_cabbage", "quantity": {"value": 5.0, "unit": "head"}}, {"id": "ing_kecap_mani", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 0.03, "unit": "pack of 100g"}}]', '[{"ingredients":["400g/14oz chicken thighs (, skinless boneless, thinly sliced 0.75cm/1/4\" thick (or breast))","500g / 1 lb hokkien noodles, lo mein, other noodles (, from the fridge, prepared per packet, rinsed well, drained (Note 1))","1 tbsp peanut oil (or any other neutral oil)","2 garlic cloves (, finely minced)","7 green onions (, cut into 5cm/2\" lengths, soft dark green parts separated from the white / pale green firmer parts)","5 cups green cabbage (, sliced ~1cm / 0.4\" thick (Napa/Chinese cabbage also works))"]},{"ingredients":["2 tbsp kecap mani (sweet soy) ( (Note 2))","1/4 cup fish sauce","1 pinch white pepper (sub black pepper)"],"purpose":"Sauce (just 2 ingredients!):"},{"ingredients":["1 tbsp+ chilli crisp, chilli paste or sriracha (add > taste > add > taste!) (Note 3)"],"purpose":"Optional grown up touch:"}]', '[{"description":"Toss chicken with 2 tbsp sauce. In a large 30cm/12\" non-stick pan over high heat, cook chicken first, adding garlic and white part of green onion towards the end. Cabbage 1 1/2 minutes, then noodles, sauce (add in 2 batches) and chilli crisp. Wilt green onion, serve!","images":[],"step":1},{"title":"Sauce","description":"Mix the ingredients in a small bowl.","images":[],"step":2},{"description":"Toss the chicken with 2 tablespoons of the sauce (no marinating time needed).","images":[],"step":3},{"description":"Cooking:","images":[],"step":4},{"title":"Cook chicken","description":"Heat the oil in a large 30cm/12\" non-stick pan over high heat until very hot. Add the chicken and cook for 2 minutes. Add the garlic and white part of the green onion, cook for another 30 seconds until chicken is just cooked.","duration":2,"images":[],"step":5},{"title":"Cabbage","description":"Add the cabbage, toss for 1 1/2 minutes or until it starts to go floppy.","images":[],"step":6},{"title":"Sauce and noodles","description":"Add the noodles and half the sauce, toss for a minute until the sauce is absorbed and no longer pooling in the pan (~ 45 seconds). Then add the remaining sauce and toss again until it''s all evenly coated and no liquid remains (~ 1 minute), adding chilli crisp towards the end, if using. (Note 4)","images":[],"step":7},{"title":"Serve","description":"Toss through the green part of the green onion until it''s wilted (barely 20 seconds), then divide between bowls. Noodle slurping time!","images":[],"step":8}]', '["fish","peanuts","soy"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eed1600b9acf', 'en', 'US', 'Ginger chicken and rice (one pot recipe!)', 'Recipe video above. This one-pot ginger chicken and rice is inspired by the flavours of Hong Kong claypot rice, steamed with a layer of mushrooms and finished with a drizzle of sauce. It''s gone straight into my top 3 one-pot recipes!I''ve used a mix of Asian mushrooms here which have more interesting textures and impart more flavour into the rice than regular white mushrooms. But I wouldn''t hesitate to make this with any type of mushrooms!', 'https://www.recipetineats.com/tachyon/2025/06/Ginger-chicken-and-rice-with-mushrooms_5.jpg', 10, 25, 45, 4, '[{"id": "ing_oil", "quantity": {"value": 0.24, "unit": "bottle"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.002, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 4.5, "unit": "kg"}}, {"id": "ing_shiitake_mushrooms", "quantity": {"value": 1.0, "unit": "pack of 150g"}}, {"id": "ing_oyster_mushrooms", "quantity": {"value": 1.0, "unit": "pack of 150g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 2.0, "unit": "jar of 50g"}}, {"id": "ing_kecap_manis_note_4", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["4 tbsp oil","500g/ 1 lb chicken thighs (, boneless, skinless, cut into small bite size pieces (Note 1))","1 1/2 cups long grain rice (, NOT RINSED (Note 2))","2 cups chicken stock (, low sodium)","4 green onion stems (, white part finely sliced, green flopped part cut into 5cm/2\" lengths)","1 1/2 tbsp ginger (, grated)","2 large garlic cloves (, finely minced)","4 - 5 slices ginger (~5mm / 0.2\" thick (large enough to easily pick out later), no need to peel)"]},{"ingredients":["150g / 5oz shiitake mushrooms (, fresh (~2 heaped cups), small halved, large thickly sliced)","150g / 5 oz oyster mushrooms ((~2 heaped cups), small kept whole, large cut into 2 or 3)","200g / 7 oz king mushrooms (, halved then cut into thick slices 7mm thick)","2 pinches salt and white pepper (each)"],"purpose":"Mushrooms (use any you want – Note 3):"},{"ingredients":["3 tbsp kecap manis ((sweet soy) - Note 4)","2 tbsp fish sauce","1/8 tsp white pepper (sub black)"],"purpose":"Simple claypot sauce:"}]', '[{"title":"ABBREVIATED","description":"Toss chicken with 1 1/2 tbsp sauce. Sear mushrooms in 2 batches, remove. SeaL chicken, add garlic, ginger and white part green onions towards end. Stir in rice, add stock and ginger slices, cover with mushrooms, steam 20 min. Rest 10 min, toss with sauce and green onion.","images":[],"step":1},{"title":"Sauce","description":"Mix sauce ingredients in a small bowl. Toss chicken with 1 1/2 tbsp of the sauce, set the rest aside for drizzling.","images":[],"step":2},{"title":"Lightly sear mushrooms","description":"Heat 1 1/2 tbsp oil in a large heavy based pot on high heat. Cook half the mushrooms with a pinch of salt and pepper until some of the mushrooms have a light tinge of golden on the surface, but don''t try to cook them all the way through (we want to do that in the rice). Remove into bowl. Repeat with remaining mushrooms.","images":[],"step":3},{"title":"Seal chicken","description":"Heat the remaining 1 tablespoon of oil until hot. Add the chicken and stir for 1 minute, just until the surface is sealed but inside still raw. Add white part of green onion, garlic and ginger, stir 30 seconds. Add rice, stir briefly just to coat in oil.","duration":1,"images":[],"step":4},{"title":"Simmer liquid","description":"Add stock and ginger slices. Bring to a rapid simmer. Scatter mushrooms across surface (add any pooled liquid too), then let it come to a rapid simmer again.","images":[],"step":5},{"title":"Steam 20 minutes","description":"Put the lid on, reduce stove to low (or medium low, for weak burners). Cook for 20 minutes (do not stir) until the liquid is fully absorbed.","duration":20,"images":[],"step":6},{"title":"Rest 10 minutes","description":"Remove pot from the stove with the lid still on and rest for 10 minutes.","duration":10,"images":[],"step":7},{"title":"Drizzle and toss","description":"Drizzle remaining sauce all over, add green part of green onions. Gently toss until the green onion is mostly wilted. Serve!","images":[],"step":8}]', '["fish","shellfish","soy"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","modern-asian","one-pot-recipes","quick-and-easy","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f600a7f8dba3', 'en', 'US', 'Hokkien noodles with chicken', 'Recipe video above. My everyday Hokkien Noodles recipe. A great sauce. Strips of chicken. Lots of vegetables. 6 minute cook. Dinner in 20 minutes flat!', 'https://www.recipetineats.com/tachyon/2024/08/Hokkien-noodles-with-chicken_2.jpg', 14, 6, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 8.0, "unit": "bunch"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["500g/ 1 lb hokkien noodles (, (fridge best) (Note 1))","350g/ 12 oz chicken thighs (boneless, skinless), cut into lot of thin 0.5 x 3cm / 0.2 x 1.2\" pieces (Note 2)","2 tbsp canola oil (or vegetable, cottonseed, peanut oil)","2 garlic cloves (, finely minced)","8 green onion stems (, cut into 5cm / 2\" lengths, white part separated from green part (Note 3))","1 red capsicum (bell peppers) (, cut into thin 0.5cm / 0.2\" strips)","3 heaped cups green cabbage (, cut into thin 1 x 5cm / 0.5 x 2\" strips)"]},{"ingredients":["2 tbsp light soy sauce (Note 4)","1 1/2 tbsp dark soy sauce (Note 4)","2 tbsp oyster sauce (Note 5)","1 tbsp Mirin or Chinese cooking wine (Note 6)","1 tbsp sesame oil (, toasted (Note 7))","1/8 tsp white pepper (sub black pepper)"],"purpose":"Sauce:"},{"ingredients":["White sesame seeds","Finely sliced green onion"],"purpose":"Optional garnishes"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"description":"Marinate chicken with 1 1/2 tbsp Sauce. Cook chicken 1 min, add garlic and white part of green onion, cook 1 min. Add capsicum & cabbage, cook 2 min. Add green part of green onion, noodles, sauce, toss 2 min. Serve!","images":[],"step":2},{"title":"Sauce","description":"Mix the sauce in a small bowl.","images":[],"step":3},{"title":"Briefly marinate chicken","description":"Toss the chicken with 1 1/2 tbsp of the Sauce. Marinate for 10 minutes while you prepare the noodles and vegetables.","duration":10,"images":[],"step":4},{"title":"Rinse noodles","description":"Prepare the noodles per the packet directions (soak in boiling water or briefly boil). Drain in a colander then rinse briefly under tap water (Note 8)","images":[],"step":5},{"title":"Sear chicken","description":"Heat the oil in a large non-stick pan over high heat until very hot (mine is 30cm/12\", Note 9 re: wok). Add the chicken and toss for 1 minute. Add the garlic and white part of the green onion, then toss for another 1 minute or until the surface of the chicken is sealed (but still a bit raw inside)","duration":1,"images":[],"step":6},{"title":"Cook veg & noodles","description":"Add the capsicum and cabbage. Toss for 2 minutes until the cabbage is mostly wilted. Add the green part of the green onions, noodles and sauce. Toss for 1 1/2 to 2 minutes until the noodles are stained a lovely mahogany colour.","duration":2,"images":[],"step":7},{"description":"Serve immediately, sprinkled with sesame seeds and green onion if desired!","images":[],"step":8}]', '["gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chinese-recipes","noodles","quick-and-easy","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3af8d4554aa7', 'en', 'US', 'Beef Tataki', 'Recipe video above. Here''s a Beef Tataki recipe, a fusion Japanese restaurant favorite with thinly sliced beef in a citrusy dressing. Making it at home costs a fraction of eating out!I make the deluxe restaurant version with beef tenderloin, crispy potato straws, and garlic oil for entertaining. Whereas the steak version with Asian Sesame Dressing and a sprinkle of crispy fried shallots with a side of Smashed Cucumbers and Garlic Pot-Steamed Rice is my sort of Monday night meal!Serves 2 as a main with sides or 4 as a starter as part of a larger banquet (see my new fusion Japanese menu here).', 'https://www.recipetineats.com/tachyon/2024/07/Beef-tataki_8.jpg', 20, 30, 50, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cooking_sake", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_yuzu", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_grapes", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["250g / 8 oz beef tenderloin/fillet (PREMIUM option) (- thin piece 13-15cm long (5-6\"), cut to even thickness (Note 1))","300g /10 oz sirloin steak ((aka Porterhouse in Australia, US: New York strip) (Note 2) - EASIER)"],"purpose":"Beef – choose ONE:"},{"ingredients":["1/2 tbsp vegetable oil (or other neutral flavoured oil)","1/4 tsp cooking salt / kosher salt"],"purpose":"Cooking:"},{"ingredients":["1 tbsp cooking sake (Note 4)","2 tsp mirin (Note 4)","1 tbsp rice vinegar (substitute apple cider vinegar)","1 1/2 tbsp Japanese soy sauce (, regular (Note 5))","1 tbsp yuzu (, or 1/2 tbsp each lime and lemon juice (Note 6))"],"purpose":"Yuzu Dressing (Note 3 other options):"},{"ingredients":["2 tbsp grapeseed oil (rapeseed oil or light olive oil)","3 garlic cloves (, sliced 2 mm thick)"],"purpose":"Garlic oil (optional, Note 7)"},{"ingredients":["Crispy potato straws (Pommes Paille, pictured, \"fancier\" option!)","Crispy fried shallots (store bought, easy option)"],"purpose":"Crispy topping options – CHOOSE ONE"},{"ingredients":["1 green onion (, finely sliced (optional curling, Note 8))"],"purpose":"Garnish:"}]', '[{"description":"Beef tenderloin:","images":[],"step":1},{"title":"Prep","description":"Preheat the oven to 130°C / 275°F (all oven types). Rub the beef with the oil and sprinkle with salt. Place on a rack set on a tray.","images":[],"step":2},{"title":"Roast for 18","description":"20 minutes or until the internal temperature in the middle is 41°C / 105°F (check first at 15 minutes, Note 9).","duration":19,"images":[],"step":3},{"title":"Sear","description":"Heat a cast iron skillet on high heat until it is smoking. Sear each side of the beef for just 10 seconds, no longer (I do 4 sides).","images":[],"step":4},{"title":"Cool","description":"Transfer the beef onto a rack on a tray. Cool for 30 minutes on the counter then refrigerate uncovered for 2 hours.","duration":30,"images":[],"step":5},{"title":"Thinly slice","description":"When ready to serve, slice it as thinly as you can without tearing the beef, aiming for 3mm / 1/16\" but up to 5mm / 1/8\" thick is fine. (Note 10 for tips)","images":[],"step":6},{"description":"Place the sake and mini in a tiny saucepan on low heat. Bring to a simmer, then simmer for 1 minute. Pour into a bowl, let it cool. Then stir in remaining dressing ingredients.","duration":1,"images":[],"step":7},{"description":"Garlic infused oil:","images":[],"step":8},{"description":"Put the garlic and oil in a tiny saucepan on low heat. Simmer for 5 minutes, stirring a few times, until the garlic is light golden. Cool for 15 minutes then strain (reserve crispy garlic for another use)","duration":5,"images":[],"step":9},{"title":"Plate up","description":"Lay the beef slices on a plate, overlapping slightly. Drizzle with 3-4 tbsp of the Dressing, then 1 1/2 tbsp of the garlic oil. Pile the crispy potato in a heap in the middle, sprinkle with green onion. (Or use the easy steak garnish options above instead).","images":[],"step":10},{"title":"To eat","description":"Serve straight away. Make sure you get some crispy potato in every bite, and squidge the beef around in the tasty sauce.","images":[],"step":11},{"description":"Easy steak option:","images":[],"step":12},{"title":"Cook","description":"Rub the steak with the oil then sprinkle with the salt. Heat a cast iron skillet on high heat until it is smoking. Cook the steak to rare (1 1/2 - 2 minutes on each side, but it will depend on thickness of steak), or to your taste (Note 11 for doneness). Cool & thinly slice steak per beef tenderloin steps above.","images":[],"step":13},{"title":"Assemble","description":"Place the slices in a line, slightly overlapping. Drizzle over Dressing and oil (or alternative Sauce of choice). Sprinkle crispy fried shallots down the centre then green onion. Serve!","images":[],"step":14}]', '["fish","gluten","soy"]', '[]', '{"mealType":["dinner","snack"],"cuisine":["fusion japanese","Modern Asian"],"categories":["asian-recipes","modern-asian"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_48a44116bb5e', 'en', 'US', 'Easy Singapore Chicken Vermicelli Noodles', 'Recipe video above. This is just a downright delicious and easy noodle stir fry that channels the flavours of everybody''s favourite Singapore Noodles. Same sauce, same egg ribbons, and strips of red capsicum. But with chicken and bacon instead of having to make or hunt down Chinese BBQ Pork and peel fresh prawns! I''ve also added bean sprouts and baby spinach for extra no-chop veg quota to turn this into a complete meal. This might not be traditional but it''s quick, easy, tasty, and you can make it tonight!', 'https://www.recipetineats.com/tachyon/2024/04/Easy-Singapore-chicken-vermicelli-noodles-2.jpg', 15, 10, 25, 3, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.2, "unit": "pack of 500g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.09, "unit": "bottle of 500ml"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.037, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_bacon", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}]', '[{"ingredients":["100 g/3.5 oz dried vermicelli noodles (not glass noodles)"]},{"ingredients":["3 tbsp light soy sauce (, or all-purpose soy (not dark soy) (Note 1))","3 tbsp Chinese cooking wine (Shaoxing wine, Note 2)","3 tsp curry powder (Note 3)","1 tsp white sugar","1/2 tsp white pepper (sub black pepper)"],"purpose":"Singapore noodles sauce:"},{"ingredients":["150g/ 5 oz skinless boneless chicken thighs","1/4 tsp cooking salt / kosher salt","1/2 tsp curry powder (Note 3)"],"purpose":"Chicken:"},{"ingredients":["2 tbsp plain oil (canola, veg, peanut)","2 eggs (, whisked)","100g/3 oz streaky bacon (, chopped into small pieces)","1/2 brown onion (, finely sliced)","3 garlic cloves (, finely minced)","1 red capsicum ((bell pepper), deseeded and finely sliced)","1 very heaped cup bean sprouts (or more leafy greens)","1 very heaped cup baby spinach (or other cook-able leafy greens or more bean sprouts)"],"purpose":"Stir fry add-ins:"}]', '[{"title":"Sauce","description":"Mix the sauce in a small bowl or jug.","images":[],"step":1},{"title":"Season chicken","description":"Toss the seasoned chicken ingredients in a bowl.","images":[],"step":2},{"description":"Prepare noodles per the packet directions then drain in a colander (usually says to soak in boiled water for 3 - 5 minutes).","duration":4,"images":[],"step":3},{"title":"Egg ribbons","description":"Heat a small amount of the oil in a large non stick pan over medium high heat. Pour the egg in a swirl to make a thin omelette. Once the surface is set (literally 30 seconds), slide or flip it onto a cutting board. Cool so you can handle it, roll it up into a cigar then cut into 7mm / 1/3\" strips. Separate. Voila! Egg ribbons!","images":[],"step":4},{"title":"Stir-fry","description":"Heat the remaining oil in the same pan over high heat. Add the bacon and cook for 1 minute. Add the onion and cook until it starts to wilt and the bacon is light golden (about 2 minutes). Add the chicken and cook until the surface is seared. Then add the garlic and capsicum and cook for another 2 minutes until the chicken is cooked.","duration":1,"images":[],"step":5},{"title":"Noodles","description":"Add (in this order) the baby spinach, bean sprouts, noodles then sauce. Using 2 spatulas, toss well for 1 1/2 minutes or until the sauce stains the noodles. There will be noodle breakage - that''s normal.","images":[],"step":6},{"title":"Finish","description":"Toss through the egg ribbons (gently, just to disperse) then serve immediately!","images":[],"step":7}]', '["egg","gluten","peanuts","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_716a59c2271e', 'en', 'US', 'Thai Turmeric Chicken (Gai Yang Khamin)', 'Recipe video. This is based on a popular southern Thailand street food that''s typically made with a butterflied chicken grilled over smokey coals. It''s sweet but has complexity owing to the simple but clever marinade.Here, I''m making a home version using the marinade for bone-in chicken thighs instead and baked it in my boring oven. I miss the charcoal flavour but it''s still lip smackingly delicious! The tumeric powder really makes it. :)', 'https://www.recipetineats.com/tachyon/2015/11/Thai-Turmeric-Chicken_4.jpg', 10, 50, 230, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.008, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 3.0, "unit": "bottle of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_turmeric", "quantity": {"value": 0.037, "unit": "jar"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["5 large chicken thighs, skin-on, bone-in (~1.2kg/2.4lb) (Note 1)"]},{"ingredients":["4 garlic cloves (, finely minced or crushed using garlic press)","2 tbsp fish sauce","2 1/2 tbsp oyster sauce","1 tsp white pepper (, ground (sub black))","1 tbsp ground turmeric","1/4 cup brown sugar (tightly packed cup)"],"purpose":"Marinade"}]', '[{"title":"Marinade chicken","description":"Mix Marinade ingredients in a large bowl. Add chicken and toss to coat. Marinade for at least 3 hours, preferably overnight.","images":[],"step":1},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced).","images":[],"step":2},{"title":"Prepare","description":"Line a tray with baking paper/parchment paper. Place chicken on the tray, skin side up. Scrape all Marinade out of th bowl and dab onto chicken.","images":[],"step":3},{"description":"Bake for 40 minutes, basting at the 30 minute and 40 minute mark using the tray juices to make it golden brown and sticky, and rotate the tray as needed for even colour.","duration":40,"images":[],"step":4},{"description":"Increase the oven temperature to 200°C/390°F (180°C fan-forced). Pop the chicken back in for a final 10 minutes to caramelise the skin.","images":[],"step":5},{"description":"Rest for 3 minutes before serving with jasmine or coconut rice, and plain chunks of tomato and cucumber the Thai way!","duration":3,"images":[],"step":6}]', '["fish","gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","australia-day","chicken-breast-recipes","chicken-recipes","cuisines","dietary","gluten-free-recipes","grilling-ideas-and-recipes","quick-and-easy","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9cb8b7f4cf19', 'en', 'US', 'Spicy Wontons - Din Tai Fung!', 'Recipe video above. Everybody knows Din Tai Fung* has the best Spicy Wontons. Here''s my copy-cat! Very specific mix of spices, it''s less spicy, less vinegary and more savoury than typical Chinese dumpling houses, designed so you can slop up every bit of that tasty sauce with the wontons without blowing your head off! So, so, very good!* Global dumpling restaurant chain that declares itself the world''s best dumplings. Many Sydney-siders would not disagree.', 'https://www.recipetineats.com/tachyon/2023/09/Spicy-wontons-din-tai-fung_7-2.jpg', 10, 5, 15, 12, '[{"id": "ing_wontons", "quantity": {"value": 11.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 0.06, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 3.0, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}]', '[{"ingredients":["1/2 tsp Chinese chicken stock powder (, or regular western stock powder (Note 5))","1 tbsp green onion (, sliced then roughly chopped, for garnish)","Extra chilli oil (, for drizzling (Note 5))"],"purpose":"Wontons:"},{"ingredients":["2 garlic cloves (, very finely minced)","1 tsp caster / superfine sugar (sub regular sugar)","1/2 tsp red chilli flakes (red pepper flakes), OPTIONAL, for spicy food lovers (Note 2)","1/4 tsp sichuan pepper powder (Note 3)","1/4 tsp Chinese five spice powder (Note 4)","1/2 tsp Chinese chicken stock powder (, or regular western stock powder (Note 5))","2 tbsp Chinese chilli oil (⚠️ Note 5), adj for spiciness (sub with sesame oil)","1 tbsp vegetable oil (sub canola, peanut or other natural oil)","2 1/2 tsp light soy sauce (, or all-purpose soy (Note 6))","1 tsp rice vinegar (sub other clean vinegar)","2 1/2 tbsp hot water (just tap is fine)"],"purpose":"Chilli oil sauce for wontons:"}]', '[{"description":"Chilli oil sauce for wontons:","images":[],"step":1},{"title":"Mix spices","description":"Put the garlic, sugar, chilli flakes, sichuan pepper, five spices and stock powder in a medium mixing bowl.","images":[],"step":2},{"title":"Heat oil","description":"Heat the chilli oil and vegetable oil in a small frying pan over medium heat until hot. Pour over garlic mixture. Enjoy the sizzle! (Don''t worry, it doesn''t spit)","images":[],"step":3},{"title":"Add sauces:","description":"Whisk in soy sauce, rice vinegar and hot water. The oil will remain a little separated on top. Set aside while you make wontons.","images":[],"step":4},{"title":"Cook wontons","description":"Bring a large saucepan of water to the boil. Add wontons and cook until they float: 4 minutes for freshly made, 6 to 8 minutes from frozen.","images":[],"step":5},{"title":"Assemble","description":"Transfer to serving dish using a slotted spoon. Pour over sauce, add an extra drizzle of chilli oil (if you dare!), sprinkle with green onion. Serve immediately!","images":[],"step":6}]', '["gluten","peanuts","sesame","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","iconic-dishes","modern-asian"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8bf5422252bf', 'en', 'US', 'Vietnamese Caramel Ginger Chicken', 'Recipe video above. Vietnamese caramel sauce is a popular sweet/savoury used in Vietnamese dishes. Here, it''s used for bite size chicken pieces that get coated in the glaze with a generous dose of ginger. It''s quick, easy, something different and outrageously good!** NOTE: Sadly seeing reader feedback that the liquid isn''t reducing and chicken isn''t caramelising. Please ensure to use a LARGE PAN and be brave, simmer RAPIDLY! Else the liquid will take ages to reduce. See Note 4.**', 'https://www.recipetineats.com/tachyon/2023/08/Vietnamese-Ginger-Caramel-Chicken_6-close-up.jpg', 7, 15, 22, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 kg / 2 lb skinless chicken thigh fillets (, cut into large 5cm/2\" pieces (Note 1))","3 tbsp fish sauce","1 bird’s eye chilli or Thai chilli (, deseeded, finely minced (optional) - Note 2)","3 tbsp vegetable oil","1/4 cup brown sugar (, tightly packed)","1/3 cup ginger (, finely julienned (about 5 cm/2\" thick piece))","2 eschallots (, halved then finely sliced (sub half red onion) (Note 3))","1/2 cup boiling water"]},{"ingredients":["Fresh coriander/cilantro or green onion slices (recommended)","Red chilli (, finely sliced (optional))","Jasmine rice"],"purpose":"Garnishes & serving:"}]', '[{"description":"Toss chicken with fish sauce and chilli, then set aside while you prepare the other ingredients. You could marinate even overnight but it''s not necessary.","images":[],"step":1},{"title":"Pan size","description":"Use a large non-stick pan (mine is 30cm/12\", must be large). Else, be prepared to remove chicken at end to speed up sauce reduction. See Note 4!","images":[],"step":2},{"title":"Caramel","description":"Mix oil and sugar in the cold pan, then turn onto medium high heat. As soon as the sugar is melted, remove the pan from the stove then carefully add the chicken (⚠️ it will sizzle so don''t throw it in!) . Add ginger and shallots, toss briefly. The caramel may harden, that''s ok, it will re-melt.","images":[],"step":3},{"title":"Cook outside of chicken","description":"Then put the pan back on the stove and stir just until the chicken changes from pink to white all over, but not browned, and definitely not cooked through.","images":[],"step":4},{"title":"Simmer 10 min","description":"Add water, stir, bring to a simmer. Simmer very rapidly, still on medium high (or even high!), for 10 to 12 minutes, until the liquid reduces right down to a glaze. It might take longer if your pan is smaller or your stove is weaker, that''s ok. Stir every now and then while watery, then once it''s reduced down to a glaze, toss regularly to get nice colour on the chicken. The further you take it, the better the colour!","duration":11,"images":[],"step":5},{"description":"Serve with jasmine rice or other plain rice garnished with extra slices of chilli and fresh coriander if desired. Smashed cucumbers or Asian Slaw would be a terrific side!","images":[],"step":6}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","chicken","chicken-recipes","mains","modern-asian","quick-and-easy","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_28bfac61179b', 'en', 'US', 'Thai Coconut Pumpkin Soup', 'Recipe video above. This is a brilliant way to turn a classic pumpkin soup into something that tastes more exotic - with very little effort. Think - pumpkin soup with Thai Red Curry vibes. It''s so good!See separate tutorial for how I cut butternut pumpkin and the Pumpkin Soup recipe for how I cut pumpkin.', 'https://www.recipetineats.com/tachyon/2023/08/Thai-Coconut-Pumpkin-Soup_2.jpg', 10, 15, 25, 5, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_thai_red_curry_paste", "quantity": {"value": 0.18, "unit": "bottle"}}, {"id": "ing_pumpkin", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_roti_frozen_pan_fried_for_dunking_note_6", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["2 tbsp vegetable oil (or other oil)","1 brown onion (, diced)","2 garlic cloves (, finely minced)","3 tbsp Thai red curry paste (, Maesri recommended (Note 1))","1.8kg/ 3.6 lb pumpkin or butternut squash ( - peeled, deseeded then chopped into 3cm / 1.2\" chunks (~1.3 kg/2.6 lb) (Note 2))","2 1/2 cups vegetable stock (, salt reduced (or chicken stock))","400ml/ 14 oz (1 can) coconut milk, (full fat, best quality (Note 3))","1 tbsp fish sauce (sub light or regular soy sauce, Note 4)"]},{"ingredients":["Crispy Asian shallots (, highly recommended (Note 5))","Red cayenne pepper (, finely sliced)","Fresh coriander leaves","Roti ((the flaky kind), frozen, pan fried - for dunking (SO GOOD!) - Note 6)"],"purpose":"Garnishes (optional):"}]', '[{"title":"Sauté","description":"Heat oil in a large heavy based pot over medium high heat. Add onion and garlic, cook for 2 minutes until soft.","duration":2,"images":[],"step":1},{"description":"Add curry paste and cook for 2 minutes.","duration":2,"images":[],"step":2},{"description":"Add pumpkin and stir to coat in the flavours for around 2 minutes.","images":[],"step":3},{"title":"Simmer 8 minutes","description":"Set aside 1/4 cup coconut milk for garnish. Add stock, remaining coconut milk and fish sauce. Bring to simmer then reduce heat to medium and simmer for 8 minutes until the pumpkin is soft.","duration":8,"images":[],"step":4},{"description":"Blitz using stick blender until smooth.","images":[],"step":5},{"description":"Serve topped with garnishes. Dunk in roti. Enjoy!","images":[],"step":6}]', '["fish","gluten","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Thai"],"categories":["asian-recipes","asian-soups","cuisines","pumpkin","quick-and-easy","soup-recipes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e2dad4918e12', 'en', 'US', 'Japchae - Korean Noodles', 'Recipe video above. Sort of a stir fry, sort of a noodle salad, this big, colourful Korean noodle dish is tossed together in a bowl rather than on the stove and served barely warm. Made with chewy, slippery sweet potato noodles (dangmyeon) which are available in large grocery stores, though can be substitute with glass noodles (bean thread noodles) or vermicelli noodles in a pinch.Makes a big batch - leftovers make for a terrific lunch!', 'https://www.recipetineats.com/tachyon/2023/07/Japchae-Korean-noodles_9.jpg', 20, 15, 35, 5, '[{"id": "ing_beef_steak", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.02, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sweet_potato", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_shiitake_mushrooms", "quantity": {"value": 1.333, "unit": "pack of 150g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 5.0, "unit": "bag of 250g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.06, "unit": "pack of 100g"}}]', '[{"ingredients":["600g/1.2lb bone-in beef short ribs *RECOMMENDED* (300g/10oz boneless)","300g/10 oz boneless beef short ribs *RECOMMENDED*","300g/10oz scotch fillet / boneless rib eye (or other steak, recommend tenderising (Note 1))"],"purpose":"Choose beef option (Note 1):"},{"ingredients":["2 tsp soy sauce (, all-purpose or light soy (Note 2))","2 tsp white sugar","2 tsp finely minced garlic","1/2 tsp black pepper"],"purpose":"Beef marinade:"},{"ingredients":["1/4 cup soy sauce (, all-purpose or light soy (Note 2))","2 tsp white sugar","1/2 tsp finely minced garlic","1 1/2 tbsp sesame oil","1/2 tsp cooking/kosher salt","1/2 tsp black pepper"],"purpose":"Noodle dressing:"},{"ingredients":["250g/ 8oz sweet potato noodles (dangmyeon), dried (Note 3)","4 tbsp vegetable oil (or other plain oil)","1 tsp cooking/kosher salt (, divided)","1 onion (, peeled, halved, sliced into 6mm/1/4\" wedges)","3 green onion stems (, cut into 5cm / 2\" lengths, white & green parts separated)","200g/7oz fresh shiitake mushrooms (, stem removed, cut into 5mm/1/5\" slices (Note 4))","2 carrots (, peeled, cut into 3mm / 1/8\" batons)","1 red capsicum/bell pepper (, cut into 0.5cm / 1/5\" slices)","4 1/2 cups (tightly packed) baby spinach","2 tbsp white sesame seeds"],"purpose":"Noodles & vegetables:"}]', '[{"description":"Quick beef marinade:","images":[],"step":1},{"description":"Cut beef into strips that are ~ 5mm thick, 1cm wide and about 5cm long (1/5\" x 2/5\" x 2\"). If using shortribs, trim excess fat, cut the meat off the bone. Then cut each piece in half lengthwise (to form 2 \"steaks\") then slice into 5mm thick. (See step photos in post or video at 0.11s, Note 6)","images":[],"step":2},{"title":"Marinate","description":"Put beef in a bowl. Add marinade ingredients, then mix. Set aside marinate while you proceed with recipe, ~15 - 20 minutes is all it needs. (Note 5)","images":[],"step":3},{"description":"Sauce and noodles:","images":[],"step":4},{"title":"Sauce","description":"Mix the Sauce ingredients in a very large mixing bowl.","images":[],"step":5},{"title":"Noodles","description":"Cook sweet potato noodles per packet directions (normally 8 min in boiling water). Drain, briefly rinse under tap water then shake off excess water well. Add noodles into the bowl with the dressing. DO NOT MIX.","images":[],"step":6},{"title":"Batch 1","description":"Heat 2 tablespoons of oil in a large non-stick pan (30cm/12\") over high heat. Cook the brown onion, white part of green onion and shiitake mushrooms with 1/2 tsp salt for 2 1/2 to 3 minutes, stirring constantly, just until starting to soften but not going golden. Pour on top of the noodles - don''t mix yet!","images":[],"step":7},{"title":"Batch 2","description":"Using the same pan still on high heat, heat 1 tbsp oil then cook the carrot and capsicum for 1 1/2 minutes, constantly stirring. Add spinach, green onion and the final 1/2 tsp salt. Keep cooking for 1 1/2 minutes until the spinach is wilted. Transfer into the noodle bowl - still don''t mix!","images":[],"step":8},{"title":"Cook beef","description":"In the same pan, heat the final 1 tbsp of oil still on high heat. Add beef and cook for 1 1/2 minutes until very lightly golden and just cooked through. Add to the noodle bowl. Don''t mix!","images":[],"step":9},{"description":"Mix! Add most of the sesame seeds (reserve some for topping). NOW you can mix! Toss, toss, toss.","images":[],"step":10},{"title":"Serve","description":"Transfer into a serving bowl, sprinkle with remaining sesame seeds. This is meant to be eaten warm, not piping hot. Eat!","images":[],"step":11}]', '["fish","gluten","sesame","soy"]', '[]', '{"mealType":["lunch","dinner"],"cuisine":["Korean"],"categories":["asian-recipes","korean-recipes","noodles","quick-and-easy","summer"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6e6cc9cb5cdb', 'en', 'US', 'Sizzling ginger steamed fish', 'Recipe video above. Named as such because the ginger and green onion topping sizzles dramatically when you pour hot oil over oven steamed fish! An incredibly simple way to make a healthy steamed fish recipe a whole lot more exciting with fresh Asian flavours.Squidge every bite of fish very well in the sauce before eating. The sauce is really tasty - it will surprise you.', 'https://www.recipetineats.com/tachyon/2023/07/Sizzling-ginger-fish_1.jpg', 5, 15, 20, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cooking_sake", "quantity": {"value": 0.02, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}]', '[{"ingredients":["2 x 180g/ 6 oz thinnish white fish fillet (, skinless (~1.5 cm/ 2/3\" thick) (Note 1))","1 tsp cooking sake (sub mirin, Chinese cooking wine, dry sherry) (Note 2)","Small pinch salt","Small pinch white pepper (sub black)"]},{"ingredients":["1/2 cup green onion (, green part only, finely sliced on diagonal (Note 3))","2 tbsp ginger (, finely julienned (Note 3))","1 tbsp large red chilli (, deseeded finely julienned on diagonal, optional (Note 4))"],"purpose":"TOPPING (divide between 2 fish):"},{"ingredients":["2 tsp light soy sauce (, or all-purpose soy (Note 5))","2 tsp sesame oil (, toasted)","2 tbsp peanut oil (or veg, canola, grapeseed)"],"purpose":"SAUCE (divide between 2 fish):"}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan).","images":[],"step":1},{"title":"Prepare parcel","description":"Place a 2 x 25cm / 10\" piece of foil on a work surface. Top with a piece of parchment/baking paper slightly smaller. Place fish on paper.","images":[],"step":2},{"title":"Season fish & wrap","description":"Sprinkle each side of the fish with a SMALL pinch of salt and pepper. Drizzle the top of each fish with 1/2 tsp sake. Form a parcel - make a parcel with the paper first, then the foil. (See video or step photos).","images":[],"step":3},{"title":"Bake","description":"Place parcels on a tray. Bake for 12 minutes or until the internal temperature is 55°C/130°F (I pierce thermometer through foil) or the fish flesh flakes (open to check). Thin fish cooks fast when enclosed!","duration":12,"images":[],"step":4},{"title":"Rest 3 min","description":"Put each parcel on a plate and unwrap, folding down the sides to create a “boat” that will catch the sauce that you can squidge the fish in. Rest for 3 minutes - heat the oil while it rests.","duration":3,"images":[],"step":5},{"description":"Heat oil until hot in a tiny saucepan or small pan over medium heat.","images":[],"step":6},{"description":"Sizzle! Top the fish with green onion, ginger and chilli. Drizzle with soy and sesame oil. Pour oil all over the green onion and ginger - it will sizzle dramatically!","images":[],"step":7},{"description":"Serve immediately. Eat fish out of foil, squidging the flaky pieces well in the sauce before eating. See post for what I served it with!","images":[],"step":8}]', '["fish","gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","dietary","fish-recipes","low-calorie-recipes","mains","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1ad6752ed673', 'en', 'US', 'Beef Chow Mein - great beef mince noodle recipe!', 'Recipe video above. The beef mince version of everybody''s favourite Chicken Chow Mein - great way to cook up ground beef with noodles. Economical and no meat chopping required, with plenty of hidden vegetables so it''s a complete dinner! Scrambling up an egg with the beef is a neat trick to make the beef cling to the noodles better.', 'https://www.recipetineats.com/tachyon/2023/07/Beef-chow-mein_5.jpg', 15, 10, 25, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_cabbage", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 2.0, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cornstarch", "quantity": {"value": 2.0, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}]', '[{"ingredients":["200g/ 7 oz chow mein noodles (, or other thin yellow egg noodles or 3 ramen cakes (Note 1))","1 1/2 tbsp canola oil","2 garlic cloves (, finely minced)","200g/ 7 oz beef mince / ground beef (any fat %)","3 green onion stems (, cut into 5cm/2\" lengths, white and green parts separated)","1 egg","2 cups green cabbage (, finely sliced (or Chinese cabbage))","1 carrot (, peeled, cut into thin batons)","1 heaped cups bean sprouts (~ 75g / 2 1/2 oz) (Note 5 - storage tip)"],"purpose":"Chow Mein:"},{"ingredients":["1 1/2 tbsp light soy sauce (or all-purpose soy sauce (Note 2))","1 1/2 tsp dark soy sauce (Note 2)","1 1/2 tbsp oyster sauce (Note 3)","1 1/2 tbsp Chinese cooking wine (Shaoxing) (Note 4)","1 1/2 tsp white sugar","Pinch white pepper"],"purpose":"Chow Mein Sauce:"},{"ingredients":["1 1/2 tsp cornflour / cornstarch","3 tbsp water"],"purpose":"Sauce thickener:"}]', '[{"title":"Sauce","description":"Mix ingredients in a small bowl then set aside. Some is used to flavour the beef, then the rest for the noodles.","images":[],"step":1},{"title":"Sauce thickener (cornflour slurry)","description":"Mix the cornflour / cornstarch and water in a separate small bowl.","images":[],"step":2},{"description":"Prepare noodles per packet directions then drain.","images":[],"step":3},{"title":"Cook beef","description":"Heat the oil in a large non-stick pan over high heat. Cook garlic for 10 seconds, then add the beef and cook until you can no longer see pink. Add 1 1/2 tablespoons of the Sauce and the white part of the green onions. Cook for another 2 minutes to get the beef nicely caramelised.","duration":0.16666666666666666,"images":[],"step":4},{"title":"Finish sauce","description":"Mix the cornflour slurry into the remaining sauce.","images":[],"step":5},{"title":"Egg","description":"Add the egg into the pan then mix it through the beef, it will sort of scramble. Egg makes the beef stick to the noodles better!","images":[],"step":6},{"title":"Cabbage & carrot","description":"When the egg is mostly cooked, add the carrot and cabbage. Cook for 1 minute until cabbage starts to wilt.","duration":1,"images":[],"step":7},{"title":"Sauce & noodles","description":"Give the sauce a quick mix. Add the bean sprouts, noodles and sauce into the pan. Toss well for 1 minute or until sauce is dispersed through the noodles. Add green part of green onions. Toss for another 1 minute.","duration":1,"images":[],"step":8},{"title":"Serve","description":"Divide between bowls and serve!","images":[],"step":9}]', '["egg","gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","beef-mince-recipes","beef-recipes","chinese-recipes","dinner-tonight","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f783d2e8882d', 'en', 'US', 'Chili crisp noodles', 'Recipe video. Ridiculously good and ridiculously fast, here by popular demand after a sneak peek on Instagram! Chili crisp oil is the star ingredient here, adds spiciness, awesome crunch, savouriness, and a touch of sweet. Widely available these days - see Note 6.Tastes like Spicy Sichuan Dan Dan Noodles - but much faster to make. LOTS OF SUB OPTIONS because chili crisp carries so much of the flavour weight here!', 'https://www.recipetineats.com/tachyon/2023/06/Chili-crisp-noodles_2.jpg', 7, 0, 7, 2, '[{"id": "ing_sesame_seeds", "quantity": {"value": 0.06, "unit": "pack of 100g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.03, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_ramen_noodles", "quantity": {"value": 0.28, "unit": "pack of 4"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}]', '[{"ingredients":["2 tbsp Chinese sesame paste (Note 1 subs)","2 tbsp light soy sauce (Note 2)","1 tbsp rice vinegar (Note 3)","1 tsp white sugar (or other sugar, or honey, maple)","2 tsp sesame oil (, toasted (Note 4))","1/8 tsp+ cooking / kosher salt (Note 5)","2 heaped tbsp chilli crisp (get oil + chili bits)","1 tbsp ginger (, finely minced*)","1 tbsp garlic (, finely minced*)","1 green onion stem (, finely sliced (or 1/4 red onion finely sliced))","1/3 cup coriander/cilantro (, roughly chopped*)"]},{"ingredients":["140g/ 5oz (2 cakes) instant noodles / ramen noodles","250g/8oz fresh noodles (like hokkien, lo mein)"],"purpose":"Noodle options (Note 7):"}]', '[{"title":"CHECK the spiciness of your chilli crisp","description":"taste it!! Laoganma is not actually that spicy (most store bought brands I''ve used are similar) and the quantity used is based on that brand. If yours is very spicy, start with less and add more later.","images":[],"step":1},{"title":"Base sauce","description":"Mix the sesame oil, vinegar, soy, sugar, salt and sesame paste in a bowl. Top with green onion (don’t mix in).","images":[],"step":2},{"title":"Sizzling chili crisp","description":"Heat chilli crisp and oil in a small pan over medium heat. Add ginger and garlic, stir 30 seconds until golden and it smells amazing. Pour over green onion - enjoy the sizzle! Then mix.","images":[],"step":3},{"title":"Toss","description":"Cook noodles per packet directions. Drag the noodles straight from the saucepan into the bowl (extra water loosens the sauce). Toss. Use cooking water to loosen more if needed. Toss through coriander/cilantro.","images":[],"step":4},{"title":"Adjust & finish","description":"Taste. Add more salt if needed and more chilli crisp if desired (not all chilli crisp is the same saltiness / spiciness). Eat!","images":[],"step":5}]', '["gluten","sesame","soy"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","chinese-recipes","modern-asian","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_709a5f652dd3', 'en', 'US', 'Xinjiang Cumin Lamb Stir Fry', 'Recipe video above. A cumin spiced lamb dish might sound totally un-Chinese, but it''s actually authentic and very on-trend! Hailing from the Xinjiang province of China, if you love Middle Eastern and Chinese food, you will love this. Bold cumin flavour with tingling "cold" spiciness from Sichuan pepper and earthy chilli flavour (but not spiciness) from the dried chillis.Spice level - On the upper warm buzz side, but not fiery heat because Sichuan pepper is a different type of spiciness, see note 4.Recipe credit: Adapted from Real-Deal Xinjiang Cumin Lamb from Omnivore''s Cookbook, one of my trusted sources for authentic Chinese cooking. I made a few minor tweaks to streamline but the flavour is bang on!', 'https://www.recipetineats.com/tachyon/2023/05/Xinjiang-Cumin-Lamb-Stir-Fry_3.jpg', 15, 8, 53, 4, '[{"id": "ing_lamb", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.01, "unit": "tub of 200g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.075, "unit": "pack of 400g"}}, {"id": "ing_cumin", "quantity": {"value": 0.075, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["500g/ 1 lb boneless lamb leg meat (or rump) (, sliced 1/2 cm / 1/5\" thick (Note 1))","1 tbsp soy sauce (, light or all-purpose (not dark or sweet))","1 tbsp Chinese cooking wine (Note 2)","1/2 tsp cooking/kosher salt","1 1/4 tsp baking soda (, sifted if lumpy (Note 3))","2 tbsp cornflour / cornstarch"],"purpose":"Lamb & marinade:"},{"ingredients":["2 tbsp cumin powder","1/2 tsp white sugar","1/2 tsp ground Sichuan pepper (Note 4 to grind your own)"],"purpose":"Spice mix:"},{"ingredients":["4 tbsp vegetable oil (or canola, peanut)","1/2 cup dried Chinese chillis (, whole, 25-30 pcs (Note 5))","1 onion (, halved then sliced 8mm / 1/4\" thick)","2 tbsp finely minced ginger (~5cm/2\" piece)","5 cloves garlic (, finely sliced)","1/2 cup coriander/cilantro (, roughly chopped)","1 tsp toasted sesame seeds","Plain rice (, fried rice - more suggestions listed in post)"],"purpose":"Stir fry:"}]', '[{"title":"Marinade","description":"Combine lamb, soy sauce, Chinese cooking wine, salt, baking soda and cornflour in a mixing bowl. Mix well then set aside for marinade for 30 minutes (counter fine).","duration":30,"images":[],"step":1},{"title":"Spice mix","description":"Mix the ingredients in a small bowl.","images":[],"step":2},{"title":"Cook lamb","description":"Heat 3 tablespoons of the oil in a large non-stick skillet (30cm/1\") over medium-high heat until hot. Add half the lamb and spread out in a single layer. Leave for 30 seconds then, using 2 wooden spoons, toss for a further 1 minute until the lamb is slightly golden. Remove onto a plate then repeat with remaining lamb (you shouldn''t need more oil).","duration":0.5,"images":[],"step":3},{"title":"Sauté aromatics","description":"Heat the remaining 1 tablespoon of oil. Add the dried chilli, ginger and garlic. Stir for 10 seconds to release flavour, then add the onion. Cook for 2 minutes until the onion just starts to soften.","duration":0.16666666666666666,"images":[],"step":4},{"title":"Spiced lamb","description":"Add the cooked lamb then sprinkle the spice mix over. Toss well to evenly coat.","images":[],"step":5},{"title":"Finish dish","description":"Add the cilantro, sesame seeds and toss. Serve over rice! (Note: the dried chillies are not meant to be eaten.)","images":[],"step":6}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","chinese-recipes","lamb","lamb-recipes","mains","modern-asian","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8e8c2f23ee7c', 'en', 'US', 'Spicy Korean Noodle Soup (quick & healthy)', 'Recipe video above. For all those times you need a spicy Asian noodle fix - FAST! This packs a serious flavour punch. The secret is the juices from the kimchi jar and a good dollop of gochujang, that magical spicy Korean paste you can get "everywhere" these days. To add protein, cook raw prawns/shrimp or fish pieces in the broth (only takes 3 min), or top with slices of BBQ pork. You can also poach chicken in the broth using this foolproof method.', 'https://www.recipetineats.com/tachyon/2023/05/Spicy-Korean-noodle-soup_4.jpg', 5, 15, 20, 2, '[{"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cabbage", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_kimchi_juice", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_gochujang", "quantity": {"value": 0.18, "unit": "bottle"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_ginger", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_stems_choi_sum", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 cups / 1 litre chicken stock/broth (, low-sodium)","2/3 cup cabbage kimchi (Note 1)","2 tbsp kimchi juice (, from kimchi tub (Note 1))","3 tbsp gochujang (Note 2)","2 tbsp light soy sauce (Note 3)","2 tsp fish sauce (sub more soy)","1 tbsp Chinese cooking wine (Shaoxing wine, Note 4)","2 slices ginger (, sliced 0.7cm / 1/3\" thick (skin on))","1 large garlic clove (, smashed (Note 5))"],"purpose":"Spicy Korean Soup Broth"},{"ingredients":["200g/ 7oz thin fresh egg noodles (or 100g/3.5oz dried - Note 6)","4 stems choi sum (or other Asian greens, cut into 7cm / 2.5\" lengths, stems separated from leafy part)","1 small carrot (, peeled, cut into thin matchsticks)","2 1/2 tsp sesame oil (, toasted (Note 8))","1/4 cup finely sliced green onions (1 stem)"],"purpose":"Add-Ins (Note 7):"}]', '[{"title":"Broth","description":"Place all broth ingredients in a saucepan. Bring to a simmer over medium-high heat, then reduce heat so it’s simmering gently. Simmer 10 minutes without a lid.","images":[],"step":1},{"title":"Cook vegetables","description":"Add choi sum stems and carrot to the broth. Simmer for 2 minutes. Add choi sum leaves and simmer for another minute. Stir in sesame oil just before serving.","duration":2,"images":[],"step":2},{"title":"Noodles","description":"Meanwhile, cook egg noodles in boiling water per packet directions. Drain, give the noodles a quick rinse under tap water. Shake off excess water well.","images":[],"step":3},{"title":"Assemble","description":"Divide noodles between bowls. Top with the vegetables. Pick the garlic and ginger out of the broth, then broth pour over the noodles. Sprinkle with green onions and serve!","images":[],"step":4}]', '["egg","fish","gluten","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Korean"],"categories":["asian-recipes","asian-soups","korean-recipes","noodles","quick-and-easy","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_34918cac7840', 'en', 'US', 'AMAZING vegetarian lettuce wraps', 'Recipe video. The meat-free version of Chinese san choy bow. You never knew vegetarian lettuce wraps could be so delicious. I never knew either, until I made these! Crumbled tofu lends the filling a meaty texture while vegetables add lovely texture, all smothered in a glossy, savoury sauce. Vegetarian food (and healthy, no less!) was never so delicious. And interesting. And easy. It''s AMAZING!Feel free to substitute the veg with other sauté-able vegetables of choice.', 'https://www.recipetineats.com/tachyon/2023/03/Vegetarian-lettuce-wraps_4.jpg', 15, 10, 25, 2, '[{"id": "ing_cornstarch", "quantity": {"value": 2.0, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tofu", "quantity": {"value": 0.833, "unit": "pack of 300g"}}, {"id": "ing_oil", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_green_beans", "quantity": {"value": 0.002, "unit": "pack"}}, {"id": "ing_mushroom", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 12.0, "unit": "head"}}, {"id": "ing_peanuts", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}]', '[{"ingredients":["1 1/4 tsp cornflour / cornstarch","3 tbsp water","1 1/2 tbsp light soy sauce (Note 1)","1 tsp dark soy sauce (Note 1)","1 1/2 tbsp oyster sauce (Note 2)","1 tsp sesame oil (, toasted)","1 tbsp Chinese cooking wine (or sub Mirin or dry sherry, Note 3)","1 tsp white sugar","1 tsp finely grated ginger (sub garlic)"],"purpose":"San choy bow sauce:"},{"ingredients":["250g/8oz extra firm tofu (Note 4)","1 tbsp oil","1 garlic (, finely minced)","1/2 onion (, finely diced)","1/2 cup carrot (, chopped into 5mm/ 0.2\" pieces)","1/2 cup green beans (, sliced into 5mm/0.2\" rounds)","1/2 cup mushroom (, chopped into 5mm/ 0.2\" pieces)"],"purpose":"Filling:"},{"ingredients":["12 lettuce leaves (+/- depending on lettuce size, Note 5)","Peanuts (, finely chopped (I like salted, but unsalted fine))","Green onion (, finely sliced)","Sriracha (, for drizzling (highly recommended))"],"purpose":"Wraps:"}]', '[{"title":"Sauce","description":"Mix cornflour/cornstarch with water until lump free. Add everything else, then mix.","images":[],"step":1},{"title":"Crumble tofu","description":"Drain tofu, then cut into 5mm/0.2\" slices. Use your fingers to crumble into a mince. Not too fine crumbs, can always break up more when cooking (just like cooking mince/ground meat!).","images":[],"step":2},{"title":"Filling","description":"Heat oil over high heat in a large non stick pan. Cook onion, garlic and carrot for 1 minute. Add green beans and mushrooms. Cook 2 minutes - green beans should still be firm.","duration":1,"images":[],"step":3},{"title":"Sauce it","description":"Add tofu and toss through. Pour in the sauce. Stir for 1 minute or until the sauce thickens and is coating the mixture nicely. (If it evaporates too quickly, add a splash of water)","duration":1,"images":[],"step":4},{"title":"Serving","description":"Transfer filling into a bowl. Lay out on the table with lettuce leaves, green onion, peanuts and bottle of sriracha.","images":[],"step":5},{"title":"DIY lettuce wraps","description":"Spoon filling into lettuce leaf. Drizzle with sriracha, sprinkle with peanuts and green onion. Bundle / fold, eat!","images":[],"step":6}]', '["gluten","sesame","soy"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dietary","low-calorie-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e906d00f3e36', 'en', 'US', 'Firecracker Beef', 'Recipe video above. This is a thrifty yet excellent dinner for all those times you need to scratch your Spicy Asian Food itch, fast! Seared beef mince gets tossed through a fiery Firecracker Sauce, tastes a bit like a spicy beef version of the much-loved Vietnamese Caramelised Pork Mince. Sweetness & spice level - Fairly spicy! See notes to reduce. Firecracker sauce is supposed to be a bit sweet to offset spice, also see notes.', 'https://www.recipetineats.com/tachyon/2022/11/Firecracker-beef-mince_2-2.jpg', 3, 10, 13, 4, '[{"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sriracha", "quantity": {"value": 0.15, "unit": "bottle of 400ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}]', '[{"ingredients":["1½ tbsp oil (vegetable, canola, peanut)","500g / 1 lb beef mince / ground beef (Note 1)","2 garlic cloves (, finely minced)","1 tsp chilli flakes / red pepper flakes (adjust to your taste)","3 tbsp water"]},{"ingredients":["2 tbsp soy sauce (, light or all-purpose (Note 2))","2 tbsp rice vinegar (Note 3)","4 tbsp sriracha sauce (Note 4)","4 tbsp brown sugar (tightly packed)"],"purpose":"Firecracker sauce:"},{"ingredients":["Rice, (soba or vermicelli noodles)","1 green onion (, finely sliced)","1 tsp sesame seeds","Diced cucumber, julienned carrot, finely sliced red radish","Extra sriracha sauce (, if you dare!)"],"purpose":"To serve (optional!):"}]', '[{"title":"Sauce","description":"Mix Firecracker sauce ingredients in a small bowl and set aside.","images":[],"step":1},{"title":"Cook beef","description":"Heat oil in a large frypan over high heat. Add beef and cook, breaking it up as you go, until you can no longer see raw meat (2½ minutes). Add garlic and chilli flakes and cook for 1 minute.","duration":1,"images":[],"step":2},{"title":"Caramelise beef","description":"Add Firecracker sauce ingredients, stir to coat the beef. Cook for 5 to 7 minutes, stirring only every minute or so initially, then more towards the end, until the sauce reduces and you can see the beef caramelising. Caramelise well for good flavour!","duration":6,"images":[],"step":3},{"title":"Water","description":"Add the water and cook for 1 minute (the water makes the beef saucier!)","duration":1,"images":[],"step":4},{"description":"Serve over rice, sprinkled with sesame seeds, green onion and a squirt of extra sriracha if you''re feeling brave! Add a pile of vegetables of choice on the side. Dive in!","images":[],"step":5}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef","beef-mince-recipes","beef-recipes","dinner-tonight","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b8e7f32b3af1', 'en', 'US', 'Vegetable Dumplings (Potstickers!)', 'Recipe video above. 4 years in the making, my favourite vegetable dumpling! These are a standout because you can actually taste the vegetables and it''s got good texture, rather than just being a wad of tasteless, watery mush which is sadly all too common.Don''t get too hung about about the wrapping part. If the pleating is too challenging, just seal it flat. Quicker, easier, and it tastes exactly the same. :)', 'https://www.recipetineats.com/tachyon/2022/09/Vegetable-Dumplings-1-on-plate.jpg', 45, 3, 48, 30, '[{"id": "ing_cabbage", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.04, "unit": "kg"}}, {"id": "ing_tofu", "quantity": {"value": 3.0, "unit": "pack of 300g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 2.0, "unit": "jar of 50g"}}, {"id": "ing_round_dumpling_wrappers", "quantity": {"value": 32.5, "unit": "unit"}}, {"id": "ing_oil", "quantity": {"value": 0.15, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}]', '[{"ingredients":["2 cups green cabbage (, finely chopped into 2mm pieces)","1/2 tsp cooking/kosher salt"],"purpose":"Wilted cabbage for Filling:"},{"ingredients":["8 dried shiitake mushroom (40 g total), medium size (Note 1)","3/4 cup firm tofu (, finely diced into 3-4mm / 1/8\" cubes (Note 2))","1/2 tsp garlic (, finely grated)","1 tsp ginger (, finely grated)","2 tbsp green onion (, finely sliced then minced)","2 tbsp finely grated floury potato (, including juices, for binding (Sebago, russet, Maris piper, Note 3))","1 1/2 tsp toasted sesame oil (Note 4)","1 tsp light soy sauce (or all-purpose, not dark soy)","1/4 tsp sugar (any)","1/4 tsp cooking/kosher salt","2 pinches white pepper (sub black)"],"purpose":"Filling:"},{"ingredients":["30 - 35 round dumpling wrappers (gow gee, Note 5)","2 - 3 tbsp canola oil","1/4 cup water per cooking batch"],"purpose":"Cooking:"}]', '[{"description":"Quick recipe (for pros):","images":[],"step":1},{"description":"Wilt cabbage 20 min, squeeze. Soak mushrooms 30 min, squeeze, finely chop. Mix with remaining Filling ingredients. Wrap. Pan fry 2 min, 1/4 cup water, pan-steam 5 min.","images":[],"step":2},{"title":"Full recipe","description":"filling:","images":[],"step":3},{"title":"Prepare cabbage","description":"Toss cabbage with 1/2 tsp salt in a bowl. Set aside for 20 minutes. Then grab handfuls and squeeze out excess water as best you can. Place squeezed cabbage in a bowl for mixing the filling in.","duration":20,"images":[],"step":4},{"title":"Shiitake mushrooms","description":"Soak mushrooms in 1 litre of boiling water for 30 minutes. Squeeze out excess liquid and finely chop into 2 mm pieces. Add to the filling bowl.","duration":30,"images":[],"step":5},{"title":"Potato","description":"Add grated potatoes to filling mix, including all the liquid that leached out when you grated it. We want all that starchy juice for its binding power!","images":[],"step":6},{"title":"Filling","description":"Add remaining ingredients into the filling bowl, mix to combine. It will look crumbly - don''t worry, everything sticks together better when steamed thanks to the potato.","images":[],"step":7},{"title":"Dumpling wrappers","description":"Take one wrapper from the packet. Keep unused wrappers covered so they don''t dry out.","images":[],"step":8},{"title":"Wrap dumplings","description":"(See video at 1m 30s!) Place a wrapper in your non-dominant hand. Dip your index finger in water and run it along the lower half of the wrapper (edge closest to you). Place 1 loosely-packed tablespoon of filling in the centre. Fold the wrapping over the filling, then seal with pleats. (If this is too hard, skip the pleats and seal flat).","images":[],"step":9},{"title":"Finished dumplings","description":"Stand dumpling upright with the pleats on top, and lightly press down to flatten the base. Shape gently into a slight curve. Place on a tray lightly dusted with cornflour/cornstarch. Repeat for remaining dumplings. Keep completed dumplings covered with a tea towel to prevent them from drying out. If you''re making ahead, cover dumplings with cling wrap and refrigerate. See storage notes.","images":[],"step":10},{"description":"Cook (pan-frying + steaming):","images":[],"step":11},{"title":"Cooking vessel","description":"Use a large non-stick pan with a lid (Note 6).","images":[],"step":12},{"title":"Pan fry","description":"Heat 1 tablespoon oil over medium high heat. Pan fry 12 to 15 dumplings for 2 minutes until the base is golden brown.","duration":2,"images":[],"step":13},{"title":"Steam","description":"Pour over 1/4 cup water over the dumplings in the skillet - it will steam and bubbly vigorously! Place the lid on and steam for 5 minutes or until the water in the pan has evaporated.","duration":5,"images":[],"step":14},{"description":"Cooked! Remove the lid. The water should have been driven off, and the wrapping should be semi-transparent (indicating it is cooked). The base should be crispy again. If not, leave the pan uncovered for a bit until the base crisps up again in the oil.","images":[],"step":15},{"title":"Serve","description":"Scoop the dumplings up with a spatula and place on a serving plate. Serve with soy sauce and chili paste for dipping, or rice vinegar mixed with soy sauce. Best served fresh - I get another batch cooking as we eat the freshly cooked ones!","images":[],"step":16},{"description":"Steaming-only option:","images":[],"step":17},{"description":"Using either a bamboo steamer set over a large wok with simmering water, or other larger steamer. Line with a fitted sheet of parchment paper with holes, and steam the dumplings for 8 minutes.","duration":8,"images":[],"step":18}]', '["gluten","sesame","soy"]', '["keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["snack","dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dumplings"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_787630138c29', 'en', 'US', 'Red Vietnamese Fried Rice', 'Recipe video above. This is the fried rice version of traditional Vietnamese red rice (plain tomato rice steamed in a pot). I added ham, peas and egg to turn it into a quick and easy meal. Frying up the tomato rice with garlic adds extra flavour which is on point!Serves 2 as a meal, or 4 to 5 as a side.', 'https://www.recipetineats.com/tachyon/2022/09/Red-Vietnamese-Fried-Rice_3.jpg', 8, 7, 15, 2, '[{"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_ham", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}]', '[{"ingredients":["30g / 2 tbsp unsalted butter","3 garlic cloves (, finely minced)","1/2 cup diced ham (I use pre-chopped, Note 1)","1 cup frozen peas","2 1/2 cups day-old cooked jasmine rice (Note 2)","2 tbsp tomato paste","2 tsp fish sauce (Note 3)","2 tsp soy sauce (all purpose or light, not dark soy, Note 4)","1/4 tsp white sugar","2 eggs (, whisked)"]}]', '[{"description":"Melt most of the butter in a large non-stick skillet over high heat (save a dab for scrambling eggs).","images":[],"step":1},{"description":"Add garlic, cook for 10 seconds.","duration":0.16666666666666666,"images":[],"step":2},{"description":"Add ham, stir for 30 seconds.","duration":0.5,"images":[],"step":3},{"description":"Add peas, stir for 30 seconds.","duration":0.5,"images":[],"step":4},{"title":"Rice and tomato paste","description":"Add rice and tomato paste, cook for 2 minutes.","duration":2,"images":[],"step":5},{"title":"Sauces","description":"Add fish sauce, soy and sugar, cook 1 minute to get a bit of nice caramelisation on the tomatoey rice.","images":[],"step":6},{"title":"Scramble eggs","description":"Push rice to one side of the pan. In the cleared space, melt reserved butter then pour in the egg and scramble until just set.","images":[],"step":7},{"title":"Serve","description":"Toss cooked egg through the rice. Serve!","images":[],"step":8}]', '["egg","fish","gluten","milk","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","fried-rice","modern-asian","quick-and-easy","rice-recipes","rice-side-dishes","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a9ca2a056a5d', 'en', 'US', 'Teriyaki Salmon Noodles', 'Recipe video above. Here''s a great quick noodle recipe that''s got everything you want for a meal. It''s got carbs, veg and protein. It''s quick. It''s one-pan. It''s easy. And it''s super tasty!! This is also a delicious dish that can wring two generous meal servings from just one piece of salmon. An economical tip! :)', 'https://www.recipetineats.com/tachyon/2022/07/Teriyaki-Salmon-Noodles_1-1.jpg', 5, 10, 15, 2, '[{"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_broccoli", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 3.0, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_cooking_sake", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp oil (veg or canola)","250 g / 8 oz salmon fillet (s), skinless, sliced into 2cm / 0.7\" strips (lengthwise, Note 1)","2 instant noodle / ramen noodle cakes (discard seasoning packs) (Note 2 other noodles)","1/2 onion (, cut into 1cm / 0.3\" slices)","1 garlic clove (, finely minced)","1 small bunch Chinese broccoli (gai lan), cut into 5 cm / 2\" lengths, leaves separated from stem (Note 3)"]},{"ingredients":["2 1/2 tbsp soy sauce (, light or all-purpose (Note 4))","2 tbsp mirin (Note 5)","2 tbsp cooking sake (Note 5)","1 tsp white sugar"],"purpose":"Teriyaki Sauce:"}]', '[{"title":"Teriyaki Sauce","description":"Mix the ingredients in a small bowl until the sugar is dissolved.","images":[],"step":1},{"description":"Coat salmon with 1 tablespoon of Teriyaki Sauce in a bowl, then set aside while you cook the noodles. (No need to marinate)","images":[],"step":2},{"description":"Cook your noodles per the packet directions. Drain, briefly rinse under tap water then set aside.","images":[],"step":3},{"title":"Cook salmon","description":"Heat 1/2 tablespoon oil in a large non-stick pan over high heat. Cook the salmon for 1 1/2 minutes on each side or until golden, then remove to a plate. Pour any remaining sauce in the skillet over the salmon.","images":[],"step":4},{"title":"Cook aromatics","description":"Roughly clean the pan with a paper towel then return to the stove, still on high heat. Heat 1 tablespoon of the remaining oil and cook the onion and garlic for 30 seconds. Add Chinese broccoli stems and cook for 1 minute.","duration":0.5,"images":[],"step":5},{"title":"Noodles & sauce","description":"Add noodles and half the Sauce. Toss for 2 minutes until the Sauce is absorbed. Add the remaining Sauce and toss to disperse. Then spread the noodles out in the pan, cook for 30 seconds un-disturbed. Repeat again 3 to 4 times (~3 min total) - a trick for nice caramelisation on the noodles (which = flavour!).","duration":2,"images":[],"step":6},{"title":"Leafy greens","description":"Drizzle the remaining 1/2 tablespoon oil around the side of the pan, then add the Chinese broccoli leaves. Toss for a further 1 1/2 minutes or until the leaves wilt.","images":[],"step":7},{"title":"Add back salmon","description":"Remove pan from stove. Place salmon on top, break into large chunks then toss through.","images":[],"step":8},{"title":"Serve","description":"Divide between bowls and serve immediately!","images":[],"step":9}]', '["fish","gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","noodles"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6d98a13ffa3b', 'en', 'US', 'Honey Prawns - stays crispy for ages!', 'Recipe video above. A recipe for old school Chinese restaurant style Honey Prawns! This recipe uses a proven method used in my Honey Chicken recipe for Honey Prawns that stays crispy hours even after coating in the sauce!1. Double coating - cornflour/cornstarch to seal in juices, followed by batter.2. Cold batter made with soda water = crispier coating that''s puffy and light, not dense and greasy.3. Cornflour/cornstarch + flour batter - cornflour for ultra crispiness, flour for golden colour.4. Double fry for extra long lasting, thicker crispiness AND less greasy (Asian secret!).5. No-soggy Sauce - glucose or corn syrup to make it "candy like" to stick on the prawn crust rather than soaking in, plus NO WATER in the sauce.Note - the sauce is sweet. That''s the way it''s supposed to be! But not as sickly sweet as many Chinese restaurants tend to be. Please do not try to change the sauce as it has been formulated to prevent making the batter soggy.', 'https://www.recipetineats.com/tachyon/2021/09/Honey-Prawns_23.jpg', 10, 20, 30, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 1.0, "unit": "pack of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.003, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.01, "unit": "tub of 200g"}}, {"id": "ing_oil", "quantity": {"value": 3.5, "unit": "bottle"}}, {"id": "ing_honey", "quantity": {"value": 0.002, "unit": "jar of 500g"}}, {"id": "ing_corn", "quantity": {"value": 0.056, "unit": "can of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.02, "unit": "bottle of 500ml"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.067, "unit": "pack of 375g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["300g/ 10oz prawns/shrimp (, peeled with tail on (600g/1.2lb whole unpeeled) (Note 1))","1/2 tsp kosher/cooking salt (halve for table salt)"],"purpose":"Prawns"},{"ingredients":["1/2 cup cornflour/cornstarch"],"purpose":"Dredging:"},{"ingredients":["9 tbsp cornflour/cornstarch (Note 2)","6 tbsp flour (, plain/all-purpose)","1/2 tsp baking powder (NOT baking soda)","1/2 tsp kosher/cooking salt (halve for table salt)","2/3 cup + 1 tbsp COLD soda water, club soda or seltzer water (NOT sparkling mineral water, Note 3)"],"purpose":"Ultra-crispy fry batter:"},{"ingredients":["3 - 4 cups vegetable or canola oil (~4cm / 1.5\" depth in a pot)"],"purpose":"Oil, for frying:"},{"ingredients":["1/3 cup (100g) honey","1.5 tbsp (25g) glucose OR corn syrup (light) (Note 4)","1 tbsp light soy sauce (or all-purpose)","2 tsp Chinese cooking wine (or mirin)"],"purpose":"Honey Sauce (Note 8 on sweetness):"},{"ingredients":["25g / 2 oz Vermicelli rice noodles (optional) (, a wad of it (not mung bean noodles, it must be rice noodles))","Sesame seeds, finely sliced green onions"],"purpose":"Garnish / serving:"}]', '[{"description":"Season and dust prawns:","images":[],"step":1},{"title":"Salt prawns","description":"Mix prawns with salt. (Don''t do this ahead, salt makes prawns sweat = compromise crispy coating!)","images":[],"step":2},{"title":"Dust","description":"Place 1/2 cup cornflour/cornstarch in a bowl. Dip prawn in, shake off excess then put on a plate. Repeat with all prawns.","images":[],"step":3},{"description":"Cold batter and fry #1:","images":[],"step":4},{"title":"Chill dry ingredients","description":"Whisk together flour, cornflour/cornstarch, baking powder and salt in a bowl. Place in fridge while oil heats up. (Helps keep batter cold, cold batter = crispier prawns)","images":[],"step":5},{"title":"Heat oil","description":"Fill small pot or large saucepan with 4cm / 1.7\" oil. Heat to 160°C/320°F on medium high stove.","images":[],"step":6},{"title":"Make cold batter","description":"When the oil is near target temp, add soda water into the dry ingredients. Then do the minimum whisks to just combine (10 or so) - a few lumps ok, better than whisking too much (changes coating texture).","images":[],"step":7},{"title":"Batter thickness","description":"Should fully coat prawns easily, not be see-through, but not thick and heavy. See video at 38 seconds for cues. Use extra soda water 1 teaspoon at a time to achieve right thickness.","images":[],"step":8},{"title":"Dredge","description":"Holding a prawn by the tail, dip into the batter then hold up for a 2 seconds to let the excess batter drip off. Then carefully place in oil. Repeat with another 5 prawns (6 per batch).","images":[],"step":9},{"title":"3 minutes Fry #1","description":"Cook for 3 minutes until light golden and crispy. When you pick them up, you can tell it''s very crispy.","duration":3,"images":[],"step":10},{"title":"Drain and repeat","description":"Place prawns on a tray with paper towels. Repeat with remaining prawns. I cook in 4 batches. Don''t crowd the pot as it brings oil temperature down too much.","images":[],"step":11},{"description":"Cool prawns for 20 minutes (Note 5). Meanwhile, make Sauce.","duration":20,"images":[],"step":12},{"title":"Simmer","description":"Place ingredients in a small saucepan over medium heat. Bring to simmer, turn down stove to medium low then leave to simmer for 3 minutes.","duration":3,"images":[],"step":13},{"title":"Syrupy consistency","description":"The consistency should be like maple syrup (see video). Turn off stove, place lid on to keep warm (when cool, it gets too thick to toss prawns in it).","images":[],"step":14},{"title":"Fry #2","description":"for ultra-crispy!","images":[],"step":15},{"description":"Heat oil to 200°C/390°F.","images":[],"step":16},{"title":"3 minutes Fry #2","description":"Place half the prawns in oil (you can crowd the pot for Fry #2). Cook for 3 minutes or until it changes from pale golden to very golden, then remove to a paper towel-lined plate. You can tell by touching that it''s built-to-last crispy! More golden = crispier (but don''t overcook the prawns!) Repeat with remaining prawns.","duration":3,"images":[],"step":17},{"description":"Sauce and serve:","images":[],"step":18},{"title":"Quickly toss","description":"Transfer prawns to a metal bowl then pour over Honey Sauce. Quickly toss with rubber spatula to coat prawns in sauce. (Sauce starts thickening if you take too long, so be quick!)","images":[],"step":19},{"title":"Garnish","description":"Pile prawns over crispy rice noodles (if using), scatter with sesame seeds, green onion and serve!","images":[],"step":20},{"description":"Puffy crispy rice noodles (optional):","images":[],"step":21},{"description":"At any point while oil is hot, drop a wad of noodles into hot oil, wait 3 seconds until it puffs up, then remove with tongs.","images":[],"step":22},{"description":"Drain on paper towels, place on plate. Top with prawns! (Note: Crispy noodles stays crispy \"forever\" so you can do this well ahead. Not for eating - is flavourless.)","images":[],"step":23}]', '["gluten","sesame","shellfish","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","deep-fried-recipes","prawns-shrimp"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2c0a261f4050', 'en', 'US', 'Sesame Crusted Tofu Steaks with Teriyaki Sauce', 'Recipe video above. Sesame seeds add excellent flavour and give tofu a crispy crust crust that stays crispy even when doused with Teriyaki Sauce. Great quick and easy recipe to convert tofu haters - so far from bland, we''re in a different stratosphere!', 'https://www.recipetineats.com/tachyon/2021/09/Crispy-Sesame-Tofu-Steaks-hero.jpg', 5, 10, 15, 4, '[{"id": "ing_tofu", "quantity": {"value": 4.0, "unit": "pack of 300g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.12, "unit": "pack of 100g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.12, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_cooking_sake", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["4 extra firm or hard tofu (, cut into 10 x 5 x 1.5cm slices (4 x 2 x 0.6\"), 100g / 3.5oz each (Note 1))","1/4 tsp each salt and pepper","2 tbsp flour (, plain/all purpose)","1 egg (, lightly whisked)","4 tbsp white sesame seeds (Note 2) (yes, you really need 4 tbsp!)","4 tbsp black sesame seeds (Note 2)","2 tbsp canola/vegetable oil","2 garlic cloves (, finely sliced 1mm thick (optional, Note 2))","1 green onion (, finely sliced (for garnish))"]},{"ingredients":["2 tbsp soy sauce (, preferably Japanese all-purpose, else light soy sauce (Note 4))","2 tbsp mirin (, preferably Japanese (Note 5))","2 tbsp cooking sake (, preferably Japanese (Note 6))","2 tbsp water"],"purpose":"Teriyaki Sauce:"}]', '[{"description":"Sesame coating:","images":[],"step":1},{"title":"Season tofu","description":"Pat tofu dry with paper towels. Sprinkle with salt and pepper.","images":[],"step":2},{"title":"Prepare crust coating","description":"Place flour, egg and sesame in separate bowls (medium shallow bowls or tupperware best).","images":[],"step":3},{"title":"Sesame crust","description":"Press tofu into flour, shake off excess. Dip in egg, then let excess drip off before coat in sesame seeds, pressing to adhere all over. Repeat with remaining tofu.","images":[],"step":4},{"description":"Cooking:","images":[],"step":5},{"title":"Crispy garlic","description":"Heat oil in a non stick skillet over medium heat. Add garlic and cook until golden and crisp. Remove and drain on paper towels.","images":[],"step":6},{"title":"Cook tofu","description":"Turn heat up to medium-high. Place tofu in skillet and cook for 1 1/2 minutes until the sesame smells nutty and becomes crisp. Turn carefully and cook the other side for 1 1/2 minutes. Then use tongs to prop the tofu steaks up on its sides to sear the edges until crisp - about 30 seconds each side should do it (see video for my technique).","images":[],"step":7},{"title":"Drain","description":"Remove tofu to paper towel lined plate.","images":[],"step":8},{"title":"Teriyaki Sauce","description":"Lower heat to medium then add Teriyaki Sauce ingredients. Simmer for 1 minute until it reduces to a syrupy consistency, then remove skillet from stove.","duration":1,"images":[],"step":9},{"title":"Serve","description":"Place tofu steak on plate. Spoon over Teriyaki Sauce (it clings to sesame, don''t worry, crust stays crispy). Sprinkle with garlic and green onion. Devour, then declare, \"I LOVE TOFU!!\".","images":[],"step":10}]', '["egg","gluten","sesame","soy"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Japanese(ish)","Modern Asian"],"categories":["asian-recipes","dietary","dinner-tonight","low-calorie-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_59b37d24b607', 'en', 'US', 'Ayam Goreng (Malaysian Fried Chicken)', 'Recipe video above. Marinated in a curry paste made with lemongrass, garlic and spices then tossed in cornflour to make the coating ultra craggy and crunchy, Ayam Goreng is Malaysia''s answer to Southern Fried Chicken. Hot contender for the world''s best fried chicken!Spiciness: Very mild. Feel free to dial it up by adding more chilli powder!', 'https://www.recipetineats.com/tachyon/2021/07/Ayam-Goreng_08.jpg', 10, 30, 1480, 4, '[{"id": "ing_chicken", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_galangal", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_lemongrass", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_turmeric", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_eshalots_and_roughly", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.263, "unit": "can of 400ml"}}, {"id": "ing_cornstarch", "quantity": {"value": 1.0, "unit": "pack of 400g"}}, {"id": "ing_oil", "quantity": {"value": 1.75, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.25 kg / 2.5 lb chichen thighs ad drumsticks, bone in skin on ( (I use 4 thighs, 3 drumsticks, Note 1))"]},{"ingredients":["2 tsp coriander seeds","2 tsp cumin seeds","1 tsp fennel seeds"],"purpose":"Toasted spices:"},{"ingredients":["3 garlic cloves (, roughly chopped)","1 tbsp ginger (, roughly chopped)","1 tbsp galangal (, roughly chopped (Note 2))","1 1/2 tsp curry powder (any type fine, mild or spicy - your choice)","1 lemongrass (, white part only roughly chopped (Note 3))","1 tsp turmeric powder","2 small eshalots (French onions, US: shallots), peeled and roughly chopped (Note 4)","1 1/2 tsp cooking/kosher salt (or 1 tsp table salt)","1/2 tsp chilli powder (, adjust to taste (Note 5))","2 tsp brown sugar","7 tbsp coconut milk (full fat best!)"],"purpose":"Ayam Goreng Curry Paste:"},{"ingredients":["1/2 cup cornflour / cornstarch","1.75 litres / quarts vegetable or canola oil"],"purpose":"Cooking:"},{"ingredients":["1 tbsp garlic (,minced (not too small, else it burns))","1 tbsp large red chilli ((cayenne pepper), deseeded and minced)","1 tbsp green onion (, minced)","Pinch of salt","Coriander/cilantro leaves"],"purpose":"Garnish (optional):"}]', '[{"title":"Toast spices","description":"Toast spices in a small skillet over medium heat (no oil) for 2 minutes or until the spices smell fragrant. Transfer seeds into Nutribullet, small food processor OR into a tall jug that fits a stick blender.","duration":2,"images":[],"step":1},{"title":"Curry paste","description":"Add remaining Curry Paste ingredients and blend until smooth.","images":[],"step":2},{"title":"Marinate","description":"Pour Curry Paste over chicken in a ziplock bag (or bowl, Note 6). Toss to coat, then marinate for 24 hours in the fridge, up to 48 hours.","images":[],"step":3},{"description":"PREPARE TO COOK (WORK IN SPECIFIED ORDER OF STEPS):","images":[],"step":4},{"title":"Dechill chicken","description":"Remove chicken from fridge 30 minutes prior to cooking and transfer into a bowl (most marinade should be stuck to chicken).","images":[],"step":5},{"title":"Preheat oven to 80°C/175°F and place rack on tray","description":"to keep chicken warm. (Note 7)","images":[],"step":6},{"title":"Cornflour coating","description":"Add cornflour to chicken and toss to coat - it will thicken the paste, this is what makes the craggy coating.","images":[],"step":7},{"title":"Heat oil 180°C/350°F","description":"Pour oil into a wide, heavy based pot to a depth of 6 cm / 2.5 \" (my 26cm/10.5\" cast iron pot = 1.75L/quarts oil, Note 8). Heat over medium high heat to 180°C/350°F - maintain temp as best you can (Note 9). This recipe will NOT work well with an air fryer – see Note 8.","images":[],"step":8},{"title":"Fry","description":"Carefully place 3 pieces of chicken in, do not touch for 2 min (to let crust adhere). Oil temperature should drop to 150°C/300°C - increase heat if needed.","duration":2,"images":[],"step":9},{"title":"Fry 8 minutes (75°C / 167°F)","description":"Fry for 8 minutes (wings for 5 minutes), or until deep golden brown and internal temperature at thickest part is 75°C / 167°F.","duration":8,"images":[],"step":10},{"title":"Keep warm","description":"Place cooked chicken onto rack and keep warm in oven. Cook remaining chicken.","images":[],"step":11},{"description":"Serve immediately, sprinkled with coriander and garlic-chilli garnish, if using. See in post for side dish suggestions!","images":[],"step":12},{"description":"Heat 3 tbsp oil in a small skillet over medium heat. Add garlic and chilli, cook until garlic is starting to go light golden. Then add green onion and cook until garlic is golden. Drain on paper towels, sprinkle with salt. Cool then sprinkle on chicken.","images":[],"step":13}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian","Malaysian","South East Asian"],"categories":["asian-recipes","asian-takeout","chicken","chicken-recipes","deep-fried-recipes","iconic-dishes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_720d4ba41b50', 'en', 'US', 'Sticky Honey Soy Chicken - baked', 'Recipe video above. This is still the best, EASIEST sticky honey soy chicken recipe I have come across. And I''ve tried many over the years! Marginally adapted from this recipe by Sprinkles and Sprouts. The sauce is very thin when you put it together and gets even thinner while baking, but miraculously, it suddenly thickens into an incredible glaze to squidge the chicken in. It''s salty and sweet with a lovely hit of sesame.Please do not double the recipe or sauce, this will prevent the sauce from reducing down to the sticky glaze you see pictured.', 'https://www.recipetineats.com/tachyon/2016/02/Honey-Soy-Baked-Chicken_60.jpg', 5, 50, 55, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.0, "unit": "pack of 3 heads"}}, {"id": "ing_honey", "quantity": {"value": 0.09, "unit": "jar of 500g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.2kg / 2.4lb bone-in, skin-on chicken thighs OR drumsticks (5 - 6 pieces) (Note 1)","1 red onion (, peeled, cut into wedges)"]},{"ingredients":["3 cloves garlic (, minced)","3 tbsp honey","3 tbsp soy sauce (Note 2)","1 tbsp apple cider vinegar (or ordinary white vinegar)","1 tsp sesame oil","1/2 tsp black pepper"],"purpose":"Glaze"},{"ingredients":["Sesame seeds","Fresh coriander/cilantro leaves (or other green things like green onion, parsley, chives)"],"purpose":"Garnish (optional)"}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":1},{"title":"Line pan","description":"Line a baking dish with foil then baking paper. The baking tray should fit the chicken comfortably, not too spaced apart (glaze will dry out), not too snug (glaze won''t thicken enough). (Note 3)","images":[],"step":2},{"title":"Glaze","description":"Mix the Glaze ingredients together.","images":[],"step":3},{"title":"Pour glaze over chicken","description":"Place onion and chicken in the baking dish skin side down, then pour the Glaze over.","images":[],"step":4},{"title":"Bake 50","description":"60 minutes: Bake for 25 minutes, then turn and bake for a further 25 to 35 minutes, until the chicken is browned and the glaze is sticky. If the glaze is not syrupy, remove the chicken to a plate and put the pan back in for a few minutes (it will reduce quickly).","duration":25,"images":[],"step":5},{"title":"Squidge/coat chicken","description":"Turn chicken and squidge in the glaze, then also spoon it over.","images":[],"step":6},{"description":"Serve! Serve with rice and steamed greens, sprinkled with sesame seeds and fresh cilantro/coriander leaves.","images":[],"step":7}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian influence"],"categories":["asian-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f505a0450ac5', 'en', 'US', 'Beef Satay with Thai Peanut Sauce', 'Recipe video above. Meat on sticks is always a good thing, and Thai Beef Satay is one of the best! In this beef version of Thai Chicken Satay, a secret tenderising satay marinade makes economical steak astonishingly succulent. So good, you can eat it plain – but no one in their right mind would skip the Thai Peanut Sauce!Note: Baking soda tenderised beef needs to be thoroughly cooked to be tender. The beef is still a bit chewy if it''s medium or less (because we''re using economical beef).Top tip: Excellent to grill on the BBQ, or even better, over charcoal for a truly authentic Thai experience.Use leftover sauce for Thai Chicken Satay, Gado Gado (Indonesian Salad with Peanut Sauce) or just douse a bowl of plain rice. You can''t go wrong!', 'https://www.recipetineats.com/tachyon/2021/07/Thai-Beef-Satay-with-Peanut-Sauce.jpg', 15, 15, 1470, 12, '[{"id": "ing_skewers", "quantity": {"value": 14.5, "unit": "pack of 50"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_coconut_mik", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.037, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_red_curry_paste", "quantity": {"value": 0.04, "unit": "bottle"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.005, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.005, "unit": "can of 400ml"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.003, "unit": "jar of 375g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_peanuts", "quantity": {"value": 0.075, "unit": "jar"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["13-16 bamboo skewers (, 16cm / 6.5\" long (Note 1))"]},{"ingredients":["600g / 1.2lb beef rump steak (top sirloin in the US) (, 2.5 cm/1\" pieces (Note 2))","1/4 cup coconut mik (, full fat (I use Ayam, Note 3))","1 tbsp curry powder (Note 4)","1 tsp white sugar","2 tsp red curry paste (Note 5)","1/2 tsp baking soda / bi-carb (tenderiser, Note 6)","1 tsp salt"],"purpose":"Marinade:"},{"ingredients":["1 tbsp red curry paste (Note 5)","2/3 cup coconut milk (, full fat (I use Ayam, Note 3))","1/3 cup natural peanut butter (, smooth (Note 7))","1 1/2 tbsp white sugar","1 tsp dark soy sauce (Note 8)","1/2 tsp salt","1 tbsp cider vinegar (Note 9)","1/3 cup water"],"purpose":"Thai Peanut Sauce:"},{"ingredients":["1 1/2 tbsp vegetable oil (, for cooking)","2 tbsp peanuts (, finely chopped)","Lime wedges (optional)","Coriander / cilantro leaves and sliced red chilli (optional)"],"purpose":"Cooking & Serving:"}]', '[{"description":"If cooking on a BBQ or over charcoal, soak skewers for 2 hours in water so they don''t burn.","images":[],"step":1},{"description":"Thai Beef Satay Skewers:","images":[],"step":2},{"description":"Mix together the beef and Marinade in a bowl. Cover with cling wrap and marinate overnight (do not reduce marinating time else the beef may not tenderise enough).","images":[],"step":3},{"title":"Thread onto skewers","description":"I do 4 pieces each.","images":[],"step":4},{"description":"Heat 1.5 tbsp oil in a large non stick pan over medium high heat.","images":[],"step":5},{"title":"Cook 10 minutes (yes, well done!)","description":"Cook skewers in batches for 2 to 2 1/2 minutes on all 4 sides until deep golden (total of 8 to 10 minutes) and fully cooked through. (Note: baking soda tenderised beef needs to be thoroughly cooked to be tender. The beef is still a bit chewy if it''s medium or less.)","images":[],"step":6},{"title":"Rest","description":"Transfer skewers to plate and rest for 3 minutes before serving with Peanut Sauce.","duration":3,"images":[],"step":7},{"description":"Thai Peanut Sauce:","images":[],"step":8},{"description":"Place all Peanut Sauce ingredients in a small saucepan over medium low heat.","images":[],"step":9},{"description":"Stir to combine then simmer, stirring every now and then, for 5 minutes. Adjust consistency with water - it should be a pourable but thickish sauce.","duration":5,"images":[],"step":10},{"description":"Remove from stove, cover with lid and keep warm while cooking skewers.","images":[],"step":11},{"description":"Pour sauce into a bowl. Sprinkle with some peanuts - stir some through if you want.","images":[],"step":12},{"description":"Pile satay skewers onto a platter, sprinkle with remaining peanuts, coriander and chilli.","images":[],"step":13},{"description":"Serve with sauce on the side for dipping. Add a side of Jasmine Rice or Thai Fried Rice or Pineapple Fried Rice to complete the meal!","images":[],"step":14}]', '["gluten","peanuts","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","beef","beef-recipes","cuisines","grilling-ideas-and-recipes","mains","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8d212b4e6ec6', 'en', 'US', 'Prawn Stir Fry (Shrimp)', 'Recipe video above. Dinner is sorted with these plump and juicy prawns in a classic ginger sesame Chinese stir fry sauce, with snow peas and broccolini. It’s a Chinese restaurant standard!As with all stir fries, feel free to switch the vegetables for anything you''ve got!TOP TIP: The best way to ensure you don''t overcook the prawns is to cook them first, remove, then add them back in at the end. Perfectly plump and juicy prawns, every single time!', 'https://www.recipetineats.com/tachyon/2021/06/Prawn-Stir-Fry-Shrimp_8.jpg', 10, 7, 17, 3, '[{"id": "ing_soy_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_shrimp", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.02, "unit": "pack of 3 heads"}}, {"id": "ing_broccoli", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_snow_peas", "quantity": {"value": 120.0, "unit": "unit"}}]', '[{"ingredients":["1 1/2 tbsp light soy sauce (sub all purpose soy, Note 1)","1 tbsp Chinese cooking wine (sub Mirin or dry sherry, Note 2)","2 tsp oyster sauce (Note 3)","1/2 tsp sesame oil (, toasted (Note 4))","1 tbsp cornflour/cornstarch","1/8 tsp white pepper (sub black pepper)","3/4 cup water"],"purpose":"Prawn Stir Fry Sauce:"},{"ingredients":["2 tbsp oil (, peanut, canola or vegetable)","250g / 8 oz medium prawns (, raw, peeled and deveined (equiv. 500g/1lb whole prawns, Note 5))","1/2 onion (, sliced, brown or white)","2 tsp ginger (, finely julienned (~2cm / 0.7\" piece))","2 tsp garlic (, finely chopped (~ 2 cloves))","1 1/2 bunches broccolini (, trimmed, cut into 5cm / 2\" lengths, (~1 1/2 cups. Sub normal broccoli))","120g / 4 oz snow peas (, thin string removed from both sides)"],"purpose":"Stir Fry:"}]', '[{"title":"Steam broccolini","description":"Steam broccolini until crisp-tender, about 2 - 3 minutes (remember it will cook more in the stir fry). Set aside to drain and dry.","images":[],"step":1},{"title":"Stir Fry Sauce","description":"Put all Stir Fry Sauce ingredients except water into a bowl. Mix until cornflour is dissolved. Then stir in water.","images":[],"step":2},{"title":"Cook then remove prawns","description":"Heat oil in a wok or large skillet on medium to medium-high heat. Add prawns and spread them in a single layer. Cook for 1 1/2 minutes, then turn and cook the other side for 1 minute until cooked through. Try not to make the prawns too golden (they are only lightly browned in stir fries). Remove prawns to a bowl. Set aside.","duration":1,"images":[],"step":3},{"title":"Cook onion, garlic and ginger","description":"Add more oil if the pan seems a bit dry. Still on medium-high heat, add onion and cook for 1 minute. Then add ginger and garlic and cook for another 1 minute until onion is starting to soften but not colour.","duration":1,"images":[],"step":4},{"title":"Add snow peas, then broccolini","description":"Add snow peas and toss until coated with oil. Then add broccolini and toss through.","images":[],"step":5},{"title":"Add Sauce and thicken","description":"Give the Sauce a stir (to dissolve cornflour settled at bottom), then pour into skillet. Cook, stirring, until sauce thickens to syrup consistency (about 1 minute) and coats the ingredients nicely.","images":[],"step":6},{"title":"Add prawns back in","description":"Then add the prawns back in (including any juices in the bowl). Toss for another 30 seconds until prawns are warmed through.","images":[],"step":7},{"title":"Serve","description":"Serve with rice!","images":[],"step":8}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dinner-tonight","prawns-shrimp","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cde66a3d365b', 'en', 'US', 'Golden Turmeric Fish (Indonesian baked fish recipe)', 'Recipe video above. This homestyle Indonesian baked fish recipe is made with a Turmeric Curry Paste slathered on to white fish fillets which are then baked, and served topped with an Indonesian-style tomato salsa called Sambal Tomat.The curry paste is a gorgeously vibrant yellow colour thanks to the turmeric, and packed with fragrant and fresh South-East Asian curry flavours (as opposed to big, in-your-face-spice like Indian curries!).Sambal Tomat comes in all forms, from complex versions with flavourings like shrimp paste, to simpler and fresh ones like this one. We only need a simple one, the curry paste has plenty of flavour!', 'https://www.recipetineats.com/tachyon/2021/05/Golden-Turmeric-Fish-Indonesian_7.jpg', 15, 15, 30, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_turmeric", "quantity": {"value": 0.025, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_macadamia_nuts", "quantity": {"value": 0.005, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_lemongrass", "quantity": {"value": 2.5, "unit": "bunch"}}, {"id": "ing_oil", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 250.0, "unit": "punnet of 250g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}]', '[{"ingredients":["4 x 180g / 6oz white fish fillets (, medium to thick, skinless (Note 1))","1/2 tsp salt","1 tbsp lime juice"],"purpose":"Quick lime marinade:"},{"ingredients":["1 small eschalot (~1/4 cup roughly chopped) (Note 2)","1 garlic clove (, finely grated*)","2 tsp fresh turmeric (, finely grated* or substitute powdered (Note 3))","1 tsp ginger (, peeled and finely grated*)","1 1/2 tbsp macadamia nuts (Note 4)","1/4 tsp salt","1/8 tsp black pepper","1 kaffir lime leaf (, torn by hand (Note 5))","2.5cm / 1\" piece of fresh lemongrass, white part only, ( cut into 1cm / 0.2\" pieces (Note 6))","1 tbsp oil","2 tbsp water"],"purpose":"Turmeric Curry Paste:"},{"ingredients":["2 tsp oil","250g / 8oz cherry tomatoes (, quartered)","1 large red chilli (cayenne pepper) (, deseeded and finely diced (adjust to taste, Note 7))","2 tsp coriander/cilantro leaves (, finely chopped (plus more for garnish))","1/4 tsp salt"],"purpose":"Sambal Tomat Topping:"}]', '[{"title":"Prep","description":"Preheat oven to 200°C / 390°F (180°C fan). Line a tray with baking / parchment paper.","images":[],"step":1},{"title":"Quick fish marinade","description":"Sprinkle fish with salt and drizzle with lime juice. Leave in fridge while making paste - just 10 minutes is fine.","images":[],"step":2},{"title":"Turmeric Curry Paste","description":"Place ingredients in a container that fits a stick blender. Then blend with stick until smooth, using extra water if needed until it is a paste consistency (ie. can be slathered on fish).","images":[],"step":3},{"title":"Slather and bake","description":"Smear paste onto surface of fish (not underside). Bake for 15 minutes until the internal temperature is 55°C/131°F (medium, just cooked but not raw at all, very juicy).","duration":15,"images":[],"step":4},{"title":"Rest","description":"Remove from oven and remove fish from tray (otherwise it keeps cooking). Rest 3 minutes, serve over rice with Sambal Tomat (below) and extra fresh coriander.","images":[],"step":5},{"title":"Sambal Tomat Topping","description":"Heat oil in a non-stick pan over medium heat. Add tomato, chilli and salt. Sauté 2 minutes until tomato is slightly softened. Stir through coriander, serve over fish.","images":[],"step":6}]', '["fish","nuts"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Indonesian"],"categories":["asian-recipes","curry-recipes","dietary","fish-recipes","gluten-free-recipes","low-calorie-recipes","mains","modern-asian","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_61ac668a588e', 'en', 'US', 'Galbi - Korean BBQ Marinated Beef Short Ribs', 'Recipe video above. This is an excellent Korean barbecue marinade that will work with pork, chicken or even lamb. And while it''s delicious cooked on the stove, a BBQ will better replicate the true Korean barbecue experience!Do not worry about overcooking the thin slices of beef. The marinade is magical, it keeps the thin slices of beef incredibly tender even if you cook it for over 10 minutes which would ordinarily turn the beef into inedible dry cardboard!', 'https://www.recipetineats.com/tachyon/2021/04/Korean-Beef-Short-Ribs-Galbi_6-1.jpg', 10, 10, 20, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_pears", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.02, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 kg/ 2lb beef short ribs, butterflied Korean style (pictured) ( or thinly sliced through the bone (Note 1 for subs))","1 tbsp vegetable oil (, for cooking)"]},{"ingredients":["1/3 cup soy sauce (all purpose or light soy, not dark or sweet)","1/4 cup brown sugar","2 tbsp mirin (Note 2)","1/4 cup onion (, finely grated (including juice))","1/4 cup nashi pear (, finely grated including juice (sub normal pear or any red apple, Note 3))","2 tsp garlic (, finely grated)","2 tsp ginger (, finely grated)","2 tbsp water","1 tbsp toasted sesame oil (Note 4)","1 tsp black pepper"],"purpose":"Korean Barbecue Marinade:"},{"ingredients":["Green onion, sesame seeds, coriander/cilantro leaves (, for garnish)","Kimchi Fried Rice","Smashed Cucumbers"],"purpose":"Serving (optional):"}]', '[{"title":"Make Marinade","description":"Whisk Marinade ingredients in a bowl.","images":[],"step":1},{"title":"Marinade 24 hours","description":"Place beef in a ziplock bag, glass or ceramic container. Pour over Marinade, mix well to coat. Cover and marinade for 24 hours.","images":[],"step":2},{"description":"Cooking:","images":[],"step":3},{"description":"Remove beef from Marinade, discard Marinade.","images":[],"step":4},{"title":"BBQ","description":"Heat on high until smoking hot, then brush grills with vegetable oil. Lay beef on BBQ and cook for 2 minutes on one side until caramelised. Turn and cook the other side until caramelised. Remove, loosely cover with foil, cook remaining beef.","duration":2,"images":[],"step":5},{"title":"Stove","description":"Cut beef strips into pieces that will fit your skillet. Heat skillet with oil over high heat. Add beef and cook for 2 minutes until caramelised, then turn and cook the other side for 2 minutes.","duration":2,"images":[],"step":6},{"description":"Garnish beef with sesame seeds and green onions if desired. You don''t need a sauce for this one - it is literally dripping with flavour! Pictured in post with Kimchi Fried Rice and Ginger Smashed Cucumbers.","images":[],"step":7}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","BBQ","Korean"],"categories":["asian-recipes","asian-takeout","beef","beef-recipes","grilling-ideas-and-recipes","iconic-dishes","korean-recipes","mains","modern-asian"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d4b904f2b27d', 'en', 'US', 'Thai Cashew Chicken Stir Fry', 'Recipe video above. Crunchy and creamy cashews are the star in this popular Thai chicken stir fry! Tossed with a bold and savoury Thai stir fry sauce, make this as spicy as you want – or not at all.Thai Cashew Chicken is a dry-style stir fry so there''s not a ton of sauce like with Chinese Cashew Chicken. But the flavour in this one is much more intense so you don''t need nor do you want more sauce, it will be too salty!SPICINESS: Nice buzz to it from 1/2 a fresh chilli, not blow-your-head-off spicy.', 'https://www.recipetineats.com/tachyon/2021/04/Thai-Cashew-Chicken_9.jpg', 10, 8, 18, 2, '[{"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_cashews", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.001, "unit": "jar of 40g"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp peanut oil (or canola or vegetable oil)","1/2 cup raw cashews (, unsalted (Note 1 for roasted))","1 garlic clove (, finely minced)","1/2 onion ((brown, yellow, or white), cut into thin wedges)","200g/7oz chicken thighs (, skinless and boneless, sliced into 1cm / 1/3\" thin strips (Note 2))","2 green onions (, cut into 2.5cm / 1” lengths, white part separated from green part)","1/2 red cayenne pepper (, deseeded and finely sliced on the diagonal (omit or reduce if preferred) (Note 3))"]},{"ingredients":["1 tbsp oyster sauce (Note 4)","1 tsp dark soy sauce (Note 5)","2 tsp fish sauce (Note 6)","1 tsp white sugar","3 tbsp water"],"purpose":"Sauce:"},{"ingredients":["Red chilli (, finely sliced (optional garnish))","Jasmine rice (, for serving (or other rice of choice))"],"purpose":"Serving:"}]', '[{"title":"Sauce","description":"Mix all the Sauce ingredients in a small bowl.","images":[],"step":1},{"title":"Cook cashews","description":"Heat oil over medium heat in a wok or large skillet. Add cashews and cook for 5 minutes until they become a dark golden colour and crunchy (yep, you might have to eat one to check!). Remove from skillet with a slotted spoon.","duration":5,"images":[],"step":2},{"title":"Garlic & onion","description":"Turn heat up to high. Add garlic and onion. Cook for 30 seconds.","duration":0.5,"images":[],"step":3},{"title":"Chicken","description":"Add chicken. Cook for 1 minute until the outside changes from pink to white.","duration":1,"images":[],"step":4},{"title":"White part of green onion & chilli","description":"Add white part of green onions and chilli. Cook for 1 minute until chicken is just cooked through.","duration":1,"images":[],"step":5},{"title":"Add Sauce","description":"Cook for 1 minute until it reduces down to a syrup, coating the chicken nicely.","duration":1,"images":[],"step":6},{"title":"Green onion & cashews","description":"Add green part of green onions and cashews. Toss for 30 seconds.","duration":0.5,"images":[],"step":7},{"title":"Serve","description":"Transfer to serving dish. Serve with jasmine rice, or other rice of choice, garnished with extra red chilli (if you can handle the heat!).","images":[],"step":8}]', '["fish","gluten","peanuts","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken","chicken-breast-recipes","chicken-recipes","cuisines","dinner-tonight","mains","quick-and-easy","stir-fries","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b830007f7c89', 'en', 'US', 'Asian Glazed Baked Barramundi (or other fish)', 'Recipe video above. Banish boring baked fish with this sweet n'' savoury, gently spiced Asian-style barbecue glaze. A quick finish under the broiler / grill caramelises the glaze for maximum flavour! For the most juicy and perfectly cooked fish, take the fish out when the internal temperature is 55C/135F. Serve with plain or flavoured rice, and some wholesome veggies to complete.', 'https://www.recipetineats.com/tachyon/2021/02/Baked-Barramundi-with-Asian-Glaze_5.jpg', 10, 25, 35, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.05, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.3, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.12, "unit": "jar of 500g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sambal_oelek", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["4 x 180g / 6oz barramundi fillets (, skinless, boneless; or other ~2.5cm / 1\" thick firm white fish fillets (Note 1))"]},{"ingredients":["4 tsp cornflour / cornstarch","2 tbsp water","5 tbsp soy sauce (, all-purpose or light soy sauce (Note 2))","4 tbsp honey (else maple syrup or 5 tbsp brown sugar)","1 tbsp sesame oil","1 tbsp Chinese black vinegar or rice vinegar (Note 3)","1 tbsp mirin (Note 4)","1 tsp sambal oelek (, or other Asian chilli paste / sauce (Note 5))","1/2 tsp Chinese Five Spice (Note 6)","1 clove garlic (, finely minced)","1 tsp ginger (, finely grated)","1/4 tsp Sichuan pepper (, or white pepper (Note 7))"],"purpose":"Glaze:"},{"ingredients":["Sesame seeds","Green onions (Note 8)","Large red chilli, finely sliced"],"purpose":"Garnishes"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan). Line a tray with parchment/baking paper. Place shelf in middle of oven.","images":[],"step":1},{"title":"Cornflour slurry","description":"Mix water and cornflour in a small bowl.","images":[],"step":2},{"title":"Make glaze","description":"Place remaining glaze ingredients in a small saucepan over medium-low heat. Simmer for 2 minutes. Add cornflour slurry then stir well. Cook it for a further 2 minutes until it thickens into a thick paste – thick enough so it stays on the fish when brushed on. See photo in post or video. If it is just a thick syrup, it will slide off the fish.","duration":2,"images":[],"step":3},{"title":"Brush glaze on Fish","description":"Place fish fillets on tray. Dab/brush paste on on the top and sides.","images":[],"step":4},{"title":"Bake then broil/grill","description":"Bake fish for 15 minutes. Then flick to broiler/grill on high, and cook for 3 minutes to caramelise the surface. Target an internal temperature of 55°C/131°F for medium, which is just cooked but not raw at all. Fish temperature will continue to rise to 58°C/136.5°F during resting.","duration":15,"images":[],"step":5},{"title":"Garnish","description":"Remove from oven, transfer to serving plates and rest for 5 minutes. Garnish with green onion, chillies and sesame seeds, as desired. Pictured in post with a side of Coconut Rice and cucumber with Asian Sesame Dressing.","duration":5,"images":[],"step":6}]', '["fish","gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","dietary","dinner-tonight","fish-recipes","low-calorie-recipes","mains","modern-asian","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ad31a0106d3d', 'en', 'US', 'General Tso''s Chicken', 'Recipe video above. That perfect combination of sweet, savoury, spicy and tangy with crispy Chinese chicken bites. This is a Chinese takeout favourite that pushes all the right buttons!', 'https://www.recipetineats.com/tachyon/2020/10/General-Tsao-Chicken_1.jpg', 15, 10, 25, 4, '[{"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.01, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 0.005, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["3 tbsp soy sauce - light or all-purpose (NOT dark soy, Note 1)","1 tbsp hoisin sauce","1 tbsp rice vinegar (sub white wine vinegar)","2 tsp chilli paste (, any (Sambal Oelak is great))","1 tsp sesame oil (toasted preferably (Note 6))","3 tbsp brown sugar","1 tbsp cornflour/cornstarch","3/4 cup chicken stock/broth (, low sodium)"],"purpose":"Sauce/Chicken Marinade:"},{"ingredients":["600g/ 1.4 lb chicken thighs (, boneless skinless, cut into 2.5cm / 1\" pieces (breast / tenderloin - Note 2))","1 tsp ginger (, finely grated)","1 tsp garlic (,finely grated)","1 cup cornflour/cornstarch (Note 5)","1 - 4 cups oil, for frying (peanut, vegetable or canola; Note 4)"],"purpose":"Chicken:"},{"ingredients":["2 tbsp oil (peanut, vegetable or canola)","2 tsp ginger (, finely chopped (Note 3))","2 cloves garlic (, finely chopped (Note 3))","1/2 teaspoon red chilli flakes (red pepper flakes)"],"purpose":"Stir Fry Sauce:"},{"ingredients":["Finely sliced green onion","Sesame seeds"],"purpose":"Garnishes (at least 1 recommended):"}]', '[{"title":"Sauce-Marinade","description":"Mix the soy, hoisin, vinegar, chilli and sesame oil.","images":[],"step":1},{"title":"Marinate Chicken","description":"Take out 2 tablespoons of Sauce-Marinade and mix with chicken. Add ginger and garlic to chicken, mix, then marinate 30 minutes.","images":[],"step":2},{"title":"Dust chicken","description":"Add cornflour into chicken and toss to coat, ensuring pieces are separated so they get fully coated.","images":[],"step":3},{"title":"Shake off excess","description":"Tip into a colander and shake to remove excess cornflour (or grab handfuls, shake so cornflour falls through your fingers).","images":[],"step":4},{"title":"Finish Sauce","description":"To the remaining Sauce-Marinade (that you made in Step 1), add sugar and cornflour. Mix, then add chicken stock and mix.","images":[],"step":5},{"title":"Heat oil","description":"Heat 2 cm / 4/5\" oil in a deep skillet (or large pot - whatever you’re comfortable with) to 200°C/390°F. To use less, see Note 4.","images":[],"step":6},{"title":"Fry","description":"Cook chicken 3 minutes, turning halfway, until golden and crispy. Drain on paper towel lined plate.","images":[],"step":7},{"title":"New / clean skillet","description":"Discard oil, wipe skillet and return to heat. Or use another large skillet.","images":[],"step":8},{"title":"Stir Fry Sauce","description":"Heat oil in a large skillet over medium heat. Add garlic, ginger, chilli flakes, saute 30 seconds until garlic is light golden. Add Sauce, bring to simmer and stir occasionally until it thickens enough that you can draw a path across pan base.","images":[],"step":9},{"title":"Toss! Add chicken, toss to coat quickly","description":"the quicker you are, the crispier the chicken stays! Transfer to serving plate, garnish and serve immediately with your rice of choice.","images":[],"step":10}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese","Chinese"],"categories":["asian-recipes","asian-takeout","chicken-recipes","chinese-recipes","modern-asian"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c2ace503e5a6', 'en', 'US', 'Chinese Rice Soup', 'Recipe video above. This is a really quick and easy soup recipe that''s filling and nourishing. The Asian infused soup broth adapted from my Chinese Noodle Soup has a depth of flavour that belies the few ingredients called for. As for add ins - in the spirit of simplicity and speed, I''ve just used fish and choy sum. But you''re only limited by your imagination!', 'https://www.recipetineats.com/tachyon/2020/10/Chinese-Rice-Soup_0.jpg', 5, 10, 15, 3, '[{"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 2.0, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.625, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_stems_choy_sum", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 litre / 32 oz chicken stock/broth, low sodium (Note 1)","1 cup water","2 garlic cloves (, smashed (Note 2))","1.5 cm / 1/2\" ginger piece, (cut into 3 slices)","1 1/2 tbsp light soy sauce (, or normal all purpose soy sauce (Note 3))","1 1/2 tbsp Chinese cooking wine (, key ingredient (Note 4 subs))","1/4 - 1/2 tsp sesame oil (, toasted (optional) (Note 5))","1/4 tsp white pepper (sub black, can omit)"],"purpose":"Broth"},{"ingredients":["3/4 cup uncooked white rice (- long grain, medium grain, short grain, jasmine (Note 6))","3 stems choy sum (, cut into 2cm / 1\" lengths, stems separated from leaves (Note 8))","250g / 8 oz white fish fillets (, cut into 2.5cm / 1\" cubes (Note 8))","1 green onion (, finely sliced)"],"purpose":"Add Ins"},{"ingredients":["Crispy fried shallots (Note 9)","Crunchy fried noodles (, pictured in post (Note 9))","Chilli oil or paste"],"purpose":"Toppings (1 minimum, all best!)"}]', '[{"title":"Combine broth ingredients","description":"Place chicken stock, soy sauce, Chinesse cooking wine, garlic and ginger in a small pot over high heat.","images":[],"step":1},{"title":"Simmer to infuse","description":"Place lid on, bring to simmer then reduce to medium and simmer for 5 minutes to allow the flavours to infuse.","duration":5,"images":[],"step":2},{"title":"Add rice","description":"Add rice and cook uncovered for 10 minutes - broth surface should be bubbling very gently.","duration":10,"images":[],"step":3},{"title":"Add fish & stems","description":"Add fish and stems of choy sum, cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Pick garlic and ginger out of soup.","images":[],"step":5},{"description":"Stir through choy sum leaves (they will wilt almost instantly), sesame oil and pepper. Serve immediately.","images":[],"step":6}]', '["fish","gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-soups","chinese-recipes","emergency-recipes","fish-recipes","quick-and-easy","rice-recipes","seafood-recipes","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9d58951cd4c5', 'en', 'US', 'Satay Chicken Curry (Malaysian)', 'Recipe video above. Forget skewers - THIS is how you get a satay fix! This Malaysian Chicken Satay Curry features chicken marinated in a homemade satay seasoning, simmered in a heady peanut satay sauce that''s coconuty and heavily seasoned. Truly restaurant quality. Yet -simple. No hunting down unsual ingredients!Spice level: Pretty warm buzz but not that spicy. If concerned, read note 1 & 3 for how to play it safe with the chilli!Adapted from a Satay recipe by a Malaysian chef and the Satay Sauce from Chinta Ria, a popular Sydney Asian restaurant - refer Note 10.', 'https://www.recipetineats.com/tachyon/2016/05/Satay-Chicken-Curry_9.jpg', 20, 25, 45, 5, '[{"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 0.005, "unit": "jar"}}, {"id": "ing_paprika", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.01, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.5, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 4.5, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.008, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_peanuts_roasted", "quantity": {"value": 0.007, "unit": "jar"}}, {"id": "ing_kecap_mani", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.08, "unit": "jar of 375g"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_lemongrass", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_peanuts", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 1/2 tsp coriander","1 1/2 tsp cumin powder","1 1/2 tsp tumeric","1 1/2 tsp paprika (sweet or normal, not smoked or spicy)","1 1/4 tsp chilli powder (, adjust to taste (not US \"Chili Powder\", Note 1))","3 1/2 tsp curry powder (, not HOT (any, Malaysian, generic, Clives of India, Keens))","1 1/4 tsp salt (, cooking / kosher (or 1 tsp table salt))","2 tsp white sugar"],"purpose":"Satay Seasoning"},{"ingredients":["750g / 1.5 lb chicken thigh fillets (, cut into bite size pieces (Note 2))","1/2 onion ((brown, white or yellow), grated)"],"purpose":"Chicken"},{"ingredients":["2 tbsp oil (, separated)","3 - 6 birds eye chillies or other small hot red chillies (, finely chopped (Note 3))","1/4 cup onion (brown, white or yellow), finely diced (~ 1/4 onion)","4 garlic cloves (, minced)","1 cup chicken broth / stock","3/4 cup peanuts, roasted unsalted, (, chopped, separated)","2 tsp kecap manis (Note 4)","3 tsp dark soy sauce (Note 5)","400g / 14oz coconut milk (preferably full fat but light will be ok)","2 tbsp peanut butter (, pure best but spread ok too, crunchy or smooth)","2 tbsp lime juice (, to taste)"],"purpose":"Satay Sauce"},{"ingredients":["3 makrut lime leaves (formerly kaffir lime leaves) (Note 6)","1 lemongrass stalk (, white part only, smashed to burst open (Note 7))"],"purpose":"Flavour Infusion – choose ONE:"},{"ingredients":["Peanuts (, chopped)","Cilantro / coriander leaves","Fresh chilli, finely chopped"],"purpose":"Garnish (choices)"}]', '[{"description":"Combine Satay Seasoning ingredients in a small bowl.","images":[],"step":1},{"description":"Marinate & Cook Chicken:","images":[],"step":2},{"title":"Marinate","description":"Combine chicken with 3 1/2 TABLESPOONS Satay Seasoning and onion in a bowl. Marinate for at least 3 hours, preferably overnight, minimum 20 minutes (Note 6)","images":[],"step":3},{"title":"Cook","description":"Heat 1 tbsp oil in a non stick skillet over high heat (Note 7). Cook chicken in 2 batches until browned all over but still raw inside. Transfer to bowl, cover and keep warm.","images":[],"step":4},{"title":"Saute aromatics","description":"Using the same skillet, turn heat down to medium and heat 1 tbsp oil. Add chill, onion and garlic cloves. Sauté until onion is translucent - around 2 minutes.","images":[],"step":5},{"title":"Satay Seasoning","description":"Add remaining Satay Seasoning and cook for 1 minute.","duration":1,"images":[],"step":6},{"title":"Blitz","description":"Transfer to a blender or small food processor (I use a Nutribullet). Add chicken stock and 1/2 cup of the peanuts (rest gets added later). Puree until pretty smooth - some peanut chunks can remain. Pour mixture back into the skillet.","images":[],"step":7},{"title":"Add remaining ingredients into sauce","description":"Add remaining 1/4 cup peanuts, kecap manis, dark soy sauce, coconut milk and peanut butter. Stir to combine.","images":[],"step":8},{"title":"Add lime leaf or lemongrass","description":"Crush makrut lime leaf in hand a bit (to break leaf to release the flavour). Add lime leaf OR lemongrass and chicken to sauce.","images":[],"step":9},{"title":"Simmer","description":"Bring to simmer, turn heat down to medium low and simmer for 15 minutes until thickened.","duration":15,"images":[],"step":10},{"title":"Serve","description":"Add lime juice to taste. Serve with rice (jasmine, white rice or brown rice). Garnish with peanuts, cilantro/coriander leaves and more chilli if desired. See Note 9 for suggested sides.","images":[],"step":11}]', '["gluten","peanuts","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Malaysian"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","curry-recipes","dietary","gluten-free-recipes","main-dishes","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9064b7108256', 'en', 'US', 'Mongolian Lamb', 'Recipe video above. At “posher” establishments, Mongolian Lamb arrives at the table on a hot iron plate, sizzling and spitting for theatric effect. Sizzle aside, this homemade version is a near perfect replica. Even the velveted texture of the lamb!The sauce is sweet and savoury, with Chinese Five Spice and Hoisin the dominant flavours. It''s completely addictive!Also excellent made with beef - see Note 1.', 'https://www.recipetineats.com/tachyon/2020/08/Mongolian-lamb_9.jpg', 15, 10, 25, 4, '[{"id": "ing_lamb", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.005, "unit": "tub of 200g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.05, "unit": "pack of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.09, "unit": "bottle of 500ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 0.18, "unit": "bottle"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 4.0, "unit": "bunch"}}]', '[{"ingredients":["350g / 12 oz lamb meat (backstrap/fillet, mid loin chops, shoulder - or any cut in Note 1)","1/2 tsp baking soda (bicarb soda) (tenderiser, Note 2)","1 tsp cornflour / cornstarch","1 tbsp light soy sauce (or all purpose, Note 3)","1 tbsp Chinese cooking wine (Note 4 subs)"],"purpose":"Lamb and marinade:"},{"ingredients":["3 tsp cornflour / cornstarch","2 tsp dark soy sauce (Note 3)","1 tsp light soy sauce (or all purpose, Note 3)","1 1/2 tsp Sambal Oelak or other chilli paste (or omit for no spice)","3 tbsp hoisin sauce (I used Lee Kum Kee brand)","2 tbsp Chinese cooking wine (Note 4 subs)","1/4 tsp Chinese five spice powder (Note 5)","3/4 cup water","1 tsp sesame oil (, toasted (Note 6))"],"purpose":"Sauce:"},{"ingredients":["2 tbsp vegetable oil (or canola or peanut)","1 large onion (, cut into large 2.5cm / 1\" squares)","2 cloves garlic (, finely chopped)","4 green onions (, cut into 5cm/2\" lengths)"],"purpose":"Stir fry:"}]', '[{"description":"Tenderise Lamb:","images":[],"step":1},{"description":"Combine lamb and marinade ingredients, mix very well. Cover and refrigerate to marinate and tenderise the lamb.","images":[],"step":2},{"title":"Marinate 2 hours","description":"Backstrap, Midloin chops and other listed Tender Cuts in Note 1.","images":[],"step":3},{"title":"Marinate 24 hours","description":"lamb shoulder and other listed Economical Cuts in Note 1. (Bare minimum marinade times is 6 hrs).","images":[],"step":4},{"description":"Cooking:","images":[],"step":5},{"title":"Sauce","description":"Mix cornflour with the soy sauces, then mix in the remaining sauce ingredients. (Note 7)","images":[],"step":6},{"title":"Cook onion","description":"Heat oil over high heat in a wok or heavy based skillet. Add onions, and stir fry for 30 seconds until starting to colour. Add garlic and toss through quickly.","duration":0.5,"images":[],"step":7},{"title":"Cook Lamb","description":"Add lamb and cook for 3 minutes until most of it changes from red to brown, and some pieces start getting nice golden brown surfaces.","duration":3,"images":[],"step":8},{"title":"Add Sauce","description":"Add green onions, stir for 30 seconds (meat should all now be brown), then add Sauce. Stir and let simmer for 1 - 2 minutes until thickened.","duration":0.5,"images":[],"step":9},{"description":"Serve with rice!","images":[],"step":10}]', '["fish","gluten","peanuts","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","lamb","lamb-recipes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_97919cb57f33', 'en', 'US', 'Built-to-last CRISPY Honey Chicken', 'Recipe video above. This recipe brings together a plethora of Asian cooking secrets for a crispy chicken that stays crispy for 4+ hrs even after tossing with sauce:1. Double coating - dredge in cornflour/cornstarch followed by batter2. Cold batter made with soda water = crispier chicken that''s puffy and light, not dense and greasy3. Cornflour/cornstarch + flour batter - cornflour for ultra crispiness, flour for golden colour + baking powder lift4. Double fry for extra long lasting, thicker crispiness AND less greasy (Asian secret!)5. No-Soggy Sauce - glucose or corn syrup to make it "candy like" to stick on chicken crust rather than soaking in, plus NO WATER in the sauce.See Notes for make ahead (99% like freshly made).', 'https://www.recipetineats.com/tachyon/2020/08/Honey-Chicken_0.jpg', 20, 30, 50, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.04, "unit": "bottle of 500ml"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.562, "unit": "tub of 200g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.003, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.002, "unit": "jar of 500g"}}, {"id": "ing_corn", "quantity": {"value": 0.056, "unit": "can of 400g"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.067, "unit": "pack of 375g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["300g/ 10oz chicken thighs (, skinless boneless, cut into 2.5cm/1\" pieces (Note 1))","1 tbsp light soy sauce (or all purpose, NOT dark soy)","2 tsp Chinese cooking wine (sub with soy)","2 tsp cornflour/cornstarch"],"purpose":"Chicken & Marinade:"},{"ingredients":["1/2 cup cornflour/cornstarch"],"purpose":"Dredging:"},{"ingredients":["6 tbsp cornflour/cornstarch (Note 8)","4 tbsp flour (, plain/all purpose)","7 - 8 tbsp COLD soda water, club soda or seltzer water (NOT sparkling mineral water, Note 2)","1/4 tsp baking powder (NOT baking soda)","1/4 tsp salt (, kosher/cooking (halve for table salt))"],"purpose":"Stay-Crispy Puffy Batter:"},{"ingredients":["2 - 3 cups vegetable oil (or canola)"],"purpose":"Oil, for frying:"},{"ingredients":["1/3 cup (100g) honey","1.5 tbsp (25g) glucose OR corn syrup (light) (Note 6)","1 tbsp light soy sauce (or all purpose)","2 tsp Chinese cooking wine (or more soy sauce)"],"purpose":"Honey Sauce (Note 8 on sweetness):"},{"ingredients":["25g / 2 oz Vermicelli rice noodles (optional) (, a wad of it (not bean noodles, must be rice noodles))","Sesame seeds, finely sliced green onions"],"purpose":"Garnish / serving:"}]', '[{"description":"Recommended step for beginners:","images":[],"step":1},{"description":"Place batter mixing bowl in the fridge with the flour, baking powder and salt. (Helps keep batter cold = crispier chicken)","images":[],"step":2},{"description":"Marinate & Dust Chicken:","images":[],"step":3},{"title":"Marinade","description":"Mix Chicken and Marinade in a bowl. Refrigerate for 30 minutes.","duration":30,"images":[],"step":4},{"title":"Dust","description":"Spread the 1/2 cup cornflour/cornstarch on a shallow plate. Scatter over about 8 to 10 chicken pieces, toss to coat, shake off excess, put on a plate. Repeat with all chicken.","images":[],"step":5},{"description":"Cold Batter & Fry #1:","images":[],"step":6},{"title":"Rack","description":"Place a rack on a tray (for draining, Note 3)","images":[],"step":7},{"title":"Heat oil","description":"Fill small pot or large saucepan with 4cm / 1.7\" oil. Heat to 180°C/350°F on medium high stove (or until chicken starts sizzle straight away when dipped).","images":[],"step":8},{"title":"Make Cold Batter","description":"Whisk together flour, cornflour/cornstarch, baking powder and salt. Pour in 7 tbsp soda water, then do minimum whisks just to combine (10 or so) - few lumps ok, better than whisking too much (changes coating texture).","images":[],"step":9},{"title":"Batter thickness","description":"should fully coat chicken easily, not be see through, but not thick and heavy - see video at 44 seconds. Use extra water 1 teaspoon at a time to achieve right thickness.","images":[],"step":10},{"title":"Dredge","description":"Drop 8 or so pieces of chicken into the batter. Turn to coat, then carefully place in oil.","images":[],"step":11},{"title":"Fry #1","description":"Cook for 3 minutes until light golden and crispy - when you pick them up, you can tell it''s very crispy.","duration":3,"images":[],"step":12},{"title":"Drain & repeat","description":"Place on rack, repeat with remaining chicken - I cook in 4 batches, don''t crowd the pot, brings oil temperature down too much.","images":[],"step":13},{"description":"Cool chicken for 20 minutes (Note 4). Meanwhile, make Sauce.","duration":20,"images":[],"step":14},{"description":"Place ingredients in a large saucepan over medium heat. Bring to simmer, then leave to simmer for 3 minutes.","duration":3,"images":[],"step":15},{"description":"Consistency should be like maple syrup (video at 1 min 11 sec). Turn off stove, place lid on to keep warm (when cool, gets too thick to toss chicken).","images":[],"step":16},{"title":"Fry #2","description":"for ultra crispy!","images":[],"step":17},{"description":"Heat oil to 200°C/390°F.","images":[],"step":18},{"description":"Add in half the chicken (you can crowd the pot for Fry #2). Cook for 90 seconds until it changes from pale golden to very golden (but not dark golden, chicken will overcook), then remove onto rack. More golden = crispier chicken.","duration":1.5,"images":[],"step":19},{"title":"Repeat with remaining chicken. (Feel the chicken","description":"you can tell it''s built-to-last crispy!)","images":[],"step":20},{"description":"Toss in Sauce & Serve:","images":[],"step":21},{"description":"Tumble into saucepan with sauce, use rubber spatula to quick toss until coated with sauce. (Sauce starts thickening if you take too long, so be quick!)","images":[],"step":22},{"description":"Pile chicken up over crispy noodles (if using), scatter with sesame seeds and green onion and serve!","images":[],"step":23},{"description":"Puffy Crispy Noodles (optional):","images":[],"step":24},{"description":"At any point while oil is hot, drop wad of noodles into hot oil, wait 3 seconds until it puffs up, then remove with tongs.","images":[],"step":25},{"description":"Drain on paper towels, place on plate to top with chicken!","images":[],"step":26}]', '["gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken","chicken-breast-recipes","chicken-recipes","chinese-recipes","deep-fried-recipes","iconic-dishes","mains","modern-asian"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6437007c7815', 'en', 'US', 'Sweet and Sour Pork', 'Recipe video above. The best ever Sweet and Sour Pork recipe is loaded with tricks the Chinese have been using for centuries: double dredgeand double fry for extra crispy, cornflour instead of flour, economical pork used for juiciness, but tenderised with baking soda so you''d swear they''re pricey chops, and a sauce that''s not sickeningly sweet. Don''t let the list of ingredients daunt you. There''s a lot of repeat ingredients!OVEN option provided in notes. Because sometimes, you just have to....', 'https://www.recipetineats.com/tachyon/2020/08/Sweet-and-Sour-Pork_6.jpg', 20, 30, 50, 5, '[{"id": "ing_pork", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.01, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.015, "unit": "tub of 200g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 1.0, "unit": "bottle of 500ml"}}, {"id": "ing_pineapple", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_ketchup", "quantity": {"value": 0.18, "unit": "bottle of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_flour", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_pineapple", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["400g/14oz pork scotch roast (aka pork neck, collar butt) or shoulder / butt, (cut into 2cm / 4/5\" cubes (Note 1))","1/2 onion (, finely grated (Note 2a))","1 tsp garlic (, finely grated (Note 2a))","1 tsp ginger (, finely grated (Note 2a))","3/8 tsp baking soda (bi-carb) (Note 2b)","2 tsp cornflour/cornstarch","2 tbsp light soy sauce (, or all purpose (Note 3))"],"purpose":"Tenderised Marinated Pork:"},{"ingredients":["5 tbsp cornflour/cornstarch ( - for mixing in)","1/2 cup cornflour/cornstarch ( - for Coating)","2 - 3 cups vegetable or canola oil"],"purpose":"For frying:"},{"ingredients":["1/3 cup white sugar","1/3 cup apple cider vinegar (or 1/4 cup normal white vinegar)","3 tbsp pineapple juice (from a 227g/8oz can pineapple pieces in juice, preferably no added sugar, Note 4)","3 tbsp ketchup (or Aussie tomato sauce)","1/2 tsp Worcestershire sauce","1 tbsp soy sauce (, light)","1 tsp Oyster Sauce (Note 5)","4 tsp cornflour/corn starch","1/2 cup water"],"purpose":"Sweet & Sour Sauce:"},{"ingredients":["1 tbsp oil","1 garlic clove (, finely chopped)","2 tsp ginger (, finely chopped)","1 onion (medium), cut into 2.5cm/ 1\" cubes (brown, white, yellow)","1/2 red capsicum/bell pepper ((large), cut into 2.5cm / 1\" cubes)","1/2 green capsicum/bell pepper ((large), cut into 2.5cm / 1\" cubes)","1 cup pineapple pieces (from the can of pineapple under Sauce)"],"purpose":"Stir Frying:"}]', '[{"description":"Mix Pork with Marinade. Marinade 18 to 24 hours. (See Note 1 for marinating time for other cuts)","images":[],"step":1},{"title":"Rack & warm oven","description":"Preheat oven to 80°C/175°F and place rack on tray - to keep pork warm.","images":[],"step":2},{"title":"Sauce","description":"Place all Sauce ingredients EXCEPT water in a large jug or small bowl. Mix until combined, then mix in water.","images":[],"step":3},{"title":"Be Stir Fry Ready","description":"Have all ingredients lined up, ready to toss in. After Fry #2, things move quickly.","images":[],"step":4},{"title":"Coating #1","description":"Mix 5 tablespoons cornflour into the pork and leave for 5 minutes. At first, it will be white from the cornflour, but after a while it will sweat and make the cornflour (mostly / partially) wet, and will be sticky (this is key for coating to stick).","duration":5,"images":[],"step":5},{"title":"Coating #2","description":"Spread 1/2 cup cornflour in a shallow bowl. Coat pork, shaking off excess, and pile onto a plate.","images":[],"step":6},{"description":"Reserve cornflour in case you need to dust again just prior to frying. Pork should be at least half white when you put it into the oil (if not, just sprinkle with reserved cornflour).","images":[],"step":7},{"description":"Fried Crispy Pork (Note 6 for oven):","images":[],"step":8},{"title":"Heat oil","description":"Pour enough oil into a large saucepan or small pot so it''s 2.5cm / 1\" deep. Heat to 180°C/350°F (or until pork immediately starts sizzling when you dip it in).","images":[],"step":9},{"title":"Fry #1","description":"Cook pork in batches, being sure not to crowd the pot, for 3 minutes until golden. Drain on rack. This step is just to cook the pork. It takes me 4 batches.","duration":3,"images":[],"step":10},{"title":"Fry #2","description":"Turn the stove up slightly and heat oil to 200°C/390°F. Starting with the coolest pork, add half the pork (you can crowd the pot) and cook for 1 1/2 minutes, or until pork is deep golden brown and crispy. Transfer to rack, repeat with remaining pork - I do 2 batches.","images":[],"step":11},{"description":"Keep warm in oven.","images":[],"step":12},{"description":"Sauce & Stir Fry:","images":[],"step":13},{"description":"Heat oil in a very large skillet over high heat.","images":[],"step":14},{"description":"Add garlic, ginger and onion, stir for 1 1/2 minutes. Add capsicum and stir for 2 minutes.","duration":2,"images":[],"step":15},{"description":"Add Sauce & pinapple, then let it come to a rapid simmer. Simmer for 2 minutes until it thickens - when you drag the spoon across the base, a path should briefly appear (see video at 1 min 53 s).","duration":2,"images":[],"step":16},{"title":"10 second toss","description":"Add pork, then QUICKLY toss to coat - aim for 10 seconds!","duration":0.16666666666666666,"images":[],"step":17},{"description":"Serve asap! Pour onto serving plate, serve immediately! Will stay crispy for around 5 minutes then starts softening but still has a solid coating. This is just the reality of Sweet and Sour Pork, even at restaurants!","images":[],"step":18}]', '["gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","deep-fried-recipes","modern-asian","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4d2ed32f7ebe', 'en', 'US', 'Chicken Broccoli Stir Fry (extra sauce!)', 'Recipe video above. Big batch stir fry made with chicken and broccoli, and lots and lots of sauce - because broccoli florets hold lots of sauce but I still want some to soak my rice!This sauce uses the minimum ingredients you can get away with but still make something that stacks up to real Chinese take out. Chinese cooking wine (shoaxing wine) is the restaurant secret - just a small splash adds depth of flavour into the sauce.Shortcut using Charlie - see Note 5 (the sauce in this recipe is basically Charlie!).', 'https://www.recipetineats.com/tachyon/2020/07/Chicken-Broccoli-Stir-Fry_2.jpg', 10, 6, 16, 5, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.01, "unit": "tub of 200g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.075, "unit": "pack of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 2.0, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_broccoli", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["500g/1 lb chicken breast, thinly sliced (or boneless thighs, do not tenderise)","1 1/2 tsp baking soda / bi-carb soda (Note 1)"],"purpose":"Tenderised chicken (Note 1)"},{"ingredients":["2 tbsp cornflour/cornstarch","3 tbsp light soy sauce (, or all purpose soy (Note 2))","1 1/2 tbsp Chinese cooking wine (shaoxing wine) or Mirin (Note 3)","3 tbsp oyster sauce (Note 4)","2 tsp sesame oil (, toasted (Note 5))","Dash of white pepper (sub black)"],"purpose":"Sauce (Note 6 for using Charlie all-purpose stir fry):"},{"ingredients":["2 tbsp oil (, peanut, vegetable or canola)","1/2 onion (, sliced)","2 garlic cloves (, finely minced with knife)","400g/ 14 oz broccoli florets (, broken/cut into small bite size pieces (2 medium heads, ~5 cups))","1 1/4 cups water"],"purpose":"Stir Fry:"},{"ingredients":["White rice (or other rice of choice)"],"purpose":"For serving:"}]', '[{"title":"Tenderise chicken","description":"Consider tenderising chicken breast using this method. (Not needed for thigh)","images":[],"step":1},{"title":"Broccoli","description":"steam or boil using preferred method until cooked to your taste (it won''t cook any further in the stir fry). I usually microwave steam 3 minutes on high. Drain well (waterlogged florets = diluted sauce).","images":[],"step":2},{"title":"Sauce","description":"Mix cornflour and soy sauce until lump free, then mix in remaining ingredients.","images":[],"step":3},{"title":"Cook aromatics","description":"Heat oil in a large skillet over high heat. Add garlic and onion, stir for 10 seconds until garlic starts to go golden.","duration":0.16666666666666666,"images":[],"step":4},{"title":"Cook chicken","description":"Add chicken and cook for 2 minutes or until the chicken is just cooked through.","duration":2,"images":[],"step":5},{"title":"Thicken sauce","description":"Add broccoli, Sauce and water. Stir well and cook for 1 to 2 minutes until the Sauce thickens and becomes glossy, and coats the ingredients.","duration":1.5,"images":[],"step":6},{"description":"Serve over rice!","images":[],"step":7}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese","Asian","Chinese"],"categories":["asian-recipes","broccoli-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_399afb02c305', 'en', 'US', 'Gado Gado (Indonesian Salad with Peanut Sauce)', 'Recipe video above. Fun to say, delicious to eat, the Gado Gado peanut sauce will make any vegetables into a big, healthy, tasty meal! Use any veg you want - the ones I''ve used are in the spirit of traditional Indonesian Gado Gado. Using Thai Red Curry Paste is an effective shortcut - it uses a lot of the ingredients used in Gado Gado sauce. Saves time, effort and money!All the veg can be warm or at room temp, so cook them first. Tempeh/tofu is best hot and crispy fresh out of the skillet.', 'https://www.recipetineats.com/tachyon/2020/06/Indonesian-Gado-Gado.jpg', 15, 15, 30, 2, '[{"id": "ing_peanut_butter", "quantity": {"value": 0.003, "unit": "jar of 375g"}}, {"id": "ing_red_curry_paste", "quantity": {"value": 0.08, "unit": "bottle"}}, {"id": "ing_kecap_mani", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ime_juice", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.003, "unit": "can of 400ml"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_beansprouts", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 200.0, "unit": "bag of 2kg"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_egg", "quantity": {"value": 0.208, "unit": "carton of 12"}}, {"id": "ing_shrimp", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_tempeh", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_peanuts", "quantity": {"value": 0.037, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1/3 cup natural peanut butter, smooth or crunchy (your choice) (Note 1)","4 tsp red curry paste (, store bought (Maesri brand best, Note 2))","3 tsp Kecap Manis (Indonesian sweet soy sauce, Note 3)","1 tsp sambal oelak or other chilli paste (adjust spiciness to taste)","1/2 tsp salt","1 large garlic clove (, pressed using garlic press (~ 3/4 tsp))","1 1/2 tbsp lime juice (Note 4)","1/2 cup coconut milk (, full fat (Ayam brand best))","1/2 cup water"],"purpose":"Gado Gado Sauce:"},{"ingredients":["1 bunch spinach (, roots trimmed)","4 cups beansprouts","200g / 7 oz potato ( - small halved, large peeled chopped 2 cm / 1\" cubes OR 1.5cm / 1/2\" slices)","1 cucumber (, sliced on the diagonal ( or 1/2 long cucumber ie Telegraph/English))","2 - 3 boiled eggs (, peeled and halved)","15 prawn crackers (, optional (Note 6))"],"purpose":"Salad (use any veg, Note 5):"},{"ingredients":["2 tbsp vegetable or peanut oil","200g / 7 oz tempeh (or firm tofu, Note 7)"],"purpose":"Crispy Tempeh (or tofu):"},{"ingredients":["1 tbsp finely chopped peanuts (highly recommended)","Red chilli (, finely sliced, optional (small = spicy, large = less spicy))"],"purpose":"Garnishes:"}]', '[{"description":"Gado Gado Peanut Sauce:","images":[],"step":1},{"description":"Mix all ingredients in a small saucepan over medium low heat. Bring to simmer then cook for 5 minutes, stirring regularly so the bottom doesn''t catch, until it thickens. If too thick, just add more water - should be able to drizzle it (see video for thickness).","duration":5,"images":[],"step":2},{"title":"Taste and adjust as follows","description":"lime for more sour, salt, sugar for sweet.","images":[],"step":3},{"description":"Cover and keep warm.","images":[],"step":4},{"description":"Blanched Vegetables:","images":[],"step":5},{"description":"Bring a saucepan of water to the boil.","images":[],"step":6},{"description":"Add potatoes and cook for 5 minutes or until cooked through. Use a slotted spoon to transfer to colander to drain.","duration":5,"images":[],"step":7},{"description":"Cook beansprouts for 3 minutes or until just wilted. Transfer to colander, press out excess water.","duration":3,"images":[],"step":8},{"title":"Add spinach, push under to submerge","description":"will instantly wilt. Remove, transfer to colander, press out excess water.","images":[],"step":9},{"description":"Crispy tempeh or tofu:","images":[],"step":10},{"description":"Slice into 0.75 x 5 cm / 1/3 x 2\" slices (or thereabouts).","images":[],"step":11},{"description":"Heat oil in a skillet over medium high heat. Cook tempeh 2 min on each side until deep golden and crispy. (Tofu ~ 1 1/2 min)","images":[],"step":12},{"description":"Either make one platter for sharing, or individual. Vegetables and egg can be served warm or at room temp, sauce should be served warm (it thickens when cool).","images":[],"step":13},{"description":"Place vegetables and tempeh on serving plate, top with egg.","images":[],"step":14},{"description":"Pour sauce into serving bowl.","images":[],"step":15},{"description":"Serve Gado Gado Salad with peanut sauce, peanuts for sprinkling, fresh chillies and prawn crackers on the side.","images":[],"step":16}]', '["egg","gluten","peanuts","shellfish","soy"]', '["high_protein"]', '{"mealType":["dinner","lunch"],"cuisine":["Bali","Indonesian"],"categories":["asian-recipes","modern-asian","salad-recipes-main-course","sauces","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f0b300af633a', 'en', 'US', 'Mie Goreng (Mee Goreng)', 'Recipe video above. These noodles tossed in a sticky savoury sweet sauce originates from Indonesia but is also popular in Malaysia. With chicken, prawns, vegetables and the signature egg ribbons, it''s pretty fully loaded! They''re commonly made by street vendors with instant noodles which give it the familiar crinkly noodle look, but feel free to use any noodles you want. (PS Ketchup is authentic!)', 'https://www.recipetineats.com/tachyon/2020/02/Mie-Goreng_5.jpg', 15, 10, 25, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 3.0, "unit": "pack of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_kecap_mani", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_ketchup", "quantity": {"value": 0.12, "unit": "bottle of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_beansprouts", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}]', '[{"ingredients":["3 instant noodle cakes (I use this)","250g/8oz fresh egg noodles (, thin to medium)","150g / 5oz dried egg noodles (, thin to medium)"],"purpose":"Noodles – use ONE (Note 1):"},{"ingredients":["2 tbsp kecap manis (or dark sweet soy sauce) (Note 2)","2 tsp light soy sauce (or normal soy, Note 3)","2 tsp dark soy sauce (, or more light soy sauce (Note 3))","1 tbsp oyster sauce (Note 4)","2 tbsp ketchup (yes really!)","1 tsp sambal oelak, chilli paste or Sriracha (adjust spiciness to taste)","2 tsp sesame oil"],"purpose":"Sauce:"},{"ingredients":["2 tbsp vegetable oil","2 eggs (, lightly whisked)","3 garlic cloves (, finely chopped)","120g/4oz chicken breast or thigh (, sliced thinly into small bite size pieces)","100g/3.5oz prawns/shrimp (, raw, peeled and deveined (smaller are better))","2 cups cabbage (, finely sliced (any green or white cabbage))","1 cup beansprouts","3 green onions (, cut into 5cm/2\" lengths (green and white part))"],"purpose":"Stir Fried Noodles:"}]', '[{"description":"Mix the Sauce in a bowl.","images":[],"step":1},{"description":"Prepare noodles per packet directions just before cooking.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a large skillet over medium heat. Pour in egg, swirl to coat base. Cook 1 minute until mostly set, then flip (do your best!).","images":[],"step":3},{"description":"Slide onto cutting board, roll up into loose \"wrap\". Slice into 1cm/ 1/3\" thick pieces - you now have egg ribbons!","images":[],"step":4},{"description":"Cooking:","images":[],"step":5},{"description":"Heat remaining 1 tbsp oil in same skillet over HIGH heat.","images":[],"step":6},{"description":"Add garlic and chicken, cook until half surface turns white.","images":[],"step":7},{"description":"Add prawns and cook for 1 minute until chicken is mostly cooked.","duration":1,"images":[],"step":8},{"description":"Add cabbage and bean sprouts, toss for 1 minute until a bit wilted.","duration":1,"images":[],"step":9},{"title":"Add noodles, green onions and Sauce, toss for 1","description":"2 minutes until Sauce reduces and noodles caramelise a bit.","duration":1.5,"images":[],"step":10},{"description":"Toss through egg ribbons and serve immediately!","images":[],"step":11}]', '["egg","gluten","sesame","shellfish","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Indonesian","Malaysian"],"categories":["asian-recipes","noodles"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f78cce541191', 'en', 'US', 'Momofuku Bossam (Korean Slow Cooked Pork Shoulder Roast)', 'Recipe video above. This is David Chang''s famous Momofuku Bossam (or Bo ssam), his take on the traditional Korean pork dish that costs US$250 at his NYC restuarant! Pork shoulder is dry cured so it''s seasoned from end to end, then slow roasted until fall apart tender and finished with a brown sugar crust. Serve with condiments for DIY lettuce wraps for an epic eating experience that will be remembered for years to come!', 'https://www.recipetineats.com/tachyon/2020/02/Momofuku-Bossam-Korean-Slow-Cooked-Pork-Shoulder_1-1.jpg', 10, 300, 1450, 10, '[{"id": "ing_pork", "quantity": {"value": 3.75, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.105, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.5, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_ssamjang", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_gochujang", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lettuce", "quantity": {"value": 4.5, "unit": "head"}}, {"id": "ing_white_rice", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_kimchi", "quantity": {"value": 500.0, "unit": "unit"}}, {"id": "ing_oysters", "quantity": {"value": 0.06, "unit": "kg"}}]', '[{"ingredients":["3.5-4 kg/ 7-8 lb pork butt / shoulder (, bone in & skinless (Note 1))","1/2 cup (110g) white sugar","1/2 cup (115g) kosher or cooking salt (NOT table salt) (Note 2)"],"purpose":"Slow Cooked Pork:"},{"ingredients":["1 tbsp kosher or cooking salt (NOT table salt) (Note 2)","7 tbsp brown sugar (, light or normal (not dark))"],"purpose":"Brown Sugar Crust:"},{"ingredients":["2.5 cups scallions (, thinly sliced (both green and white parts, ~5-6 stems))","1/2 cup fresh ginger (, peeled and finely grated (Note 3))","1/3 cup canola oil (Note 4)","1.5 tsp light soy sauce (or all purpose, not dark soy sauce Note 5)","1 teaspoon sherry vinegar (Note 6)","1/2 tsp kosher or cooking salt (, to taste (Note 2))"],"purpose":"Ginger Shallot Sauce:"},{"ingredients":["2 tbsp ssamjang (Note 8)","1 tbsp gochujang (Note 8)","5 tsp sherry vinegar (Note 6)","2 tbsp canola oil (Note 4)","1 tbsp water","1 tsp white sugar"],"purpose":"Spicy Ssam Sauce (Note 7):"},{"ingredients":["4 - 5 heads butter/bib lettuce (40 - 50+ leaves, Note 9)","3 cups cooked white rice","500g/1lb kimchi","12 + oysters (, raw, in shell (optional, Note 10))"],"purpose":"Serving:"}]', '[{"description":"Bossam Slow Cooked Pork:","images":[],"step":1},{"description":"Mix sugar and salt together. Pat pork dry. Coat pork in sugar salt mixture, getting it into all the crevices. Rub/pat well to adhere as best you can - discard excess salt unused/falls off (usually ~ 2-3 tbsp).","images":[],"step":2},{"description":"Place in a glass dish (Note 13), cover loosely with cling wrap and refrigerated 24 - 36 hours (Note 11).","images":[],"step":3},{"description":"Preheat oven to 150°C/300°F (all oven types) with rack in the middle of oven.","images":[],"step":4},{"title":"Remove pork from fridge","description":"surface will be wet. Either transfer pork to clean pan (metal, ceramic or glass) or drain off excess liquid / scrape out salt/sugar in same glass pan. Do not rinse pork.","images":[],"step":5},{"description":"Roast 5 hours (Note 12), uncovered, spooning over pan juices once each hour, until you can easily pull the meat apart with 2 forks (check on side).","images":[],"step":6},{"description":"Remove from oven, rest for 10 minutes (up to 1 hour is fine, loosely cover in foil).","duration":10,"images":[],"step":7},{"description":"Turn oven up to 260°C/500°F (all oven types).","images":[],"step":8},{"description":"Brown Sugar Crust:","images":[],"step":9},{"description":"Mix brown sugar and salt.","images":[],"step":10},{"description":"Spoon juices all over pork.","images":[],"step":11},{"description":"Spoon sugar onto pork and use your hands to make it stick to the top and sides (not underneath). Make layer on top as even as you can (for even caramelisation).","images":[],"step":12},{"description":"Place in oven for 10 minutes until surface is a deep golden crust, sugar is bubbling and caramelised (see VIDEO!). Keep a close eye on it from 5 minutes. If the highest points start getting black, cover with small piece of foil (just stick it on).","duration":10,"images":[],"step":13},{"description":"Remove from oven and transfer to serving platter for serving. (Don''t use pan juices, it will be salty from brine)","images":[],"step":14},{"title":"Ginger Shallot Sauce","description":"Mix ingredients in bowl and stand for 20 minutes to let it soften.","duration":20,"images":[],"step":15},{"title":"Ssam Sauce","description":"Mix ingredients together. Oil will naturally separate over time if sauce is left to stand, just mix again to reincorporate.","images":[],"step":16},{"description":"Place pork on serving platter with lettuce, oysters, kimchi, rice, Ginger Shallot Sauce and Ssam Sauce on the side.","images":[],"step":17},{"title":"Attack the pork","description":"it will shred easily. Shred as much or little as you want, let people do it themselves or you can do it for them. Prepare to fight over the epic crust.","images":[],"step":18},{"description":"To eat, place lettuce in hand. Spoon in some rice, top with pulled pork, small piece of kimchi, oyster, some ginger shallot sauce then finally a little drizzle of spicy Ssam sauce.","images":[],"step":19},{"description":"Bundle up, bite and enjoy!","images":[],"step":20}]', '["gluten","milk","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Korean","Modern Asian"],"categories":["asian-recipes","dietary","gluten-free-recipes","iconic-dishes","korean-recipes","main-dishes","modern-asian","pork-recipes","roasts","slow-cooked-fall-apart"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8af630ad60ee', 'en', 'US', 'Siu Mai (Shumai - Chinese Steamed Dumplings)', 'Recipe video above. Siu Mai is the first thing you grab off the trolleys when you descend upon your favourite Yum Cha. And now you can get your Siu Mai fix on demand! These Chinese steamed dumplings are filled with a classic pork and prawn filling. Serves 2 - 3 as a main meal, or more as part of a larger spread. Also see Japanese Shumai (smaller, topped with peas!)', 'https://www.recipetineats.com/tachyon/2020/02/Siu-Mai_Chinese-steamed-dumplings_3.jpg', 30, 8, 38, 20, '[{"id": "ing_shiitake_mushrooms", "quantity": {"value": 3.0, "unit": "pack of 150g"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_shrimp", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 1.875, "unit": "carton of 12"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.05, "unit": "kg"}}]', '[{"ingredients":["3 dried shiitake mushrooms (, soaked in boiling water, finely chopped (Note 1))","350g/ 13oz pork mince (ground pork) (, fatty (Note 2))","3/4 tsp salt","2.5 tsp sugar","1 tsp light soy sauce (Note 4)","1.5 tbsp Chinese cooking wine (aka Shaoxing wine, sub Mirin or dry sherry) (Note 5)","150g/5oz prawns/shrimp (, peeled and deveined, chopped 0.5cm / 1/5\" (Note 3))","2 tbsp white part of green onions (, finely minced (Note 6))","20 - 25 wonton wrappers / egg wrappers (8cm/3.5\" squares or rounds (Note 7))"]},{"ingredients":["50g/1.5oz flying fish roe (Note 8 for alternatives)"],"purpose":"Garnish:"}]', '[{"description":"Place pork, salt, soy sauce, rice wine, sugar with the pork meat/mince in a large mixing bowl. Mix vigorously with a spoon or use your hands until it becomes pasty (initially it will be crumbly) - about 30 seconds.","images":[],"step":1},{"description":"Add mushrooms, prawns and green onions, mix until just dispersed (don''t crush the prawn meat).","images":[],"step":2},{"description":"Making Siu Mai (process steps and video helpful!):","images":[],"step":3},{"description":"Form an \"O\" with your forefinger and thumb.","images":[],"step":4},{"description":"Place a wonton wrapper over the \"O\". Push in 1 heaped teaspoon of Filling and push down into the \"O\" hole.","images":[],"step":5},{"description":"Use a butter knife to smear more Filling into until level with edge of wonton.","images":[],"step":6},{"description":"Place on work surface and push down to flatten base and use fingers to shape into a round.","images":[],"step":7},{"description":"Steaming Dumplings:","images":[],"step":8},{"description":"Line a 30cm/12\" bamboo steamer (or stove steamer) with baking paper with holes in it (Note 9)","images":[],"step":9},{"description":"Fill a wok big enough to hold steamer with about 2 cups of water (Note 10). Bring to rapid simmer over medium high heat.","images":[],"step":10},{"title":"Place Siu Mai in steamer (20","description":"25 fits). Place lid on, place on wok over simmering water.","images":[],"step":11},{"description":"Steam 8 minutes, or until internal temperature of dumplings is 75°C/165°F. (If yours are bigger due to larger wonton wrappers are bigger, they will take longer).","images":[],"step":12},{"description":"Remove steamer from wok. Remove lid and place a tiny bit of roe in the middle of each dumpling.","images":[],"step":13},{"description":"Serve immediate with dipping sauce!","images":[],"step":14},{"description":"Siu Mai Dipping Sauce:","images":[],"step":15},{"description":"Provide soy sauce, Chinese black vinegar or normal white vinegar, Chinese chilli paste (or Sriracha or other chilli). Let people mix their own to their taste (I do: 3 parts soy, 1 part vinegar, as much chilli as I think I can handle).","images":[],"step":16}]', '["egg","fish","gluten","shellfish","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["snack","dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chinese-recipes","dumplings","iconic-dishes","modern-asian","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_14e5bd3dff07', 'en', 'US', 'Dan Dan Noodles', 'Recipe video above. The iconic spicy Sichuan Dan Dan Noodles, made at home! Am intensely flavoured spicy sesame chilli oil sauce tossed with noodles and pork. Don''t be daunted by the list and steps, there''s no need to rush. Cook and prepare all the parts except the noodles. Cook the noodles just before serving so they''re piping hot because the idea is to toss hot noodles with the pork and sauce so the heat warms everything else up. That''s the Dan Dan way!', 'https://www.recipetineats.com/tachyon/2020/02/Dan-Dan-Noodles_4-2.jpg', 15, 15, 30, 4, '[{"id": "ing_sesame_seeds", "quantity": {"value": 0.06, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 0.045, "unit": "pack of 100g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.24, "unit": "bottle of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 0.005, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 0.09, "unit": "pack of 100g"}}, {"id": "ing_chicken", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 0.04, "unit": "bottle"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_sui_mi_ya_cai", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_stems_choy_sum", "quantity": {"value": 16.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_peanuts", "quantity": {"value": 0.037, "unit": "jar"}}]', '[{"ingredients":["2 tbsp Chinese sesame paste (sub tahini, Note 1)","1.5 tbsp Chinese chilli paste in oil (, adjust spiciness (Note 2))","4 tbsp light soy sauce (Note 3)","2 garlic cloves (, minced)","3 tsp white sugar","1/2 tsp Chinese five spice powder (Note 4)","1 tsp Sichuan pepper powder (, preferably freshly ground (Note 5))","3 tbsp (or more!) chilli oil (, preferably Chinese (Note 6))","3/4 cup (185ml) chicken broth/stock (, hot, low sodium)"],"purpose":"Dan Dan Sauce:"},{"ingredients":["2 tsp Hoisin sauce","1 tsp dark soy sauce (Note 7)","1 tbsp Chinese cooking wine (sub 2 tbsp extra chicken stock)","1/2 tsp Chinese five spice powder (Note 4)","1 tbsp vegetable oil","250g/ 8oz pork mince (ground pork)"],"purpose":"Pork topping:"},{"ingredients":["1 tsp vegetable oil","30g (1/4 cup) Sui Mi Ya Cai (preserved mustard greens) (, finely chopped (Note 8))"],"purpose":"Sui mi ya cai (preserved mustard greens):"},{"ingredients":["500g/1lb white fresh noodles (, medium thickness (Note 9))","16 choy sum stems (, cut into 15cm pieces)","2 green onions (, finely sliced)","1 tbsp peanuts (, finely chopped (optional))"],"purpose":"To serve:"}]', '[{"description":"Mix all ingredients except oil and chicken stock. Then gently stir in oil and stock - oil should be sitting on surface. Set aside.","images":[],"step":1},{"description":"Mix together hoisin, soy, Chinese wine and five spice (\"Sauce\").","images":[],"step":2},{"description":"Heat oil in a skillet or wok over high heat. Add pork and cook, breaking it up as you, until it changes from pink to white. Add Sauce and cook for 1 minute, then transfer into a bowl.","duration":1,"images":[],"step":3},{"description":"Sui mi ya cai (preserved mustard greens):","images":[],"step":4},{"description":"Return skillet to stove, reduce to medium heat. Add oil into middle of skillet.","images":[],"step":5},{"description":"Add Sui mi ya cai and stir for 30 seconds, just to warm through. Set aside.","duration":0.5,"images":[],"step":6},{"description":"Noodles & choi sum:","images":[],"step":7},{"description":"Bring a large pot of water to the boil. Cook noodles per packet directions.","images":[],"step":8},{"description":"Add choi sum for last 1 minute of cooking.","images":[],"step":9},{"description":"Ladle 1/4 of Dan Dan Sauce into a bowl. Pile in noodles, top with pork and Sui mi ya cai. Place choi sum on side.","images":[],"step":10},{"description":"Sprinkle with peanuts and green onions and serve.","images":[],"step":11},{"description":"To eat, mix it all up to coat the noodles well with Sauce, then devour!","images":[],"step":12}]', '["gluten","mustard","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["American Chinese","Sichuan","Szechuan"],"categories":["asian-recipes","chinese-recipes","iconic-dishes","modern-asian","noodles"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0a43dbd28272', 'en', 'US', 'Saucy Vegetable Stir Fry', 'Recipe video above. Any vegetables are totally scoffable when they''re smothered in a tasty Chinese gravy! Use any veg you want - just add them according to the cook time (hard veg in first, leafy veg in last). For a quick hit of protein, toss in some cubes of firm tofu. For a chicken version, use this Chicken Stir Fry. Recipe works with Charlie - see Note 4.', 'https://www.recipetineats.com/tachyon/2020/01/Vegetable-Stir-Fry_9.jpg', 10, 5, 15, 4, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_buk_choy", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp vegetable oil","2 garlic cloves (, finely chopped)","1 tbsp ginger (, finely sliced (optional))","1/2 onion (, peeled and sliced)","1 carrot (, large)","3 medium buk choy ( or other leafy greens of choice (Note 1))","1 cup mushrooms (, sliced 3mm / 1/8\" thick)","1 capsicum (, sliced 1/2cm / 1/5\" thick)"]},{"ingredients":["1 tbsp cornflour / corn starch","1 1/2 tbsp soy sauce (, light or all purpose (not dark soy) (Note 2))","2 tsp Oyster Sauce","1 tbsp Chinese Cooking Wine or Mirin (Note 3)","1/2 tsp sesame oil (optional)","Dash of white pepper (or black)","3/4 cup / 185 ml water"],"purpose":"Sauce (or use 4 tbsp Charlie, Note 4):"},{"ingredients":["Finely sliced green onions","Sesame seeds"],"purpose":"Garnishes, optional:"}]', '[{"description":"Vegetable Prep:","images":[],"step":1},{"title":"Carrot","description":"cut in half lengthwise then diagonally sliced 2mm / 1/10\" thick","images":[],"step":2},{"title":"Buk Choy (Note 1)","description":"Trim base off, then cut leaves off the stem. Cut the stem lengthwise into 1cm / 2/5\" wide pieces. Keep leaves separate from stems, they will be cooked at different times.","images":[],"step":3},{"title":"Sauce (Charlie","description":"Note 4):","images":[],"step":4},{"description":"Place cornflour and soy sauce in a bowl and mix until cornflour is dissolved, then mix in remaining Sauce ingredients.","images":[],"step":5},{"description":"Cooking:","images":[],"step":6},{"description":"Heat oil in a wok or large heavy based skillet over high heat.","images":[],"step":7},{"description":"Add garlic and ginger, stir for 10 seconds. Add onion, stir for 30 seconds.","duration":0.16666666666666666,"images":[],"step":8},{"title":"Add carrot, capsicum and stems of buk choy","description":"stir for 1 minute.","duration":1,"images":[],"step":9},{"description":"Add mushrooms, then stir for 2 to 3 minutes until the vegetables are almost cooked.","duration":2.5,"images":[],"step":10},{"description":"Add Sauce and toss for 1 minute until Sauce thickens and becomes glossy, coating all the vegetables. Don''t overcook so they become floppy and limp - they should be just cooked, \"crisp tender\".","duration":1,"images":[],"step":11},{"description":"Remove from stove and serve over rice (low carb option: cauliflower rice). Garnish with green onions and sesame seeds if using. A big dollop of chilli sauce wouldn''t go astray either!","images":[],"step":12}]', '["gluten","sesame","soy"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-greens","asian-recipes","asian-takeout","chinese-recipes","dietary","gluten-free-recipes","low-calorie-recipes","mains","quick-and-easy","side-dishes","stir-fries","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_43bd74ad9828', 'en', 'US', 'Vietnamese Pho recipe', 'Recipe video above. Experience the magic of one of the greatest soups in the world with this easy to follow traditional recipe! The depth of flavour in the broth will blow you away - it looks so clear and light but it''s packed with flavour.Getting enough flavour and light-richness into the soup broth calls for the right combination of meat AND bones. You can''t just use bones (even really meaty ones), the soup just lacks flavour. I tried multiple times. Use the leftover cooked brisket to make Caramelised Vietnamese Pulled Beef (it''s so good!) and see in post for more ways to use it.Next time - try Chicken Pho! It''s amazing, and quicker to make. :)', 'https://www.recipetineats.com/tachyon/2019/04/Beef-Pho_6.jpg', 20, 180, 200, 6, '[{"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_star_anise", "quantity": {"value": 0.025, "unit": "jar"}}, {"id": "ing_cinnamon_quill", "quantity": {"value": 0.01, "unit": "jar"}}, {"id": "ing_cardamon_pods", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_beef_brisket", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_marrow_bones_cut_to_reveal_marrow", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 3.5, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 40.0, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 0.1, "unit": "pack"}}, {"id": "ing_beef", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_brisket_slices", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_beansprouts_handful", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}]', '[{"ingredients":["2 large onions (, halved)","150g / 5oz ginger (, sliced down the centre)"],"purpose":"Aromatics:"},{"ingredients":["10 star anise","4 cinnamon quills","4 cardamon pods","3 cloves (the spice cloves!)","1.5 tbsp coriander seeds"],"purpose":"Spices"},{"ingredients":["1.5kg / 3lb beef brisket","1kg / 2lb meaty beef bones","1kg / 2lb marrow bones ((leg, knuckle), cut to reveal marrow)","3.5 litres / 3.75 quarts water (15 cups)"],"purpose":"Beef bones (Note 1):"},{"ingredients":["2 tbsp white sugar","1 tbsp salt","40 ml / 3 tbsp fish sauce (Note 2)"],"purpose":"Seasoning:"},{"ingredients":["50g / 1.5 oz dried rice sticks (or 120g/4oz fresh) (Note 3)","30g / 1 oz beef tenderloin, raw, very thinly sliced (Note 4)","3 - 5 brisket slices (used for broth)"],"purpose":"Noodle Soup – PER BOWL:"},{"ingredients":["Beansprouts, handful","Thai basil, 3 - 5 sprigs","Coriander/cilantro, 3 - 5 sprigs (or more basil)","Lime wedges*","Finely sliced red chilli*","Hoisin sauce*","Sriracha* (for spiciness)"],"purpose":"Toppings:"}]', '[{"description":"Heat a heavy based skillet over high heat (no oil) until smoking.","images":[],"step":1},{"description":"Place onion and ginger in pan cut side down. Cook for a few minutes until it''s charred, then turn. Remove and set aside.","images":[],"step":2},{"description":"Toast Spices lightly in a dry skillet over medium high heat for 3 minutes.","duration":3,"images":[],"step":3},{"description":"Remove impurities:","images":[],"step":4},{"description":"Rinse bones & brisket then cover with water in large stock pot.","images":[],"step":5},{"description":"Boil for 5 minutes, then drain.","duration":5,"images":[],"step":6},{"description":"Rinse each bone and brisket under tap water.","images":[],"step":7},{"description":"Wipe pot clean, bring 3.5 litres / 3.75 quarts water to boil.","images":[],"step":8},{"description":"Add bones and brisket, onion, ginger, Spices","images":[],"step":9},{"title":"Add onion, ginger, Spices, sugar and salt","description":"water should just barely cover everything.","images":[],"step":10},{"description":"Cover with lid, simmer 3 hours.","images":[],"step":11},{"description":"Remove brisket (should be fall-apart tender), cool then refrigerate for later.","images":[],"step":12},{"description":"Simmer remaining soup UNCOVERED for 40 minutes.","duration":40,"images":[],"step":13},{"description":"Strain broth into another pot, discard bones and spices. Should be about 2.5 litres / 2.65 quarts (10 cups), if loads more, reduce.","images":[],"step":14},{"description":"Add fish sauce, adjust salt and sugar if needed. Broth should be beefy, fragrant with spices, savoury and barely sweet.","images":[],"step":15},{"description":"Prepare rice noodles per packet, just prior to serving.","images":[],"step":16},{"description":"Place noodles in bowl. Top with raw beef and brisket.","images":[],"step":17},{"title":"Ladle over about 400 / 14 oz hot broth","description":"will cook beef to medium rare.","images":[],"step":18},{"description":"Serve with Toppings on the side!","images":[],"step":19}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","asian-soups","beef-recipes","iconic-dishes","soup-recipes","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a0e0746cfb8d', 'en', 'US', 'Pad Thai', 'Recipe video above. Here''s a Pad Thai recipe that really does taste just as good as takeout from good Thai restaurants, and you''ll find everything you need at the supermarket! I use chicken here but feel free to switch with any protein, even prawns/shrimp. If you''re after a truly authentic Pad Thai recipe, see here - but be warned that most people will find it a little too "real" for their palettes because Pad Thai in Thailand has stronger fish sauce/dried shrimp "funk". (Don''t misread that word! :))', 'https://www.recipetineats.com/tachyon/2018/05/Chicken-Pad-Thai_9.jpg', 20, 10, 30, 2, '[{"id": "ing_rice", "quantity": {"value": 0.25, "unit": "pack"}}, {"id": "ing_tamarind_puree", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 0.15, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_beansprouts", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_tofu", "quantity": {"value": 1.0, "unit": "pack of 300g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_peanuts", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_more_beansprouts", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["125 g / 4oz Chang''s Pad Thai dried rice sticks (Note 1)"]},{"ingredients":["1 1/2 tbsp tamarind puree (, NOT concentrate (Note 2))","3 tbsp (packed) brown sugar","2 tbsp fish sauce (Note 3)","1 1/2 tbsp oyster sauce (Note 4)"],"purpose":"Sauce:"},{"ingredients":["2 - 3 tbsp vegetable or canola oil","1/2 onion (, sliced (brown, yellow))","2 garlic cloves (, finely chopped)","150 g/5oz chicken breast (or thigh) (, thinly sliced)","2 eggs (, lightly whisked)","1 1/2 cups of beansprouts","1/2 cup firm tofu, cut into 3cm / 1 1/4\" batons (see photo)","1/4 cup garlic chives , cut into 3cm / 1 1/4\" pieces","1/4 cup finely chopped peanuts"],"purpose":"Stir Fry:"},{"ingredients":["Lime wedges (essential)","Ground chilli or cayenne pepper (optional)","More beansprouts"],"purpose":"For serving:"}]', '[{"description":"Place noodles in a large bowl, pour over plenty of boiling water. Soak for 5 minutes, then drain in a colander and quickly rinse under cold water. Don''t leave them sitting around for more than 5 - 10 minutes.","duration":5,"images":[],"step":1},{"description":"Mix Sauce in small bowl.","images":[],"step":2},{"description":"Heat 2 tbsp oil in a large non stick pan (or well seasoned skillet) over high heat. Add garlic and onion, cook for 30 seconds.","duration":0.5,"images":[],"step":3},{"description":"Add chicken and cook for 1 1/2 minutes until mostly cooked through.","images":[],"step":4},{"description":"Push to one side of the pan, pour egg in on the other side. Scramble using the wooden spoon (add touch of extra oil if pan is too dry), then mix into chicken.","images":[],"step":5},{"description":"Add bean sprouts, tofu, noodles then Sauce.","images":[],"step":6},{"description":"Toss gently for about 1 1/2 minutes until Sauce is absorbed by the noodles.","images":[],"step":7},{"description":"Add garlic chives and half the peanuts. Toss through quickly then remove from heat.","images":[],"step":8},{"description":"Serve immediately, sprinkled with remaining peanuts and lime wedges on the side, with a sprinkle of chilli and a handful of extra beansprouts on the side if desired (this is the Thai way!). Squeeze over lime juice to taste before eating.","images":[],"step":9}]', '["egg","fish","gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","cuisines","noodles","quick-and-easy","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a24a8884f9ef', 'en', 'US', 'Lo Mein Noodles', 'Recipe video above. If you want lip smackingly delicious Lo Mein noodles just like takeout, you just need to get the SAUCE right! The noodle part is easy - you can literally use any noodles, even pasta (yep, seriously). Also, switch out the vegetables with 5 cups (packed) of any chopped vegetables of choice.', 'https://www.recipetineats.com/tachyon/2019/11/Lo-Mein_5.jpg', 8, 7, 15, 3, '[{"id": "ing_oil", "quantity": {"value": 0.09, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 6.0, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.05, "unit": "pack of 400g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.5 tbsp vegetable or peanut oil","2 garlic cloves (, finely minced (Note 1))","1/2 onion (, finely sliced)","300g / 10oz chicken or other protein (, sliced 0.5cm / 1/5\" thick (Note 2))","2 medium carrots (, peeled and cut into 4 x 0.75cm / 1.75 x 1/3\" batons)","1 large red capsicum / bell pepper (, sliced (or 2 small))","6 green onions (, cut into 5 cm/2” lengths)","500g / 1lb Lo Mein, Hokkien or other medium thickness egg noodles, fresh, (, prepared per packet (Note 3 for dried))","1/4 cup (65ml) water"]},{"ingredients":["4 tsp cornflour / cornstarch","2 tbsp dark soy sauce (Note 4)","2 tbsp soy sauce or light soy sauce ( (Note 4))","1 tbsp Chinese cooking wine or Mirin (Note 5 subs)","1 tsp white sugar (omit if using Mirin)","1/2 tsp sesame oil (, toasted, optional (Note 6))","1/4 tsp white pepper (sub black)"],"purpose":"Sauce:"},{"ingredients":["Green onion (, finely sliced)"],"purpose":"Garnish (optional):"}]', '[{"title":"Sauce","description":"Mix cornflour and dark soy until lump free, then add remaining Sauce ingredients.","images":[],"step":1},{"title":"Season Chicken","description":"Transfer 2 tsp Sauce into bowl with chicken. Toss to coat.","images":[],"step":2},{"description":"Heat oil in a wok or large heavy based skillet over high heat until smoking.","images":[],"step":3},{"description":"Add onion and garlic, stir 30 seconds.","images":[],"step":4},{"description":"Add chicken, stir until white on the outside, still raw inside - 1 minute.","images":[],"step":5},{"description":"Add carrot and capsicum/bell peppers, cook 2 minutes or until chicken is cooked.","images":[],"step":6},{"description":"Add noodles, Sauce and water. Use 2 wooden spoons and toss for 30 seconds.","duration":0.5,"images":[],"step":7},{"description":"Add green onions, toss for another 1 minute until all the noodles are slick with sauce.","images":[],"step":8},{"description":"Serve immediately, garnished with extra green onions if using.","images":[],"step":9}]', '["egg","gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese","Asian","Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dinner-tonight","main-dishes","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_69ddfa114ba2', 'en', 'US', 'Chicken Fried Rice', 'Recipe video above. A fully loaded, completely delicious Chicken Fried Rice! Serve it as a side - or have it as a main! (See here for a classic side dish Fried Rice).', 'https://www.recipetineats.com/tachyon/2019/09/Chicken-fried-rice-copy.jpg', 10, 10, 20, 4, '[{"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.6, "unit": "pack of 200g"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_white_rice", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.075, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 tbsp oil (, peanut, vegetable or canola)","2 eggs (, lightly whisked)","150g (5oz) chicken breast (, finely sliced into small pieces)","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","120g (4oz) bacon (, excess fat trimmed, chopped (Note 1))","1 small carrot* (, peeled and diced 0.75cm / 1/3\")","1/2 cup frozen corn* (or can or fresh)","1/2 cup frozen peas*","2 cups (packed) cooked white rice (, day old (Note 2))","3/4 cup green onions (, finely sliced)"]},{"ingredients":["2.5 tbsp Chinese cooking wine or Mirin (Note 3)","1 tbsp oyster sauce (Note 4)","3 tbsp light soy sauce (Note 5)","1/2 tsp sesame oil (, optional)","1/4 tsp white pepper (, optional)"],"purpose":"SAUCE:"}]', '[{"title":"Sauce & chicken","description":"Mix Sauce in a bowl. Pour 2 tsp over chicken, toss to coat, then set aside for 10 minutes.","duration":10,"images":[],"step":1},{"title":"Egg","description":"Heat 1 tbsp oil in a wok or skillet over medium heat. Add egg and scramble until just cooked (still a touch wet) then remove.","images":[],"step":2},{"title":"Fried Rice","description":"Turn heat up to high, add remaining 1/2 tbsp oil and bacon into same skillet. Cook for 1 minute or so until fat starts to melt, then add onion and garlic.","duration":1,"images":[],"step":3},{"title":"Cook until bacon is light golden","description":"about 1 1/2 minutes.","images":[],"step":4},{"description":"Add vegetables (still frozen is fine). Cook for 1 minute.","duration":1,"images":[],"step":5},{"description":"Add chicken and cook until it changes from pink to white - about 1 1/2 minutes.","images":[],"step":6},{"description":"Add rice and Sauce ingredients. Cook for 1 1/2 minutes, stirring consantly.","images":[],"step":7},{"description":"Add egg and green onion, toss through to disperse then remove from heat.","images":[],"step":8},{"description":"Serve immediately!","images":[],"step":9}]', '["egg","gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","fried-rice","quick-and-easy","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
